// ─── Sync imported HTML table → employee.records (Excel → table → array chain) ───

function renderImportedTable(rows) {
  const tbody = document.getElementById('importedDataBody');
  tbody.innerHTML = '';
  rows.forEach(r => {
    const tr = document.createElement('tr');
    
    // Determine status text
    let statusText = r.entry ? 'دوام' : 'غياب';
    if (r.status) {
      const s = STATUSES.find(st => st.value === r.status);
      statusText = s ? s.label : r.status;
    }

    tr.innerHTML = `
      <td>${r.name}</td>
      <td>${r.date}</td>
      <td>${r.entry}</td>
      <td>${r.exit}</td>
      <td>${formatNum(r.advance)}</td>
      <td>${formatNum(r.penalty)}</td>
      <td><span class="status-badge ${r.entry || r.status ? 'active' : 'inactive'}">${statusText}</span></td>
    `;
    tbody.appendChild(tr);
  });
}

// ─── Attendance Calendar Logic ───
const CALENDAR_DAY_NAMES = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, ch => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;'
  }[ch]));
}

function getRecordHours(rec) {
  if (!rec) return 0;
  if (Number(rec.hours) > 0) return Number(rec.hours);
  if (rec.checkInMin != null && rec.checkOutMin != null) {
    const minutes = rec.checkOutMin > rec.checkInMin
      ? rec.checkOutMin - rec.checkInMin
      : (24 * 60 - rec.checkInMin) + rec.checkOutMin;
    return Math.round((minutes / 60) * 100) / 100;
  }
  return 0;
}

function isCalendarAttendanceRecord(rec) {
  if (!rec) return false;
  const status = normalizeStatus(rec.status);
  if (status === 'leave' || status === 'absent') return false;
  return !!rec.checkIn || isWorkStatus(status);
}

function getRecordDateObject(rec) {
  const y = Number(rec?.year);
  const m = Number(rec?.month);
  const d = Number(rec?.day);
  if (!y || !m || !d) return null;
  return new Date(y, m - 1, d);
}

function isActualAttendanceDataRecord(rec) {
  if (!rec) return false;
  return !!(rec.checkIn || rec.checkOut || rec.checkInMin != null || rec.checkOutMin != null || rec.managerApproved || rec.attendanceCorrected);
}

// Single source of truth for "what's the newest day we actually have real
// attendance data for". Never looks past today (a record dated in the future
// isn't a real update yet). Shared by the freshness banner AND the calendar's
// actual/forecast cutoff below — both must agree on the same anchor date.
function findLatestActualAttendanceRecord() {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  let latest = null;
  employees.forEach(emp => {
    (emp.records || []).forEach(rec => {
      if (!isActualAttendanceDataRecord(rec)) return;
      const dt = getRecordDateObject(rec);
      if (!dt || Number.isNaN(dt.getTime()) || dt > today) return;
      if (!latest || dt > latest.date) latest = { date: dt, rec, emp };
    });
  });
  return latest;
}

// The forecast cutoff anchor (requirement: lastCompleteAttendanceUpdateDate /
// lastCompleteDatabaseUpdateDate). An admin can pin this manually via
// omni.adminSettings.lastCompleteAttendanceUpdateDate (ISO date string) when
// the last full import doesn't line up with the newest single record (e.g. a
// bulk import that was verified complete through a specific date). Absent an
// override, it's derived from the newest actual attendance record. Returns
// null only when there has never been any real attendance data at all — in
// that case every day, in every month, is forecast-eligible.
function getAttendanceUpdateCutoffDate() {
  const manual = omni?.adminSettings?.lastCompleteAttendanceUpdateDate || omni?.adminSettings?.lastCompleteDatabaseUpdateDate;
  if (manual) {
    const parsed = parseEmployeeLifecycleDate(manual);
    if (parsed) return parsed;
  }
  const latest = findLatestActualAttendanceRecord();
  return latest ? latest.date : null;
}

// A day is forecast-eligible when it falls strictly after the cutoff anchor
// (or when there's no anchor at all yet, e.g. a brand-new install with zero
// imported attendance). Days on/before the cutoff are never auto-forecast —
// if they're empty, that's either a confirmed zero or a genuine data gap,
// never a "day hasn't happened yet" situation. This deliberately does NOT
// compare against today's wall-clock date — the cutoff can be weeks behind
// today if the last import lagged, and every one of those in-between days
// must still forecast rather than render as a confirmed zero.
function isCalendarDayForecastEligible(year, month, day) {
  const cutoff = getAttendanceUpdateCutoffDate();
  if (!cutoff) return true;
  const target = new Date(year, month - 1, day);
  return target > cutoff;
}

function getAttendanceDataFreshness() {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const latest = findLatestActualAttendanceRecord();
  if (!latest) {
    return {
      status: 'missing',
      title: 'لا توجد بيانات حضور فعلية',
      detail: 'يمكن فتح الصفحة، لكن يجب استيراد أو تحديث التايم شيت قبل الاعتماد على الحسابات.',
      dateLabel: '-',
      ageLabel: 'غير محدد'
    };
  }
  const daysOld = Math.floor((today - latest.date) / (24 * 60 * 60 * 1000));
  const dateLabel = `${latest.date.getFullYear()}-${String(latest.date.getMonth() + 1).padStart(2, '0')}-${String(latest.date.getDate()).padStart(2, '0')}`;
  const ageLabel = daysOld === 0 ? 'اليوم' : daysOld === 1 ? 'منذ يوم واحد' : `منذ ${daysOld} أيام`;
  const status = daysOld > 7 ? 'stale' : 'fresh';
  return {
    status,
    title: status === 'fresh' ? 'بيانات الحضور محدثة' : 'بيانات الحضور قديمة',
    detail: status === 'fresh'
      ? `آخر تحديث فعلي للبيانات في ${dateLabel} (${ageLabel}).`
      : `آخر تحديث فعلي للبيانات في ${dateLabel} (${ageLabel}). الأيام التي بعده تُعرض كتنبؤ وليست صفراً فعلياً، إلى أن يتم استيراد بياناتها.`,
    dateLabel,
    ageLabel,
    daysOld
  };
}

// ─── Payroll month close/reopen (requirement: "closed" day-calc mode) ───
// A closed month is frozen: actual records already recorded still display
// normally, but forecast projection stops entirely (no speculative rows, no
// auto-recompute) until explicitly reopened. Stored as a flat list of
// "YYYY-MM" keys — deliberately NOT nested under workshopOperatingCosts or
// any other settings blob, so it can't be silently wiped by an unrelated
// partial write to those.
function monthKeyOf(year, month) {
  return `${year}-${String(month).padStart(2, '0')}`;
}

function getClosedPayrollMonthsSet() {
  const raw = omni?.adminSettings?.closedPayrollMonths;
  return new Set(Array.isArray(raw) ? raw : []);
}

function isPayrollMonthClosed(year, month) {
  return getClosedPayrollMonthsSet().has(monthKeyOf(year, month));
}

window.setPayrollMonthClosed = function(year, month, closed) {
  if (window.PermissionService && !window.PermissionService.check('employees', 'update')) {
    if (typeof showToast === 'function') showToast('لا تملك صلاحية إغلاق أو إعادة فتح الشهر', 'error');
    return;
  }
  if (!omni) return;
  if (!omni.adminSettings) omni.adminSettings = {};
  const set = getClosedPayrollMonthsSet();
  const key = monthKeyOf(year, month);
  if (closed) set.add(key); else set.delete(key);
  omni.adminSettings.closedPayrollMonths = Array.from(set);
  saveData();
  if (typeof showToast === 'function') {
    showToast(closed ? `تم إغلاق شهر ${MONTHS_AR[month - 1]} ${year} — لا مزيد من التوقعات حتى إعادة الفتح` : `تمت إعادة فتح شهر ${MONTHS_AR[month - 1]} ${year}`, 'success');
  }
  if (typeof renderAttendanceCalendar === 'function') renderAttendanceCalendar();
};

// Single classification for a calendar day, per the requirement's four
// modes. Priority order matters: an actually-recorded day always wins (even
// a Friday with approved overtime), Friday/weekly-off is checked before the
// forecast cutoff (a Friday never gets a normal payroll forecast — see
// getCalendarDayData), and only then does the cutoff decide forecast vs a
// pre-cutoff gap.
function getCalendarDayMode(year, month, day, { hasActualRows, isFridayDay, monthClosed }) {
  if (monthClosed) return 'closed';
  if (hasActualRows) return 'actual';
  if (isFridayDay) return 'weekly_off';
  if (isCalendarDayForecastEligible(year, month, day)) return 'forecast';
  const hasExpectedStaff = employees.some(emp => isEmployeeActiveOnDate(emp, year, month, day));
  return hasExpectedStaff ? 'missing' : 'actual';
}

const CALENDAR_DAY_MODE_LABELS = {
  actual: 'فعلي',
  forecast: 'تنبؤي',
  closed: 'مغلق',
  weekly_off: 'يوم عطلة',
  missing: 'بيانات ناقصة'
};

const CALENDAR_DAY_MODE_ICONS = {
  actual: 'fa-circle-check',
  forecast: 'fa-wand-magic-sparkles',
  closed: 'fa-lock',
  weekly_off: 'fa-mug-hot',
  missing: 'fa-triangle-exclamation'
};

function renderAttendanceFreshnessBanner(pageId, anchorSelector) {
  const page = document.getElementById(pageId);
  if (!page) return;
  let banner = page.querySelector('.attendance-freshness-banner');
  if (!banner) {
    banner = document.createElement('div');
    banner.className = 'attendance-freshness-banner';
    const anchor = page.querySelector(anchorSelector);
    if (anchor) anchor.insertAdjacentElement('beforebegin', banner);
    else page.prepend(banner);
  }
  const info = getAttendanceDataFreshness();
  banner.className = `attendance-freshness-banner freshness-${info.status}`;
  const icon = info.status === 'fresh' ? 'fa-circle-check' : info.status === 'stale' ? 'fa-triangle-exclamation' : 'fa-circle-info';
  banner.innerHTML = `
    <div class="freshness-icon"><i class="fa-solid ${icon}"></i></div>
    <div>
      <strong>${escapeHtml(info.title)}</strong>
      <span>${escapeHtml(info.detail)}</span>
    </div>
  `;
}

// getDefaultWorkshopOperatingCostItems() moved to modules/data-providers.js (GO 16 de-monolith Phase 2)

function getWorkshopOperatingCostSettings() {
  const defaults = getDefaultWorkshopOperatingCostItems();
  if (!omni || typeof omni !== 'object') return { monthlyItems: defaults };
  if (!omni.adminSettings || typeof omni.adminSettings !== 'object') omni.adminSettings = {};
  const settings = omni.adminSettings.workshopOperatingCosts || {};
  const savedItems = Array.isArray(settings.monthlyItems) ? settings.monthlyItems : [];
  const savedById = Object.fromEntries(savedItems.map(item => [item.id, item]));
  const monthlyItems = defaults.map(item => ({
    ...item,
    ...(savedById[item.id] || {}),
    amount: Number(savedById[item.id]?.amount ?? item.amount) || 0,
    active: savedById[item.id]?.active !== false
  }));
  savedItems
    .filter(item => item && item.id && !monthlyItems.some(defaultItem => defaultItem.id === item.id))
    .forEach(item => monthlyItems.push({ ...item, amount: Number(item.amount) || 0, active: item.active !== false }));
  return { ...settings, monthlyItems };
}

// How many days in the month actually have staffing — either real recorded
// attendance, or (past the forecast cutoff) at least one employee expected
// to be active. Used only by the 'attendance_days' allocation basis. Falls
// back to 1 so a division by it never produces Infinity on a month with no
// staffing signal at all.
function getMonthStaffedDayCount(year, month) {
  const daysInMonth = getDaysInMonth(year, month);
  let count = 0;
  for (let d = 1; d <= daysInMonth; d++) {
    if (isFriday(year, month, d)) continue;
    const hasActual = employees.some(emp => (emp.records || []).some(rec =>
      recordBelongsToMonth(rec, year, month) && Number(rec.day) === d && (isCalendarAttendanceRecord(rec) || rec.managerApproved)
    ));
    if (hasActual) { count++; continue; }
    if (isCalendarDayForecastEligible(year, month, d) && employees.some(emp => isEmployeeActiveOnDate(emp, year, month, d))) count++;
  }
  return Math.max(count, 1);
}

// Fixed operating costs (rent, internet, electricity...) each carry their own
// allocation basis — how their monthly amount gets spread across days. This
// replaces the old single global "divide by working days" rule: fixed
// overhead must keep showing up even on days with zero attendance, which
// only 'calendar_days' (the new default) guarantees.
//   calendar_days   — every day of the month, Friday included.
//   working_days     — every non-Friday day only (old default behaviour);
//                       Friday's share is rolled into the weekly figure.
//   attendance_days   — only on days with real/forecast staffing.
//   manual            — counted in the monthly total, but never auto-spread
//                       into a daily figure (the admin accounts for it
//                       elsewhere).
function getWorkshopOperatingCostBreakdown(year, month) {
  const daysInMonth = getDaysInMonth(year, month);
  const fridayCount = getFridaysInMonth(year, month).length;
  const workingDaysInMonth = Math.max(daysInMonth - fridayCount, 1);
  const staffedDaysInMonth = getMonthStaffedDayCount(year, month);
  const settings = getWorkshopOperatingCostSettings();
  const monthKey = `${year}-${String(month).padStart(2, '0')}`;

  const items = settings.monthlyItems.map(item => {
    const actualRecord = item.actuals ? item.actuals[monthKey] : null;
    const isVerified = actualRecord ? actualRecord.verified === true : false;
    const defaultVal = Number(item.amount) || 0;
    const actualVal = actualRecord ? (Number(actualRecord.amount) || 0) : defaultVal;

    // Amount to use in calculations: actual if verified, default estimate if not verified
    const amountToUse = isVerified ? actualVal : defaultVal;
    const allocationBasis = item.allocationBasis || 'calendar_days';

    return {
      ...item,
      defaultAmount: defaultVal,
      actualAmount: actualVal,
      isVerified: isVerified,
      amountToUse: amountToUse,
      allocationBasis,
      perCalendarDay: amountToUse / daysInMonth,
      perWorkingDay: amountToUse / workingDaysInMonth,
      perAttendanceDay: amountToUse / staffedDaysInMonth,
      paymentDate: actualRecord?.paymentDate || '',
      paymentSource: actualRecord?.paymentSource || '',
      paidBy: actualRecord?.paidBy || ''
    };
  });

  const activeItems = items.filter(item => item.active !== false);
  const monthlyTotal = activeItems.reduce((sum, item) => sum + item.amountToUse, 0);

  // Legacy aggregate figures — still meaningful as a single "all items,
  // spread over working days" summary number for callers that don't need
  // the per-day/per-basis breakdown (e.g. the payroll forecast card).
  const dailyShare = monthlyTotal / workingDaysInMonth;

  return {
    items: activeItems,
    monthlyTotal,
    daysInMonth,
    fridayCount,
    workingDaysInMonth,
    staffedDaysInMonth,
    dailyShare,
    // Friday itself carries no daily share (it's not a working day for this
    // purpose) — instead the whole week's worth (6 working days) is rolled
    // up and shown once, on Friday, as a distinct "weekly" figure.
    weeklyShare: dailyShare * 6,
    configured: monthlyTotal > 0
  };
}

// Per-day operating cost share, respecting each item's own allocation basis.
// isStaffedDay must reflect actual-or-forecast staffing for THIS specific
// day (not the month-wide count above), so 'attendance_days' items track the
// real presence pattern day by day rather than a flat average.
function getOperatingCostShareForDay(operatingCost, isFridayDay, isStaffedDay) {
  return operatingCost.items.reduce((sum, item) => {
    switch (item.allocationBasis) {
      case 'working_days':
        return sum + (isFridayDay ? 0 : item.perWorkingDay);
      case 'attendance_days':
        return sum + (isStaffedDay ? item.perAttendanceDay : 0);
      case 'manual':
        return sum; // entered/accounted for directly elsewhere, never auto-spread
      case 'calendar_days':
      default:
        return sum + item.perCalendarDay;
    }
  }, 0);
}

// The "look back at this past week" convenience figure shown only on
// Friday's card. Only 'working_days' items belong here — 'calendar_days'
// items already collected their own share on Friday itself via
// getOperatingCostShareForDay, so including them again here would double
// them. 'attendance_days'/'manual' items aren't rolled up weekly at all.
function getOperatingCostWeeklyShare(operatingCost) {
  return operatingCost.items.reduce((sum, item) => sum + (item.allocationBasis === 'working_days' ? item.perWorkingDay * 6 : 0), 0);
}

// Sums each employee's netDue (wages due, advances already excluded — see
// getEmployeeDailyFinancialSummary) for the 6 working days preceding a
// Friday, so the Friday "weekly" rollup can include labor cost, not just
// rent/operating cost. Skips any day that falls before day 1 (partial week
// at the start of a month) rather than reaching into the previous month.
function getWeeklyLaborCost(year, month, fridayDay) {
  const cfg = { ...getConfig(), year, month };
  let total = 0;
  for (let d = fridayDay - 6; d <= fridayDay - 1; d++) {
    if (d < 1) continue;
    employees.forEach(emp => {
      const rec = (emp.records || []).find(r => recordBelongsToMonth(r, year, month) && r.day === d);
      if (!rec || (!isCalendarAttendanceRecord(rec) && !rec?.managerApproved)) return;
      total += getEmployeeDailyFinancialSummary(emp, rec, cfg).netDue;
    });
  }
  return total;
}

function isFutureCalendarDay(year, month, day) {
  const today = new Date();
  const target = new Date(year, month - 1, day);
  const current = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  return target > current;
}

function getCalendarDayData(year, month, day) {
  const cfg = { ...getConfig(), year, month };
  const date = new Date(year, month - 1, day);
  const operatingCost = getWorkshopOperatingCostBreakdown(year, month);
  const rows = employees.map((emp, idx) => {
    const rec = (emp.records || []).find(r => recordBelongsToMonth(r, year, month) && r.day === day);
    if (!isCalendarAttendanceRecord(rec) && !rec?.managerApproved) return null;
    const hours = getRecordHours(rec);
    const statusInfo = getStatusInfo(rec.status);
    const money = getEmployeeDailyFinancialSummary(emp, rec, cfg);
    return {
      empIdx: idx,
      employee: emp,
      name: emp.name,
      rec,
      hours,
      money,
      statusLabel: statusInfo.label,
      statusColor: statusInfo.color
    };
  }).filter(Boolean);
  const actualEmployeeKeys = new Set(rows.map(item => String(item.employee?.id || item.name || item.empIdx)));
  const isFridayDay = isFriday(year, month, day);
  const monthClosed = isPayrollMonthClosed(year, month);
  const mode = getCalendarDayMode(year, month, day, { hasActualRows: rows.length > 0, isFridayDay, monthClosed });
  // A closed month never forecasts (frozen), a Friday never gets a normal
  // payroll forecast (see requirement: weekly-off payroll forecast is zero
  // unless there's actual/approved overtime, which would already be in
  // `rows` and short-circuit mode to 'actual'), and any other day only
  // forecasts once it's past the cutoff anchor — never based on wall-clock
  // "today", so a lagging import doesn't silently render as a confirmed zero.
  const forecastRows = mode === 'forecast'
    ? employees.map((emp, idx) => {
        if (!isEmployeeActiveOnDate(emp, year, month, day)) return null;
        const key = String(emp.id || emp.name || idx);
        if (actualEmployeeKeys.has(key)) return null;
        const money = getEmployeeForecastDailySummary(emp, year, month, day, cfg);
        return {
          empIdx: idx,
          name: emp.name,
          money,
          hours: money.hours,
          statusLabel: 'متوقع',
          statusColor: '#a78bfa',
          isForecast: true
        };
      }).filter(Boolean)
    : [];

  const totalHours = rows.reduce((sum, item) => sum + item.hours, 0);
  const forecastHours = forecastRows.reduce((sum, item) => sum + item.hours, 0);
  const totalPayable = rows.reduce((sum, item) => sum + item.money.payable, 0);
  const totalPenalties = rows.reduce((sum, item) => sum + item.money.penalties, 0);
  const totalAdvances = rows.reduce((sum, item) => sum + item.money.advances, 0);
  const laborDueCost = rows.reduce((sum, item) => sum + item.money.netDue, 0);
  const forecastLaborCost = forecastRows.reduce((sum, item) => sum + item.money.netDue, 0);
  // Fixed operating costs are allocated per their own basis (see
  // getOperatingCostShareForDay) — a 'calendar_days' item (the default) now
  // gets its share on every day including Friday, so rent/internet/etc.
  // never silently disappear just because attendance is zero that day.
  const isStaffedDay = rows.length > 0 || forecastRows.length > 0;
  const operatingShareForDay = getOperatingCostShareForDay(operatingCost, isFridayDay, isStaffedDay);
  // The Friday "look back at the week" rollup only needs 'working_days'
  // items — 'calendar_days' items already got their own share above.
  const weeklyOperatingShare = isFridayDay ? getOperatingCostWeeklyShare(operatingCost) : 0;
  const weeklyLaborShare = isFridayDay ? getWeeklyLaborCost(year, month, day) : 0;
  const weeklyTotalShare = weeklyOperatingShare + weeklyLaborShare;
  const netDailyCost = laborDueCost + forecastLaborCost + operatingShareForDay;
  const lateCount = rows.filter(item => item.rec.checkInMin != null && item.rec.checkInMin > 9 * 60).length;
  const overtimeCount = rows.filter(item => item.hours > 9).length;

  return {
    year,
    month,
    day,
    isFriday: isFridayDay,
    dayName: CALENDAR_DAY_NAMES[date.getDay()],
    mode,
    modeLabel: CALENDAR_DAY_MODE_LABELS[mode],
    modeIcon: CALENDAR_DAY_MODE_ICONS[mode],
    monthClosed,
    rows,
    forecastRows,
    hasForecast: forecastRows.length > 0,
    totalHours,
    forecastHours,
    totalPayable,
    totalPenalties,
    totalAdvances,
    laborDueCost,
    forecastLaborCost,
    operatingCost,
    operatingShareForDay,
    weeklyOperatingShare,
    weeklyLaborShare,
    weeklyTotalShare,
    netDailyCost,
    lateCount,
    overtimeCount
  };
}

function formatCutoffDateLabel(date) {
  if (!date) return 'غير محدد';
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function buildCalendarForecastBasisNote() {
  const cutoff = getAttendanceUpdateCutoffDate();
  return `
    <div class="cal-forecast-basis-note">
      <i class="fa-solid fa-wand-magic-sparkles"></i>
      توقع مبني على آخر تحديث فعلي للبيانات بتاريخ <b>${formatCutoffDateLabel(cutoff)}</b> — ليس صفراً مؤكداً، بل عرض مسبق للموظفين والساعات والكلفة المتوقعة حتى يتم استيراد أو تأكيد الحضور الفعلي لهذا اليوم.
    </div>
  `;
}

// Never render a bare "0 employees / 0 cost" for a day that isn't a
// confirmed actual — each mode gets its own honest explanation instead.
function buildCalendarEmptyDayMessage(dayData) {
  switch (dayData.mode) {
    case 'forecast':
      return `<div class="cal-empty-detail">لا يوجد موظفون نشطون متوقعون لهذا اليوم (تنبؤي) — راجع حالة الموظفين وتواريخ المباشرة/الانفكاك.</div>`;
    case 'missing':
      return `<div class="cal-empty-detail cal-empty-missing"><i class="fa-solid fa-triangle-exclamation"></i> بيانات ناقصة: لم يتم استيراد حضور هذا اليوم بعد، ولا يمكن اعتباره صفر حضور فعلي مؤكد.</div>`;
    case 'weekly_off':
      return `<div class="cal-empty-detail">يوم عطلة (جمعة) — لا يوجد حضور عادي متوقع، إلا إذا وُجد إضافي معتمد من المدير.</div>`;
    case 'closed':
      return `<div class="cal-empty-detail">الشهر مغلق ولا يوجد حضور مسجل لهذا اليوم في السجل الفعلي.</div>`;
    case 'actual':
    default:
      return `<div class="cal-empty-detail">لا يوجد حضور مسجل لهذا اليوم (صفر فعلي مؤكد).</div>`;
  }
}

function renderCalendarDayDetails(dayData) {
  const panel = document.getElementById('calDayDetails');
  if (!panel || !dayData) return;
  const workersHtml = dayData.rows.length
    ? dayData.rows.map(item => `
      <div class="cal-worker-row">
        <div class="cal-worker-main">
          <span class="cal-worker-avatar">${escapeHtml(item.name.slice(0, 2))}</span>
          <div>
            <strong>${escapeHtml(item.name)}</strong>
            <span>${escapeHtml(item.statusLabel)} · ${escapeHtml(item.rec.checkIn || '--:--')} - ${escapeHtml(item.rec.checkOut || '--:--')} ${item.rec.managerApproved ? '<span class="manager-approval-badge">مدير ✓</span>' : ''}</span>
            ${item.rec.managerApproved ? `<small class="calendar-manager-line">اعتماد: ${escapeHtml(item.rec.managerApprovedBy || 'المدير')} · ${escapeHtml(item.rec.managerApprovalNote || '')}${item.rec.attendanceCorrected ? ` · الأصل ${escapeHtml(item.rec.originalInTime || '--:--')} - ${escapeHtml(item.rec.originalOutTime || '--:--')}` : ''}</small>` : ''}
            <small class="calendar-finance-line">إضافي ${formatHoursAsMinutesLabel(item.money.calc.otHours)} · تأخير ${Math.round(item.money.calc.lateMinutes || 0)} دقائق (${formatMoneyReadable(item.money.calc.late)}) · خصومات ${formatMoneyReadable(item.money.penalties)} · سلف ${formatMoneyReadable(item.money.advances)} · مستحق اليوم ${formatMoneyReadable(item.money.netDue)}</small>
          </div>
        </div>
        <div class="cal-worker-hours">${formatHoursAsMinutesLabel(item.hours)}<br><small>${formatMoneyReadable(item.money.payable)}</small></div>
      </div>
    `).join('')
    : buildCalendarEmptyDayMessage(dayData);

  const forecastWorkersHtml = dayData.forecastRows?.length
    ? `
      <div class="cal-forecast-workers-title"><i class="fa-solid fa-wand-magic-sparkles"></i> حضور متوقع غير مسجل بعد</div>
      ${dayData.forecastRows.map(item => `
        <div class="cal-worker-row cal-worker-forecast">
          <div class="cal-worker-main">
            <span class="cal-worker-avatar">${escapeHtml(item.name.slice(0, 2))}</span>
            <div>
              <strong>${escapeHtml(item.name)}</strong>
              <span>متوقع حسب حالة الموظف وتاريخ المباشرة/الانفكاك والشفت</span>
              <small class="calendar-forecast-line">بدلات اليوم داخلة بالحساب: ${formatMoneyReadable(item.money.allowance)} · مستحق متوقع ${formatMoneyReadable(item.money.netDue)}</small>
            </div>
          </div>
          <div class="cal-worker-hours">${formatHoursAsMinutesLabel(item.hours)}<br><small>${formatMoneyReadable(item.money.netDue)}</small></div>
        </div>
      `).join('')}
    `
    : '';

  const operatingItemsHtml = dayData.operatingCost.items.length
    ? dayData.operatingCost.items.map(item => {
        const badgeStyle = item.isVerified
          ? 'background: rgba(16, 185, 129, 0.15); color: #10b981; border: 1px solid rgba(16, 185, 129, 0.3); padding: 1px 4px; border-radius: 4px; font-size: 10px; margin-right: 4px;'
          : 'background: rgba(245, 158, 11, 0.15); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.3); padding: 1px 4px; border-radius: 4px; font-size: 10px; margin-right: 4px;';
        const badgeText = item.isVerified ? 'موثق' : 'مقدّر';
        const tooltip = item.isVerified
          ? `دُفع ${item.paymentDate ? 'بتاريخ ' + item.paymentDate : ''} ${item.paymentSource === 'person_pocket' ? `من جيب ${item.paidBy || 'المالك'}` : 'من قاصة الورشة'}`.trim()
          : 'قيمة تقديرية غير موثقة بعد';
        return `<span style="display: inline-flex; align-items: center; margin-left: 8px;" title="${escapeHtml(tooltip)}">${escapeHtml(item.name)}: <b style="margin: 0 4px;">${formatMoneyReadable(item.amountToUse)}</b> <small style="${badgeStyle}">${badgeText}</small></span>`;
      }).join(' · ')
    : '<span>لم تضبط مبالغ الإيجار والتشغيل الشهرية بعد.</span>';

  panel.innerHTML = `
    <div class="cal-detail-header">
      <div>
        <span class="cal-detail-kicker">${dayData.isFriday ? 'جمعة' : 'يوم دوام'}</span>
        <h3>${dayData.dayName} ${dayData.day} ${MONTHS_AR[dayData.month - 1]} ${dayData.year}</h3>
      </div>
      <div class="cal-detail-badges">
        <span class="cal-mode-badge cal-mode-badge-${dayData.mode}"><i class="fa-solid ${dayData.modeIcon}"></i> ${dayData.modeLabel}</span>
        <div class="cal-detail-total">${dayData.rows.length} موظف</div>
      </div>
    </div>
    ${dayData.mode === 'forecast' ? buildCalendarForecastBasisNote() : ''}
    ${dayData.mode === 'missing' ? `<div class="cal-missing-note"><i class="fa-solid fa-triangle-exclamation"></i> لا توجد بيانات حضور مستوردة لهذا اليوم رغم وجود موظفين نشطين — هذه فجوة بيانات محتملة وليست صفراً فعلياً مؤكداً.</div>` : ''}
    ${dayData.mode === 'closed' ? `<div class="cal-closed-note"><i class="fa-solid fa-lock"></i> هذا الشهر مغلق — لا يتم احتساب توقعات جديدة. استخدم زر "إعادة فتح الشهر" لإعادة تفعيل التوقع.</div>` : ''}
    <div class="cal-detail-stats calendar-finance-stats">
      ${dayData.hasForecast ? `
        <div class="cal-forecast-stat"><span>الموظفون المتوقعون</span><strong>${dayData.forecastRows.length}</strong></div>
        <div class="cal-forecast-stat"><span>ساعات متوقعة</span><strong>${dayData.forecastHours.toFixed(1)}</strong></div>
        <div class="cal-forecast-stat"><span>أجور وبدلات متوقعة</span><strong>${formatMoneyReadable(dayData.forecastLaborCost)}</strong></div>
      ` : ''}
      <div><span>إجمالي الساعات</span><strong>${dayData.totalHours.toFixed(1)}</strong></div>
      <div><span>الموظفون المتواجدون</span><strong>${dayData.rows.length}</strong></div>
      <div><span>الأجور المستحقة قبل الخصم</span><strong>${formatMoneyReadable(dayData.totalPayable)}</strong></div>
      <div><span>الغرامات/الخصومات</span><strong>${formatMoneyReadable(dayData.totalPenalties)}</strong></div>
      <div><span>الأجور المستحقة بعد الخصم</span><strong>${formatMoneyReadable(dayData.laborDueCost)}</strong></div>
      <div><span>السلف المدفوعة منفصلة</span><strong>${formatMoneyReadable(dayData.totalAdvances)}</strong></div>
      <div><span>${dayData.isFriday ? 'تشغيل/إيجار اليوم (جمعة)' : 'تشغيل/إيجار اليوم'}</span><strong>${formatMoneyReadable(dayData.operatingShareForDay)}</strong></div>
      ${dayData.isFriday ? `
        <div class="cal-weekly-opcost-stat"><span>📅 الكلفة الأسبوعية الكاملة (تشغيل + أجور، بدون سلف)</span><strong>${formatMoneyReadable(dayData.weeklyTotalShare)}</strong></div>
      ` : ''}
      <div><span>كلفة اليوم المستحقة</span><strong>${formatMoneyReadable(dayData.netDailyCost)}</strong></div>
    </div>
    <div class="calendar-cost-note">
      <strong>كلفة اليوم = أجور مستحقة بعد الغرامات + حصة تشغيل/إيجار اليوم (كل بند حسب أساس تخصيصه: يومي تقويمي، أيام عمل، أيام حضور، أو يدوي).</strong>
      <span>${dayData.isFriday
        ? 'الجمعة يوم عطلة فلا تُحسب لها حصة تشغيل يومية خاصة بها؛ بدلاً من ذلك تظهر أعلاه الكلفة الأسبوعية الكاملة (أجور ٦ أيام العمل + تشغيل/إيجار الأسبوع) كخانة منفصلة مميّزة. السلف لا تدخل في هذا الرقم إطلاقاً — تبقى معروضة كمدفوعات منفصلة أسفل الصفحة لأنها ليست كلفة حقيقية بل دفعة مقدّمة من مستحقات الموظف.'
        : 'السلف والمشتريات وحركات القاصة لا تدخل في هذه الكلفة، وتبقى معروضة كمدفوعات منفصلة.'}</span>
      <div class="calendar-operating-items" style="display: flex; flex-wrap: wrap; gap: 8px; margin-top: 5px;">${operatingItemsHtml}</div>
    </div>
    <div class="cal-workers-list">${dayData.rows.length ? workersHtml : ''}${forecastWorkersHtml || (!dayData.rows.length ? workersHtml : '')}</div>
  `;
}

function opcItemIcon(id) {
  const icons = {
    rent: 'fa-house', internet: 'fa-wifi', electricity: 'fa-bolt',
    water: 'fa-droplet', diesel: 'fa-gas-pump', chatgpt: 'fa-robot'
  };
  return icons[id] || 'fa-receipt';
}

// Scans the expenses ledger for this month for transactions matching an
// operating-cost item's keywords, so the modal can suggest the actual paid
// amount instead of leaving it to manual re-entry. Excludes transactions this
// same module already posted (sourceId prefix 'opcost_') to avoid a suggestion
// that just echoes back what was already recorded.
function findMatchingExpenseSuggestion(item, monthKey) {
  if (!finance || !Array.isArray(finance.transactions)) return 0;
  const rawTerms = (Array.isArray(item.keywords) && item.keywords.length) ? item.keywords : [item.name];
  const terms = rawTerms.map(t => String(t).toLowerCase()).filter(Boolean);
  if (!terms.length) return 0;
  return finance.transactions
    .filter(tx => tx.type === 'expense' && String(tx.date || '').startsWith(monthKey))
    .filter(tx => !String(tx.sourceId || '').startsWith('opcost_'))
    .filter(tx => {
      const hay = `${tx.description || ''} ${getCategoryName('expense', tx.categoryId) || ''}`.toLowerCase();
      return terms.some(term => hay.includes(term));
    })
    .reduce((sum, tx) => sum + asMoney(tx.amount), 0);
}

window.openMonthlyOperatingCostsModal = async function() {
  ensureOmni();
  ensureFinance();
  const cfg = getConfig();
  const monthKey = `${cfg.year}-${String(cfg.month).padStart(2, '0')}`;
  const settings = getWorkshopOperatingCostSettings();
  // Session-only mirror of in-progress (not yet confirmed) edits, keyed by
  // item id. Populated by syncDraftFromDom() right before any action that
  // re-renders the list (add/delete/undo), so those edits survive the
  // rebuild. Deliberately kept OUT of item.actuals — writing draft values
  // there made an item's saved actuals record exist prematurely, which
  // broke the "no record yet -> show the default estimate" fallback (a
  // real regression: editing another item's default then re-rendering
  // froze an unrelated item's actual-paid field at a stale value instead
  // of tracking further default edits).
  const draftState = {};

  function buildModalHtml() {
    const activeItems = settings.monthlyItems.filter(item => item.active !== false);
    const totalDefault = activeItems.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
    const verifiedCount = activeItems.filter(item => item.actuals?.[monthKey]?.verified).length;

    return `
    <div class="opc-modal-scope">
      <style>
        #omniModalBox.opc-modal-wide { width: 680px !important; max-width: 94vw !important; padding: 28px !important; }
        .opc-modal-scope { direction: rtl; text-align: right; }
        .opc-intro { font-size: 13px; color: var(--text-secondary); margin-bottom: 16px; line-height: 1.8; }
        .opc-summary-bar { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
        .opc-summary-chip { flex: 1; min-width: 150px; background: var(--gradient-card); border: 1px solid var(--border-glass); border-radius: var(--radius-md); padding: 12px 16px; backdrop-filter: blur(12px); }
        .opc-summary-chip span { display: block; font-size: 11px; color: var(--text-secondary); margin-bottom: 5px; }
        .opc-summary-chip strong { font-size: 16px; color: var(--text-primary); }
        .opc-items-list { display: flex; flex-direction: column; gap: 18px; max-height: 52vh; overflow-y: auto; padding: 4px 6px 4px 2px; margin-bottom: 20px; }
        .opc-item-card { background: var(--gradient-card); border: 1px solid var(--border-glass); border-radius: var(--radius-lg); padding: 18px; backdrop-filter: blur(16px); transition: var(--transition); }
        .opc-item-card.opc-is-verified { border-color: rgba(52,211,153,0.35); box-shadow: 0 0 0 1px rgba(52,211,153,0.08), var(--shadow-md); }
        .opc-item-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }
        .opc-item-name { display: flex; align-items: center; gap: 9px; font-size: 15px; color: var(--text-heading); }
        .opc-item-name i { color: var(--accent-blue); width: 18px; text-align: center; font-size: 15px; }
        .opc-locked-badge { font-size: 10.5px; background: rgba(52,211,153,0.15); color: var(--accent-green); border: 1px solid rgba(52,211,153,0.3); padding: 3px 9px; border-radius: 999px; margin-right: 10px; display: inline-flex; align-items: center; gap: 4px; }
        .opc-delete-btn { background: transparent; border: none; color: var(--accent-red); cursor: pointer; padding: 5px 7px; border-radius: 7px; transition: var(--transition); }
        .opc-delete-btn:hover { background: rgba(248,113,113,0.12); }
        .opc-amounts-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-items: start; }
        .opc-field label { display: block; font-size: 11.5px; color: var(--text-secondary); margin-bottom: 5px; }
        .opc-field input.form-input { width: 100%; height: 38px; font-size: 13px; }
        .opc-basis-field { margin-bottom: 14px; }
        .opc-basis-field select.form-input { width: 100%; height: 38px; font-size: 13px; }
        .opc-suggestion-chip { margin-top: 7px; width: 100%; font-size: 11px; background: rgba(56,189,248,0.12); color: var(--accent-blue); border: 1px solid rgba(56,189,248,0.3); border-radius: 999px; padding: 5px 10px; cursor: pointer; display: flex; align-items: center; gap: 6px; justify-content: center; transition: var(--transition); }
        .opc-suggestion-chip:hover { background: rgba(56,189,248,0.22); }
        .opc-toggle-row { display: flex; align-items: center; gap: 12px; margin-top: 14px; padding: 11px 14px; background: rgba(255,255,255,0.02); border: 1px solid var(--border-glass); border-radius: var(--radius-md); cursor: pointer; transition: var(--transition); }
        .opc-toggle-row:hover { background: rgba(255,255,255,0.045); }
        .opc-toggle-switch { position: relative; width: 42px; height: 24px; flex-shrink: 0; }
        .opc-toggle-switch input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; z-index: 1; }
        .opc-toggle-switch input:disabled { cursor: not-allowed; }
        .opc-toggle-track { position: absolute; inset: 0; background: rgba(255,255,255,0.14); border-radius: 999px; transition: var(--transition); }
        .opc-toggle-knob { position: absolute; top: 2px; right: 2px; width: 20px; height: 20px; background: #fff; border-radius: 50%; transition: var(--transition); box-shadow: var(--shadow-sm); }
        .opc-toggle-switch input:checked + .opc-toggle-track { background: var(--accent-green); }
        .opc-toggle-switch input:checked + .opc-toggle-track .opc-toggle-knob { transform: translateX(-18px); }
        .opc-toggle-switch input:disabled + .opc-toggle-track { opacity: 0.6; }
        .opc-toggle-text { font-size: 13px; color: var(--text-primary); font-weight: 500; }
        .opc-verify-panel { display: none; grid-template-columns: 1fr 1fr; gap: 16px; border-top: 1px dashed var(--border-glass); }
        .opc-verify-panel.opc-panel-open { display: grid; margin-top: 16px; padding-top: 16px; animation: opcSlideDown .22s ease; }
        @keyframes opcSlideDown { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: translateY(0); } }
        .opc-radio-row { display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: var(--text-secondary); }
        .opc-radio-row label { display: flex; align-items: center; gap: 7px; cursor: pointer; }
        .opc-radio-row input[type=radio] { accent-color: var(--accent-blue); cursor: pointer; width: 15px; height: 15px; }
        .opc-hidden { display: none !important; }
        .opc-locked-note { grid-column: 1 / -1; font-size: 12.5px; color: var(--text-secondary); background: rgba(52,211,153,0.06); border: 1px solid rgba(52,211,153,0.2); border-radius: var(--radius-sm); padding: 12px 14px; display: flex; flex-direction: column; gap: 6px; }
        .opc-locked-note i { color: var(--accent-green); margin-left: 6px; }
        .opc-undo-btn { align-self: flex-start; margin-top: 4px; font-size: 11.5px; background: rgba(248,113,113,0.1); color: var(--accent-red); border: 1px solid rgba(248,113,113,0.3); border-radius: 999px; padding: 6px 13px; cursor: pointer; display: flex; align-items: center; gap: 6px; transition: var(--transition); }
        .opc-undo-btn:hover { background: rgba(248,113,113,0.2); }
        .opc-empty { text-align: center; color: var(--text-muted); font-size: 13px; padding: 22px; }
        .opc-add-section { border-top: 1px solid var(--border-glass); padding-top: 16px; }
        .opc-add-section h4 { margin: 0 0 12px; font-size: 13.5px; color: var(--text-secondary); }
        .opc-add-row { display: flex; gap: 10px; }
        .opc-add-row input.form-input { height: 38px; font-size: 13px; }
      </style>

      <p class="opc-intro">
        لشهر <strong>${MONTHS_AR[cfg.month - 1]} ${cfg.year}</strong>. البند الموثّق يستخدم القيمة الفعلية المعتمدة، بينما البند غير الموثّق يستخدم القيمة الافتراضية التقديرية في حساب حصة اليوم بالتقويم.
      </p>

      <div class="opc-summary-bar">
        <div class="opc-summary-chip"><span>عدد البنود</span><strong>${activeItems.length}</strong></div>
        <div class="opc-summary-chip"><span>الموثّق هذا الشهر</span><strong style="direction: ltr; unicode-bidi: embed; display: inline-block;">${verifiedCount} / ${activeItems.length}</strong></div>
        <div class="opc-summary-chip"><span>إجمالي الافتراضي الشهري</span><strong>${formatMoneyReadable(totalDefault)}</strong></div>
      </div>

      <div class="opc-items-list" id="modalCostItemsContainer"><!-- Rows injected here --></div>

      <div class="opc-add-section">
        <h4><i class="fa-solid fa-circle-plus"></i> إضافة بند مصروف تشغيلي جديد</h4>
        <div class="opc-add-row">
          <input type="text" id="newCostItemName" class="form-input" placeholder="اسم المصروف (مثال: صيانة دورية)" style="flex: 2;">
          <input type="number" id="newCostItemDefault" class="form-input" placeholder="الافتراضي شهرياً" style="flex: 1;">
          <button type="button" class="btn btn-secondary" onclick="addCostItemFromModal()" style="padding: 0 15px;">إضافة</button>
        </div>
      </div>
    </div>
  `;
  }

  function renderModalCostRows() {
    const container = document.getElementById('modalCostItemsContainer');
    if (!container) return;

    const activeItems = settings.monthlyItems.filter(item => item.active !== false);

    if (activeItems.length === 0) {
      container.innerHTML = `<div class="opc-empty">لا توجد بنود مصاريف مضافة.</div>`;
      return;
    }

    container.innerHTML = activeItems.map(item => {
      const actualRecord = item.actuals ? item.actuals[monthKey] : null;
      const draft = draftState[item.id];
      const isLocked = !!(actualRecord && actualRecord.postedTxId);
      const defaultVal = Number(item.amount) || 0;
      const isVerified = draft ? draft.verified : (actualRecord ? actualRecord.verified === true : false);
      const actualVal = draft ? draft.actualVal : (actualRecord ? (Number(actualRecord.amount) || 0) : defaultVal);
      const paymentDate = draft ? draft.paymentDate : (actualRecord?.paymentDate || todayISO());
      const paymentSource = draft ? draft.paymentSource : (actualRecord?.paymentSource || 'cashbox');
      const paidBy = draft ? draft.paidBy : (actualRecord?.paidBy || 'سيف');
      const adoptDefaultDraft = draft ? draft.adoptDefault : false;
      const suggestion = isLocked ? 0 : findMatchingExpenseSuggestion(item, monthKey);

      return `
        <div class="opc-item-card ${isVerified ? 'opc-is-verified' : ''}">
          <div class="opc-item-header">
            <div class="opc-item-name">
              <i class="fa-solid ${opcItemIcon(item.id)}"></i>
              <strong>${escapeHtml(item.name)}</strong>
              ${isLocked ? '<span class="opc-locked-badge"><i class="fa-solid fa-lock"></i> مرحّل</span>' : ''}
            </div>
            ${isLocked ? '' : `<button type="button" class="opc-delete-btn" onclick="deleteCostItemFromModal('${item.id}')" title="حذف"><i class="fa-solid fa-trash-can"></i></button>`}
          </div>

          <div class="opc-amounts-row">
            <div class="opc-field">
              <label>الافتراضي التقديري (شهرياً)</label>
              <input type="number" class="form-input opc-default-amt" data-id="${item.id}" value="${defaultVal}" ${isLocked ? 'disabled' : ''}>
            </div>
            <div class="opc-field">
              <label>الفعلي المشتري (لهذا الشهر)</label>
              <input type="number" class="form-input opc-actual-amt" data-id="${item.id}" value="${actualVal}" ${isLocked ? 'disabled' : ''}>
              ${suggestion > 0 ? `<button type="button" class="opc-suggestion-chip" onclick="applyOpcSuggestion('${item.id}', ${suggestion})"><i class="fa-solid fa-wand-magic-sparkles"></i> اقتراح من سجل المصاريف: ${formatMoneyReadable(suggestion)}</button>` : ''}
            </div>
          </div>

          <div class="opc-field opc-basis-field">
            <label>أساس توزيع الكلفة على الأيام</label>
            <select class="form-input opc-allocation-basis" data-id="${item.id}" onchange="setOpcAllocationBasis('${item.id}', this.value)" ${isLocked ? 'disabled' : ''}>
              <option value="calendar_days" ${item.allocationBasis === 'calendar_days' || !item.allocationBasis ? 'selected' : ''}>كل أيام الشهر (تقويمي)</option>
              <option value="working_days" ${item.allocationBasis === 'working_days' ? 'selected' : ''}>أيام العمل فقط (بدون الجمعة)</option>
              <option value="attendance_days" ${item.allocationBasis === 'attendance_days' ? 'selected' : ''}>أيام الحضور الفعلي فقط</option>
              <option value="manual" ${item.allocationBasis === 'manual' ? 'selected' : ''}>يدوي (بدون توزيع يومي تلقائي)</option>
            </select>
          </div>

          <label class="opc-toggle-row">
            <span class="opc-toggle-switch">
              <input type="checkbox" class="opc-verified-check" data-id="${item.id}" ${isVerified ? 'checked' : ''} ${isLocked ? 'disabled' : ''} onchange="toggleOpcVerifyPanel('${item.id}')">
              <span class="opc-toggle-track"><span class="opc-toggle-knob"></span></span>
            </span>
            <span class="opc-toggle-text">توثيق واعتماد هذا الشهر</span>
          </label>

          <div class="opc-verify-panel ${isVerified ? 'opc-panel-open' : ''}" id="opcVerifyPanel_${item.id}">
            ${isLocked ? `
              <div class="opc-locked-note">
                <div><i class="fa-solid fa-circle-check"></i>تم اعتماد هذا المصروف وترحيله ${paymentSource === 'person_pocket' ? `من جيب <b>${escapeHtml(paidBy || 'المالك')}</b>` : '<b>وخصمه من قاصة الورشة</b>'} بتاريخ <b>${escapeHtml(paymentDate)}</b>.</div>
                <small>لتصحيح مبلغ أو تاريخ خاطئ، استخدم "تراجع" لعكس القيد المحاسبي وإعادة فتح البند.</small>
                <button type="button" class="opc-undo-btn" onclick="undoOpcPostedItem('${item.id}')"><i class="fa-solid fa-rotate-left"></i> تراجع عن الترحيل</button>
              </div>
            ` : `
              <div class="opc-field">
                <label>تاريخ الدفع الفعلي</label>
                <input type="date" class="form-input opc-payment-date" data-id="${item.id}" value="${paymentDate}">
              </div>
              <div class="opc-field">
                <label>التأثير على القاصة</label>
                <div class="opc-radio-row">
                  <label><input type="radio" name="opcSource_${item.id}" class="opc-payment-source" data-id="${item.id}" value="cashbox" ${paymentSource !== 'person_pocket' ? 'checked' : ''} onchange="toggleOpcPocketField('${item.id}')"> نعم، يخصم من قاصة الورشة</label>
                  <label><input type="radio" name="opcSource_${item.id}" class="opc-payment-source" data-id="${item.id}" value="person_pocket" ${paymentSource === 'person_pocket' ? 'checked' : ''} onchange="toggleOpcPocketField('${item.id}')"> لا، دفع مباشر من جيب المالك</label>
                </div>
              </div>
              <div class="opc-field opc-pocket-field ${paymentSource === 'person_pocket' ? '' : 'opc-hidden'}" id="opcPocketField_${item.id}" style="grid-column: 1 / -1;">
                <label>اسم الدافع</label>
                <input type="text" class="form-input opc-paid-by" data-id="${item.id}" value="${escapeHtml(paidBy)}" placeholder="اسم المالك">
              </div>
              <label class="opc-toggle-row" style="grid-column: 1 / -1; margin-top: 0;">
                <span class="opc-toggle-switch">
                  <input type="checkbox" class="opc-adopt-default" data-id="${item.id}" ${adoptDefaultDraft ? 'checked' : ''}>
                  <span class="opc-toggle-track"><span class="opc-toggle-knob"></span></span>
                </span>
                <span class="opc-toggle-text">اعتماد هذه القيمة كافتراضي مستقبلي للأشهر القادمة</span>
              </label>
            `}
          </div>
        </div>
      `;
    }).join('');
  }

  // renderModalCostRows() rebuilds the ENTIRE items container from
  // `settings`/`draftState`, so anything the user typed but hasn't reached
  // final Confirm yet (default/actual amounts, verify toggle, payment date/
  // source/payer, adopt-default) only lives in the live DOM. Any action that
  // re-renders (add item, delete item, undo) must first pull those
  // in-progress values out of the DOM here, or the re-render silently wipes
  // every other card's unsaved edits — this was reported live: adding a
  // custom item after editing every other item erased all the edits above
  // it. Default-estimate edits (`item.amount`) are safe to apply immediately;
  // actual/verify/payment fields go into `draftState`, NOT `item.actuals` —
  // writing them there would create a premature "saved" record that breaks
  // the "no record yet -> fall back to the default estimate" display logic
  // for every later default edit on that same item.
  function syncDraftFromDom() {
    const container = document.getElementById('modalCostItemsContainer');
    if (!container) return;

    settings.monthlyItems.forEach(item => {
      if (item.active === false) return;
      const existingRecord = item.actuals ? item.actuals[monthKey] : null;
      if (existingRecord && existingRecord.postedTxId) return; // never touch a posted month/item

      const defaultInput = container.querySelector(`.opc-default-amt[data-id="${item.id}"]`);
      if (defaultInput) item.amount = Number(defaultInput.value) || 0;

      const actualInput = container.querySelector(`.opc-actual-amt[data-id="${item.id}"]`);
      if (!actualInput) return; // row not rendered (e.g. brand new item pushed this same tick)

      const verifiedCheck = container.querySelector(`.opc-verified-check[data-id="${item.id}"]`);
      const paymentDateInput = container.querySelector(`.opc-payment-date[data-id="${item.id}"]`);
      const sourceRadio = container.querySelector(`.opc-payment-source[data-id="${item.id}"]:checked`);
      const paidByInput = container.querySelector(`.opc-paid-by[data-id="${item.id}"]`);
      const adoptCheck = container.querySelector(`.opc-adopt-default[data-id="${item.id}"]`);

      draftState[item.id] = {
        actualVal: Number(actualInput.value) || 0,
        verified: !!verifiedCheck?.checked,
        paymentDate: paymentDateInput?.value || todayISO(),
        paymentSource: sourceRadio?.value === 'person_pocket' ? 'person_pocket' : 'cashbox',
        paidBy: paidByInput?.value.trim() || '',
        adoptDefault: !!adoptCheck?.checked
      };
    });
  }

  window.toggleOpcVerifyPanel = function(id) {
    const panel = document.getElementById(`opcVerifyPanel_${id}`);
    const checkbox = document.querySelector(`.opc-verified-check[data-id="${id}"]`);
    if (!panel || !checkbox) return;
    panel.classList.toggle('opc-panel-open', checkbox.checked);
  };

  // Applied immediately to the item (like the default-estimate amount) —
  // it's a display/calculation setting, not a financial verification field,
  // so it doesn't need to go through draftState + the confirm review prompt.
  window.setOpcAllocationBasis = function(id, basis) {
    const item = settings.monthlyItems.find(x => x.id === id);
    if (item) item.allocationBasis = basis;
  };

  window.toggleOpcPocketField = function(id) {
    const field = document.getElementById(`opcPocketField_${id}`);
    const selected = document.querySelector(`.opc-payment-source[data-id="${id}"]:checked`);
    if (field) field.classList.toggle('opc-hidden', !selected || selected.value !== 'person_pocket');
  };

  window.applyOpcSuggestion = function(id, amount) {
    const input = document.querySelector(`.opc-actual-amt[data-id="${id}"]`);
    if (input) input.value = amount;
    if (typeof showToast === 'function') showToast('تم تعبئة القيمة المقترحة من سجل المصاريف', 'success');
  };

  // Reverses a posted operating-cost item: cancels the v6 move via the
  // existing audited FinanceService.cancelMove (creates a reversing entry,
  // marks the original cancelled — same pattern as cancelMoveFromUI), drops
  // the synthetic legacy mirror row this module created, and reopens the
  // item for re-entry. Never deletes the real ledger history.
  window.undoOpcPostedItem = async function(id) {
    const item = settings.monthlyItems.find(x => x.id === id);
    const record = item?.actuals?.[monthKey];
    if (!item || !record || !record.postedTxId) return;

    if (!confirm(`سيتم عكس مصروف "${item.name}" المُرحّل بقيد عكسي في السجل المحاسبي وإعادة فتح البند للتعديل. هل تريد المتابعة؟`)) return;

    const legacyTx = finance.transactions.find(tx => tx.id === record.postedTxId);
    try {
      if (legacyTx?.v6_move_id && window.FinanceService) {
        await FinanceService.cancelMove(legacyTx.v6_move_id, { backup_tag: 'pre_opcost_undo' });
        if (window.PentagonDB) await PentagonDB.load({ force: true });
      }
    } catch (err) {
      if (typeof showToast === 'function') showToast(err.message || 'تعذّر عكس القيد المحاسبي', 'error');
      return;
    }

    if (legacyTx) {
      finance.transactions = finance.transactions.filter(tx => tx.id !== record.postedTxId);
    }

    delete item.actuals[monthKey];
    omni.adminSettings.workshopOperatingCosts = settings;
    saveData();

    if (typeof showToast === 'function') showToast('تم التراجع عن الترحيل وإعادة فتح البند', 'success');
    syncDraftFromDom();
    renderModalCostRows();
  };

  window.addCostItemFromModal = function() {
    const nameInput = document.getElementById('newCostItemName');
    const defaultInput = document.getElementById('newCostItemDefault');
    const name = nameInput.value.trim();
    const defaultVal = Number(defaultInput.value) || 0;

    if (!name) {
      if (typeof showToast === 'function') showToast('يرجى إدخال اسم المصروف', 'error');
      return;
    }

    syncDraftFromDom();

    settings.monthlyItems.push({
      id: 'cost_' + Date.now(),
      name,
      amount: defaultVal,
      active: true,
      allocationBasis: 'calendar_days',
      accountId: 'expense_general',
      categoryId: 'cat_general',
      keywords: [name],
      actuals: {}
    });

    nameInput.value = '';
    defaultInput.value = '';

    renderModalCostRows();
  };

  window.deleteCostItemFromModal = function(id) {
    const item = settings.monthlyItems.find(x => x.id === id);
    if (item) {
      syncDraftFromDom();
      item.active = false;
      renderModalCostRows();
    }
  };

  // This item list needs more room than the generic 400px omni modal box —
  // widen it just for this feature's lifetime via a scoped class, restored on close.
  const opcModalBoxEl = document.getElementById('omniModalBox');
  if (opcModalBoxEl) opcModalBoxEl.classList.add('opc-modal-wide');

  const confirmed = await showOmniModal(
    `ضبط مصاريف التشغيل - ${MONTHS_AR[cfg.month - 1]} ${cfg.year}`,
    buildModalHtml(),
    (bodyEl) => {
      const activeItems = settings.monthlyItems.filter(item => item.active !== false);

      // Pass 1 — read the form and validate, WITHOUT mutating anything yet.
      // This lets us show the user exactly what's about to hit the ledger
      // before committing, and abort cleanly (nothing touched) if validation
      // fails or the user declines the review prompt below.
      const plan = [];
      for (const item of activeItems) {
        const actualRecord = item.actuals ? item.actuals[monthKey] : null;
        const isLocked = !!(actualRecord && actualRecord.postedTxId);
        const defaultVal = Number(bodyEl.querySelector(`.opc-default-amt[data-id="${item.id}"]`)?.value ?? item.amount) || 0;

        if (isLocked) { plan.push({ item, isLocked: true }); continue; }

        const actualInput = bodyEl.querySelector(`.opc-actual-amt[data-id="${item.id}"]`);
        const verifiedCheck = bodyEl.querySelector(`.opc-verified-check[data-id="${item.id}"]`);
        const actualVal = Number(actualInput?.value) || 0;
        const verified = !!verifiedCheck?.checked;

        if (!verified) { plan.push({ item, isLocked: false, defaultVal, verified: false, actualVal }); continue; }

        const paymentDate = bodyEl.querySelector(`.opc-payment-date[data-id="${item.id}"]`)?.value || todayISO();
        const sourceRadio = bodyEl.querySelector(`.opc-payment-source[data-id="${item.id}"]:checked`);
        const paymentSource = sourceRadio?.value === 'person_pocket' ? 'person_pocket' : 'cashbox';
        const paidBy = paymentSource === 'person_pocket'
          ? (bodyEl.querySelector(`.opc-paid-by[data-id="${item.id}"]`)?.value.trim() || '')
          : '';
        const adoptDefault = !!bodyEl.querySelector(`.opc-adopt-default[data-id="${item.id}"]`)?.checked;

        if (paymentSource === 'person_pocket' && !paidBy) {
          if (typeof showToast === 'function') showToast(`يرجى إدخال اسم الدافع لبند "${item.name}"`, 'error');
          return false;
        }
        if (actualVal <= 0) {
          if (typeof showToast === 'function') showToast(`أدخل مبلغاً صحيحاً لبند "${item.name}"`, 'error');
          return false;
        }

        plan.push({ item, isLocked: false, defaultVal, verified: true, actualVal, paymentDate, paymentSource, paidBy, adoptDefault });
      }

      // Pass 2 — anything about to post a real ledger entry gets shown to the
      // user first and requires an explicit yes. Items that only update the
      // estimate/unverified actual (no ledger impact) skip this prompt.
      const toPost = plan.filter(p => p.verified && !p.isLocked);
      if (toPost.length > 0) {
        const lines = toPost.map(p => {
          const src = p.paymentSource === 'person_pocket' ? `من جيب ${p.paidBy}` : 'من قاصة الورشة';
          return `• ${p.item.name}: ${formatMoneyReadable(p.actualVal)} (${src}) بتاريخ ${p.paymentDate}`;
        }).join('\n');
        const ok = confirm(`سيتم تسجيل القيود التالية في السجل المالي:\n\n${lines}\n\nهل تريد إضافتها للسجل المالي؟`);
        if (!ok) return false;
      }

      // Pass 3 — apply. Only now do we mutate settings/post to the ledger.
      for (const p of plan) {
        const { item } = p;
        if (p.isLocked) continue; // never touch an already-posted month/item
        item.amount = p.defaultVal;

        if (!item.actuals) item.actuals = {};

        if (!p.verified) {
          item.actuals[monthKey] = { amount: p.actualVal, verified: false };
          continue;
        }

        const posted = addFinanceTransaction({
          type: 'expense',
          direction: 'out',
          sourceType: p.paymentSource,
          sourceId: `opcost_${item.id}_${monthKey}`,
          date: p.paymentDate,
          amount: p.actualVal,
          categoryId: item.categoryId || 'cat_general',
          departmentId: 'dept_workshop',
          accountId: item.accountId || 'expense_general',
          description: `مصاريف تشغيل - ${item.name} - ${MONTHS_AR[cfg.month - 1]} ${cfg.year}`,
          paidByName: p.paidBy
        }, { skipSave: true });

        item.actuals[monthKey] = {
          amount: p.actualVal,
          verified: true,
          paymentDate: p.paymentDate,
          paymentSource: p.paymentSource,
          paidBy: p.paidBy,
          postedTxId: posted?.id || ''
        };

        if (p.adoptDefault) item.amount = p.actualVal;
      }

      if (!omni.adminSettings) omni.adminSettings = {};
      omni.adminSettings.workshopOperatingCosts = settings;
      saveData();

      if (typeof showToast === 'function') showToast('✅ تم حفظ مصاريف التشغيل وتحديث التقويم', 'success');
      return true;
    },
    () => {
      renderModalCostRows();
    }
  );

  delete window.addCostItemFromModal;
  delete window.deleteCostItemFromModal;
  delete window.toggleOpcVerifyPanel;
  delete window.setOpcAllocationBasis;
  delete window.toggleOpcPocketField;
  delete window.applyOpcSuggestion;
  delete window.undoOpcPostedItem;
  if (opcModalBoxEl) opcModalBoxEl.classList.remove('opc-modal-wide');

  if (confirmed) {
    renderAttendanceCalendar();
  }
}

function selectCalendarDay(day) {
  selectedCalendarDay = day;
  renderAttendanceCalendar();
}

function calendarJumpToday() {
  const now = new Date();
  setConfigValue('cfgMonth', now.getMonth() + 1);
  setConfigValue('cfgYear', now.getFullYear());
  selectedCalendarDay = now.getDate();
  renderAttendanceCalendar();
}

// Official, persistent documentation log for verified monthly operating-cost
// items — a standing table on the calendar page (not the transient config
// modal), listing every documented item across every month so it stays
// reviewable after the modal closes. Sorted most recent payment first.
function renderOpcDocumentationLog() {
  const tbody = document.getElementById('opcDocLogBody');
  const statsEl = document.getElementById('opcDocLogStats');
  if (!tbody || !statsEl) return; // section not present on this page build

  ensureOmni();
  const items = (omni.adminSettings?.workshopOperatingCosts?.monthlyItems) || [];
  const rows = [];
  items.forEach(item => {
    Object.entries(item.actuals || {}).forEach(([monthKey, record]) => {
      if (!record || record.verified !== true) return;
      rows.push({
        monthKey,
        itemName: item.name,
        amount: Number(record.amount) || 0,
        paymentDate: record.paymentDate || '',
        paymentSource: record.paymentSource || 'cashbox',
        paidBy: record.paidBy || '',
        posted: !!record.postedTxId
      });
    });
  });

  rows.sort((a, b) => (b.paymentDate || b.monthKey).localeCompare(a.paymentDate || a.monthKey) || b.monthKey.localeCompare(a.monthKey));

  const totalAmount = rows.reduce((sum, r) => sum + r.amount, 0);
  statsEl.innerHTML = `
    <span><strong>${rows.length}</strong> قيد موثّق</span>
    <span><strong>${formatMoneyReadable(totalAmount)}</strong> إجمالي موثّق</span>
  `;

  if (!rows.length) {
    tbody.innerHTML = `<tr><td colspan="6" class="opc-doclog-empty">لا توجد بنود موثّقة بعد. وثّق مصروفاً من نافذة "مصاريف التشغيل" ليظهر هنا.</td></tr>`;
    return;
  }

  tbody.innerHTML = rows.map(r => {
    const [y, m] = r.monthKey.split('-');
    const monthLabel = `${MONTHS_AR[Number(m) - 1] || m} ${y}`;
    const sourceLabel = r.paymentSource === 'person_pocket' ? `جيب ${escapeHtml(r.paidBy || 'المالك')}` : 'قاصة الورشة';
    const statusBadge = r.posted
      ? `<span class="opc-doclog-badge opc-doclog-posted"><i class="fa-solid fa-lock"></i> مرحّل</span>`
      : `<span class="opc-doclog-badge opc-doclog-pending"><i class="fa-solid fa-triangle-exclamation"></i> غير مرحّل</span>`;
    return `
      <tr>
        <td>${escapeHtml(monthLabel)}</td>
        <td>${escapeHtml(r.itemName)}</td>
        <td class="opc-doclog-amount">${formatMoneyReadable(r.amount)}</td>
        <td>${escapeHtml(r.paymentDate || '-')}</td>
        <td>${sourceLabel}</td>
        <td>${statusBadge}</td>
      </tr>
    `;
  }).join('');
}

// Splits the month into actual-vs-forecast on both the payroll AND the
// operating-cost side (requirement: never mix a forecast total into a
// finalized/actual figure). A day only ever contributes to one side —
// getCalendarDayData already resolved its `mode`, so there's no double
// counting between actualLabor/forecastLabor or actualOperating/
// forecastOperating.
function getCalendarMonthForecastSummary(year, month, allDayData) {
  const monthClosed = isPayrollMonthClosed(year, month);
  const activeEmployees = employees.filter(emp => emp && emp.name && employeeHasActiveDayInMonth(emp, year, month));

  let actualLabor = 0, forecastLabor = 0, actualOperating = 0, forecastOperating = 0;
  let actualDays = 0, forecastDays = 0, missingDays = 0, weeklyOffDays = 0;
  allDayData.forEach(day => {
    if (day.mode === 'forecast') {
      forecastLabor += day.forecastLaborCost;
      forecastOperating += day.operatingShareForDay;
      forecastDays++;
    } else {
      actualLabor += day.laborDueCost;
      actualOperating += day.operatingShareForDay;
      if (day.mode === 'actual') actualDays++;
      else if (day.mode === 'missing') missingDays++;
      else if (day.mode === 'weekly_off') weeklyOffDays++;
    }
  });

  const operating = getWorkshopOperatingCostBreakdown(year, month);
  return {
    mode: monthClosed ? 'closed' : (forecastDays > 0 ? (actualDays > 0 ? 'mixed' : 'forecast') : 'actual'),
    monthClosed,
    activeEmployees: activeEmployees.length,
    actualLabor,
    forecastLabor,
    actualOperating,
    forecastOperating,
    operatingMonthlyTotal: operating.monthlyTotal,
    totalActual: actualLabor + actualOperating,
    totalForecast: forecastLabor + forecastOperating,
    // The authoritative grand total still uses the month's full fixed-cost
    // total (not actualOperating+forecastOperating), because 'manual'-basis
    // items aren't auto-spread across days and would otherwise be silently
    // dropped from this figure.
    projectedGrandTotal: actualLabor + forecastLabor + operating.monthlyTotal,
    actualDays,
    forecastDays,
    missingDays,
    weeklyOffDays
  };
}

function buildCalendarMonthForecastBox(summary, year, month) {
  const modeLabel = summary.mode === 'closed' ? 'شهر مغلق' : summary.mode === 'actual' ? 'خلاصة فعلية' : summary.mode === 'forecast' ? 'توقع شهري كامل' : 'فعلي + تنبؤي';
  const forecastLine = summary.mode === 'actual' || summary.mode === 'closed'
    ? `<span>أيام فعلية</span><strong>${summary.actualDays}</strong>`
    : `<span>أيام مستقبلية متوقعة</span><strong>${summary.forecastDays}</strong>`;
  const missingLine = summary.missingDays > 0
    ? `<div class="cal-month-forecast-missing"><span>أيام بيانات ناقصة</span><strong>${summary.missingDays}</strong></div>`
    : '';
  return `
    <div class="cal-month-forecast-box ${summary.mode === 'closed' ? 'cal-month-forecast-box-closed' : ''}" role="note" aria-label="توقعات شهر ${MONTHS_AR[month - 1]} ${year}">
      <div class="cal-month-forecast-head">
        <i class="fa-solid ${summary.mode === 'closed' ? 'fa-lock' : 'fa-chart-line'}"></i>
        <div>
          <strong>${modeLabel}</strong>
          <small>${MONTHS_AR[month - 1]} ${year}</small>
        </div>
      </div>
      <div class="cal-month-forecast-grid">
        <div><span>موظفون داخل الحساب</span><strong>${summary.activeEmployees}</strong></div>
        <div>${forecastLine}</div>
        <div><span>أجور فعلية</span><strong>${formatMoneyReadable(summary.actualLabor)}</strong></div>
        <div class="cal-forecast-stat"><span>أجور متوقعة</span><strong>${formatMoneyReadable(summary.forecastLabor)}</strong></div>
        <div><span>تشغيل فعلي</span><strong>${formatMoneyReadable(summary.actualOperating)}</strong></div>
        <div class="cal-forecast-stat"><span>تشغيل متوقع</span><strong>${formatMoneyReadable(summary.forecastOperating)}</strong></div>
        ${missingLine}
        <div class="cal-month-forecast-total"><span>إجمالي الشهر المتوقع</span><strong>${formatMoneyReadable(summary.projectedGrandTotal)}</strong></div>
      </div>
    </div>
  `;
}

function renderAttendanceCalendar() {
  renderAttendanceFreshnessBanner('pageCalendar', '.calendar-container-pro');
  const container = document.getElementById('attendanceCalendarGrid');
  const cfg = getConfig();
  const daysInMonth = getDaysInMonth(cfg.year, cfg.month);
  const firstDay = new Date(cfg.year, cfg.month - 1, 1).getDay();

  document.getElementById('calHeaderMonthYear').textContent = `${MONTHS_AR[cfg.month - 1]} ${cfg.year}`;
  container.innerHTML = '';

  const allDayData = Array.from({ length: daysInMonth }, (_, idx) => getCalendarDayData(cfg.year, cfg.month, idx + 1));
  const today = new Date();
  if (
    selectedCalendarDay == null &&
    today.getFullYear() === cfg.year &&
    today.getMonth() + 1 === cfg.month
  ) {
    selectedCalendarDay = today.getDate();
  }
  if (selectedCalendarDay == null || selectedCalendarDay > daysInMonth) {
    const firstAttendanceDay = allDayData.find(day => day.rows.length > 0);
    selectedCalendarDay = firstAttendanceDay ? firstAttendanceDay.day : 1;
  }

  CALENDAR_DAY_NAMES.forEach((name, idx) => {
    const head = document.createElement('div');
    head.className = 'cal-weekday' + (idx === 5 ? ' cal-weekday-friday' : '');
    head.textContent = name;
    container.appendChild(head);
  });

  // Padding for first day
  for (let i = 0; i < firstDay; i++) {
    const empty = document.createElement('div');
    empty.className = 'cal-day-box cal-day-off';
    container.appendChild(empty);
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const box = document.createElement('div');
    const dayData = allDayData[d - 1];
    box.className = [
      'cal-day-box',
      dayData.isFriday ? 'cal-day-friday' : '',
      dayData.rows.length ? 'cal-day-has-attendance' : 'cal-day-empty',
      selectedCalendarDay === d ? 'cal-day-selected' : ''
    ].filter(Boolean).join(' ');
    box.setAttribute('role', 'button');
    box.setAttribute('tabindex', '0');
    box.onclick = () => selectCalendarDay(d);
    box.onkeydown = (event) => {
      if (event.key === 'Enter' || event.key === ' ') selectCalendarDay(d);
    };

    const dateNum = document.createElement('div');
    dateNum.className = 'cal-date-num';
    dateNum.innerHTML = `<span>${d}</span><small>${dayData.dayName}</small>`;
    box.appendChild(dateNum);

    const summary = document.createElement('div');
    summary.className = 'cal-day-summary';
    summary.innerHTML = `
      <strong>${dayData.rows.length}</strong>
      <span>حضور</span>
      <em>${dayData.totalHours.toFixed(1)} س</em>
    `;
    box.appendChild(summary);
    if (dayData.rows.length) {
      const moneyMini = document.createElement('div');
      moneyMini.className = 'calendar-finance-mini';
      moneyMini.innerHTML = `<b>كلفة اليوم</b> ${formatMoneyReadable(dayData.netDailyCost)}<small>سلف ${formatMoneyReadable(dayData.totalAdvances)}</small>`;
      box.appendChild(moneyMini);
    }
    // Friday shows the week's rolled-up operating + labor cost as its own
    // distinct badge — even with no attendance rows of its own, since it
    // summarizes the preceding 6 working days, not Friday itself.
    if (dayData.isFriday && dayData.weeklyTotalShare > 0) {
      const weeklyMini = document.createElement('div');
      weeklyMini.className = 'cal-weekly-mini-badge';
      weeklyMini.innerHTML = `<b>📅 أسبوعي</b> ${formatMoneyReadable(dayData.weeklyTotalShare)}`;
      box.appendChild(weeklyMini);
    }

    const dots = document.createElement('div');
    dots.className = 'cal-emp-dots';

    dayData.rows.slice(0, 8).forEach(item => {
      const badge = document.createElement('div');
      badge.className = 'cal-emp-badge';
      badge.textContent = item.name.substring(0, 2);
      badge.title = `${item.name} (${item.rec.checkIn || '--:--'} - ${item.rec.checkOut || '--:--'})`;
      badge.style.borderColor = item.statusColor;
      dots.appendChild(badge);
    });

    if (dayData.rows.length > 8) {
      const more = document.createElement('div');
      more.className = 'cal-emp-more';
      more.textContent = `+${dayData.rows.length - 8}`;
      dots.appendChild(more);
    }

    box.appendChild(dots);
    container.appendChild(box);
  }

  const selectedData = allDayData.find(day => day.day === selectedCalendarDay) || allDayData[0];
  document.getElementById('calDailyTotalHours').textContent = selectedData ? selectedData.totalHours.toFixed(1) : '0';
  document.getElementById('calDailyActiveEmps').textContent = selectedData ? selectedData.rows.length : '0';
  renderCalendarDayDetails(selectedData);
  renderOpcDocumentationLog();
}

function renderAttendanceCalendar() {
  renderAttendanceFreshnessBanner('pageCalendar', '.calendar-container-pro');
  const container = document.getElementById('attendanceCalendarGrid');
  if (!container) return;
  const cfg = getConfig();
  const daysInMonth = getDaysInMonth(cfg.year, cfg.month);
  const firstDay = new Date(cfg.year, cfg.month - 1, 1).getDay();
  const header = document.getElementById('calHeaderMonthYear');
  if (header) header.textContent = `${MONTHS_AR[cfg.month - 1]} ${cfg.year}`;
  container.innerHTML = '';

  const allDayData = Array.from({ length: daysInMonth }, (_, idx) => getCalendarDayData(cfg.year, cfg.month, idx + 1));
  const today = new Date();
  if (selectedCalendarDay == null && today.getFullYear() === cfg.year && today.getMonth() + 1 === cfg.month) {
    selectedCalendarDay = today.getDate();
  }
  if (selectedCalendarDay == null || selectedCalendarDay > daysInMonth) {
    const firstVisibleDay = allDayData.find(day => day.rows.length > 0 || day.hasForecast);
    selectedCalendarDay = firstVisibleDay ? firstVisibleDay.day : 1;
  }

  CALENDAR_DAY_NAMES.forEach((name, idx) => {
    const head = document.createElement('div');
    head.className = 'cal-weekday' + (idx === 5 ? ' cal-weekday-friday' : '');
    head.textContent = name;
    container.appendChild(head);
  });

  for (let i = 0; i < firstDay; i++) {
    const empty = document.createElement('div');
    empty.className = 'cal-day-box cal-day-off';
    container.appendChild(empty);
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const dayData = allDayData[d - 1];
    const badgeRows = dayData.hasForecast ? dayData.forecastRows : dayData.rows;
    const box = document.createElement('div');
    box.className = [
      'cal-day-box',
      `cal-day-mode-${dayData.mode}`,
      dayData.isFriday ? 'cal-day-friday' : '',
      dayData.hasForecast ? 'cal-day-forecast' : '',
      dayData.rows.length ? 'cal-day-has-attendance' : 'cal-day-empty',
      selectedCalendarDay === d ? 'cal-day-selected' : ''
    ].filter(Boolean).join(' ');
    box.setAttribute('role', 'button');
    box.setAttribute('tabindex', '0');
    box.onclick = () => selectCalendarDay(d);
    box.onkeydown = (event) => {
      if (event.key === 'Enter' || event.key === ' ') selectCalendarDay(d);
    };

    const dateNum = document.createElement('div');
    dateNum.className = 'cal-date-num';
    dateNum.innerHTML = `<span>${d}</span><small>${dayData.dayName}</small>`;
    box.appendChild(dateNum);

    const modeBadge = document.createElement('div');
    modeBadge.className = `cal-day-mode-badge cal-day-mode-badge-${dayData.mode}`;
    modeBadge.innerHTML = `<i class="fa-solid ${dayData.modeIcon}"></i> ${dayData.modeLabel}`;
    box.appendChild(modeBadge);

    const visibleCount = dayData.hasForecast ? dayData.forecastRows.length : dayData.rows.length;
    const visibleHours = dayData.hasForecast ? dayData.forecastHours : dayData.totalHours;
    const visibleLabel = dayData.hasForecast ? 'متوقع' : 'حضور';
    const summary = document.createElement('div');
    summary.className = 'cal-day-summary';
    summary.innerHTML = `<strong>${visibleCount}</strong><span>${visibleLabel}</span><em>${visibleHours.toFixed(1)} س</em>`;
    box.appendChild(summary);

    if (dayData.rows.length || dayData.hasForecast) {
      const moneyMini = document.createElement('div');
      moneyMini.className = 'calendar-finance-mini' + (dayData.hasForecast ? ' calendar-finance-mini-forecast' : '');
      moneyMini.innerHTML = dayData.hasForecast
        ? `<b>متوقع</b> ${formatMoneyReadable(dayData.netDailyCost)}<small>بدون سلف</small>`
        : `<b>كلفة اليوم</b> ${formatMoneyReadable(dayData.netDailyCost)}<small>سلف ${formatMoneyReadable(dayData.totalAdvances)}</small>`;
      box.appendChild(moneyMini);
    }

    if (dayData.isFriday && dayData.weeklyTotalShare > 0) {
      const weeklyMini = document.createElement('div');
      weeklyMini.className = 'cal-weekly-mini-badge';
      weeklyMini.innerHTML = `<b>أسبوعي</b> ${formatMoneyReadable(dayData.weeklyTotalShare)}`;
      box.appendChild(weeklyMini);
    }

    const dots = document.createElement('div');
    dots.className = 'cal-emp-dots';
    badgeRows.slice(0, 8).forEach(item => {
      const badge = document.createElement('div');
      badge.className = 'cal-emp-badge' + (item.isForecast ? ' cal-emp-badge-forecast' : '');
      badge.textContent = item.name.substring(0, 2);
      badge.title = item.isForecast ? `${item.name} (متوقع)` : `${item.name} (${item.rec.checkIn || '--:--'} - ${item.rec.checkOut || '--:--'})`;
      badge.style.borderColor = item.statusColor;
      dots.appendChild(badge);
    });
    if (badgeRows.length > 8) {
      const more = document.createElement('div');
      more.className = 'cal-emp-more';
      more.textContent = `+${badgeRows.length - 8}`;
      dots.appendChild(more);
    }

    box.appendChild(dots);
    container.appendChild(box);
  }

  const monthSummary = getCalendarMonthForecastSummary(cfg.year, cfg.month, allDayData);
  container.insertAdjacentHTML('beforeend', buildCalendarMonthForecastBox(monthSummary, cfg.year, cfg.month));

  const closeBtn = document.getElementById('calendarCloseMonthBtn');
  if (closeBtn) {
    const closed = monthSummary.monthClosed;
    closeBtn.innerHTML = closed
      ? '<i class="fa-solid fa-lock-open"></i><span>إعادة فتح الشهر</span>'
      : '<i class="fa-solid fa-lock"></i><span>إغلاق الشهر</span>';
    closeBtn.title = closed ? 'إعادة فتح الشهر لاستئناف التوقع' : 'إغلاق الشهر وتجميد التوقعات';
    closeBtn.classList.toggle('calendar-month-closed-active', closed);
  }

  const selectedData = allDayData.find(day => day.day === selectedCalendarDay) || allDayData[0];
  const selectedHours = selectedData ? (selectedData.hasForecast ? selectedData.forecastHours : selectedData.totalHours) : 0;
  const selectedEmployees = selectedData ? (selectedData.hasForecast ? selectedData.forecastRows.length : selectedData.rows.length) : 0;
  const hoursEl = document.getElementById('calDailyTotalHours');
  const empsEl = document.getElementById('calDailyActiveEmps');
  if (hoursEl) hoursEl.textContent = selectedHours.toFixed(1);
  if (empsEl) empsEl.textContent = selectedEmployees;
  renderCalendarDayDetails(selectedData);
  renderOpcDocumentationLog();
}

window.toggleCalendarMonthClosed = function() {
  const cfg = getConfig();
  setPayrollMonthClosed(cfg.year, cfg.month, !isPayrollMonthClosed(cfg.year, cfg.month));
};

// ─── Attendance forecast regression tests ───
// Manual diagnostic (run from the console: runAttendanceForecastRegressionTests()).
// Swaps the live `employees` array and the operating-cost/closed-month admin
// settings for a synthetic fixture, runs the scenarios, and restores the
// originals in `finally` — never touches real data, never persists anything
// (no saveData() call anywhere in here). Uses the REAL current year/month so
// isEmployeeActiveOnDate's auto-resignation guard (anchored to the real
// wall-clock date) doesn't false-positive against synthetic dates.
function runAttendanceForecastRegressionTests() {
  const results = [];
  const assert = (name, cond, detail = '') => results.push({ name, pass: !!cond, detail });

  const originalEmployees = employees;
  if (!omni) omni = {};
  if (!omni.adminSettings) omni.adminSettings = {};
  const originalWorkshopCosts = omni.adminSettings.workshopOperatingCosts;
  const originalClosedMonths = omni.adminSettings.closedPayrollMonths;
  const originalManualCutoff = omni.adminSettings.lastCompleteAttendanceUpdateDate;
  const originalManualCutoffAlt = omni.adminSettings.lastCompleteDatabaseUpdateDate;
  const originalSelectedDay = selectedCalendarDay;

  try {
    omni.adminSettings.workshopOperatingCosts = {
      monthlyItems: [
        { id: 'rent', name: 'إيجار الورشة', amount: 300000, active: true, allocationBasis: 'calendar_days' },
        { id: 'internet', name: 'اشتراك الإنترنت', amount: 60000, active: true, allocationBasis: 'calendar_days' },
        { id: 'electricity', name: 'اشتراك الكهرباء', amount: 90000, active: true, allocationBasis: 'calendar_days' }
      ]
    };
    omni.adminSettings.closedPayrollMonths = [];
    omni.adminSettings.lastCompleteAttendanceUpdateDate = null;
    omni.adminSettings.lastCompleteDatabaseUpdateDate = null;

    const now = new Date();
    const YEAR = now.getFullYear();
    const MONTH = now.getMonth() + 1;
    const prevMonth = MONTH === 1 ? 12 : MONTH - 1;
    const prevYear = MONTH === 1 ? YEAR - 1 : YEAR;
    const prevMonthLastDay = getDaysInMonth(prevYear, prevMonth);
    const nextNonFriday = (startDay) => {
      let d = startDay;
      while (isFriday(YEAR, MONTH, d)) d++;
      return d;
    };

    const empA = {
      id: 'test_emp_forecast_a',
      name: 'موظف اختبار توقع',
      active: true,
      salary: 300000,
      records: [
        { year: prevYear, month: prevMonth, day: prevMonthLastDay, checkIn: '08:00', checkOut: '17:00', status: 'normal', hours: 8 }
      ]
    };
    employees = [empA];

    // 1) A month with the last update on the previous month's end shows the
    //    current month as forecast, never as a confirmed zero.
    const dayOne = nextNonFriday(1);
    const day1Data = getCalendarDayData(YEAR, MONTH, dayOne);
    assert(
      'شهر بلا استيراد جديد يظهر تنبؤي وليس صفراً فعلياً',
      day1Data.mode === 'forecast' && day1Data.rows.length === 0,
      `day=${dayOne} mode=${day1Data.mode} rows=${day1Data.rows.length}`
    );

    // 2) A day after the cutoff with no attendance records forecasts the
    //    active employee.
    assert(
      'يوم بعد آخر تحديث يتوقع الموظفين النشطين',
      day1Data.forecastRows.length === 1 && day1Data.forecastRows[0].name === empA.name,
      `forecastRows=${day1Data.forecastRows.length}`
    );

    // 3) Friday shows no normal payroll forecast, but fixed (calendar_days)
    //    operating expenses are still allocated to it.
    const firstFriday = getFridaysInMonth(YEAR, MONTH)[0];
    if (firstFriday) {
      const fridayData = getCalendarDayData(YEAR, MONTH, firstFriday);
      assert(
        'الجمعة بلا أجور تنبؤية عادية لكن مصاريف التشغيل الثابتة تُحسب',
        fridayData.mode === 'weekly_off' && fridayData.forecastLaborCost === 0 && fridayData.operatingShareForDay > 0,
        `mode=${fridayData.mode} forecastLaborCost=${fridayData.forecastLaborCost} opShare=${fridayData.operatingShareForDay}`
      );
    } else {
      assert('الجمعة بلا أجور تنبؤية عادية لكن مصاريف التشغيل الثابتة تُحسب', false, 'لا توجد جمعة في الشهر (غير متوقع)');
    }

    // 4) Importing actual attendance for a forecast day converts ONLY that
    //    day to actual — the next day stays forecast.
    const dayTwo = nextNonFriday(dayOne + 1);
    const dayThree = nextNonFriday(dayTwo + 1);
    empA.records.push({ year: YEAR, month: MONTH, day: dayTwo, checkIn: '08:00', checkOut: '17:00', status: 'normal', hours: 8 });
    const day2Data = getCalendarDayData(YEAR, MONTH, dayTwo);
    const day3Data = getCalendarDayData(YEAR, MONTH, dayThree);
    assert(
      'استيراد حضور فعلي ليوم واحد يحوّله لفعلي دون التأثير على بقية الأيام',
      day2Data.mode === 'actual' && day3Data.mode === 'forecast',
      `day${dayTwo}=${day2Data.mode} day${dayThree}=${day3Data.mode}`
    );

    // 5) Fixed rent/internet/electricity still appear on a day with zero
    //    employees.
    employees = [];
    const emptyDayData = getCalendarDayData(YEAR, MONTH, nextNonFriday(5));
    assert(
      'مصاريف الإيجار/الإنترنت/الكهرباء تظهر رغم صفر موظفين',
      emptyDayData.rows.length === 0 && emptyDayData.operatingShareForDay > 0,
      `rows=${emptyDayData.rows.length} opShare=${emptyDayData.operatingShareForDay}`
    );

    // 6) Forecast totals never create accounting journal entries or payable
    //    balances — purely computed for display, nothing posted.
    const txCountBefore = (finance?.transactions || []).length;
    const allDays = Array.from({ length: getDaysInMonth(YEAR, MONTH) }, (_, i) => getCalendarDayData(YEAR, MONTH, i + 1));
    getCalendarMonthForecastSummary(YEAR, MONTH, allDays);
    getPayrollForecastSummary(YEAR, MONTH);
    const txCountAfter = (finance?.transactions || []).length;
    assert(
      'التوقعات لا تُنشئ قيود محاسبية أو مستحقات فعلية',
      txCountAfter === txCountBefore,
      `before=${txCountBefore} after=${txCountAfter}`
    );
  } finally {
    employees = originalEmployees;
    omni.adminSettings.workshopOperatingCosts = originalWorkshopCosts;
    omni.adminSettings.closedPayrollMonths = originalClosedMonths;
    omni.adminSettings.lastCompleteAttendanceUpdateDate = originalManualCutoff;
    omni.adminSettings.lastCompleteDatabaseUpdateDate = originalManualCutoffAlt;
    selectedCalendarDay = originalSelectedDay;
  }

  const passCount = results.filter(r => r.pass).length;
  const allPassed = passCount === results.length;
  if (typeof console !== 'undefined') {
    console.log(`%cattendance forecast regression: ${passCount}/${results.length} passed`, allPassed ? 'color:#34d399;font-weight:bold' : 'color:#f87171;font-weight:bold');
    if (typeof console.table === 'function') {
      console.table(results.map(r => ({ الفحص: r.name, النتيجة: r.pass ? 'PASS' : 'FAIL', التفاصيل: r.detail })));
    }
  }
  return { passCount, total: results.length, allPassed, results };
}
window.runAttendanceForecastRegressionTests = runAttendanceForecastRegressionTests;

function prevMonthCal() {
  let m = parseInt(getConfigNumber('cfgMonth', 3), 10);
  let y = parseInt(getConfigNumber('cfgYear', 2026), 10);
  if (m === 1) { m = 12; y--; } else { m--; }
  setConfigValue('cfgMonth', m);
  setConfigValue('cfgYear', y);
  selectedCalendarDay = null;
  renderAttendanceCalendar();
}

function nextMonthCal() {
  let m = parseInt(getConfigNumber('cfgMonth', 3), 10);
  let y = parseInt(getConfigNumber('cfgYear', 2026), 10);
  if (m === 12) { m = 1; y++; } else { m++; }
  setConfigValue('cfgMonth', m);
  setConfigValue('cfgYear', y);
  selectedCalendarDay = null;
  renderAttendanceCalendar();
}

// ─── Filter Table by Month ───
function filterTableByMonth() {
  const filterValue = document.getElementById('monthFilter').value;
  const rows = document.querySelectorAll('#importedDataTable tbody tr');

  rows.forEach(row => {
    const dateCell = row.cells[1].textContent; // Date column
    if (!filterValue) {
      row.style.display = '';
    } else {
      row.style.display = dateCell.includes(`/${filterValue}/`) ? '' : 'none';
    }
  });
}

// ─── Export/Import Data ───
function exportData() {
  const data = {
    employees,
    finance: ensureFinance(),
    config: getConfig(),
    dateGenerated: new Date().toISOString(),
    version: '2.1'
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `octagon_payroll_backup_${new Date().toISOString().split('T')[0]}.json`;
  a.click();
  URL.revokeObjectURL(url);
  showToast('✅ تم تصدير النسخة الاحتياطية بنجاح', 'success');
}

function importDataClick() {
  document.getElementById('importFile').click();
}

function importData(event) {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const data = JSON.parse(e.target.result);
      if (data.employees) {
        if (confirm('هل تريد استبدال البيانات الحالية بالنسخة المستوردة؟')) {
          employees = data.employees;
          finance = data.finance || defaultFinanceState();
          omni = data.omni || defaultOmniState();
          ensureFinance();
          ensureOmni();
          // Restoring an older backup taken before the balance sign-flip migration:
          // bring its employees up to the current convention too.
          migrateEmployeePrevAdvanceSignConvention();
          if (data.config) {
            setConfigValue('cfgMonth', data.config.month);
            setConfigValue('cfgYear', data.config.year);
            setConfigValue('cfgSalary', data.config.nominalSalary);
            if (data.config.cfgTransport != null) setConfigValue('cfgTransport', data.config.cfgTransport);
            if (data.config.cfgFood != null) setConfigValue('cfgFood', data.config.cfgFood);
          }
          saveData();
        }
      } else {
        showToast('❌ ملف غير صالح', 'error');
      }
    } catch (err) {
      showToast('❌ فشل في قراءة الملف', 'error');
    }
  };
  reader.readAsText(file);
}

function getConfig() {
  let y = parseInt(getConfigNumber('cfgYear', 2026), 10) || 2026;
  return {
    year: y,
    month: parseInt(getConfigNumber('cfgMonth', 3), 10) || 3,
    nominalSalary: getConfigNumber('cfgSalary', 500000) || 500000,
    cfgTransport: getConfigNumber('cfgTransport', 50000) || 50000,
    cfgFood: getConfigNumber('cfgFood', 50000) || 50000,
  };
}

function repairKnownArabicMojibake(value) {
  if (typeof value !== 'string' || !/[\uFFFD\u00D8\u00D9\u00F0\u0178\u00E2\u00C3]/.test(value)) return value;
  return value
    .replace(/\uFFFD\uFFFDمت/g, 'تمت')
    .replace(/الخط\uFFFD\uFFFDة/g, 'الخطوة')
    .replace(/ليوم \uFFFD\uFFFDد/g, 'ليوم غد');
}

function sanitizePersistedArabicText(value, seen = new WeakSet()) {
  if (!value || typeof value !== 'object') return value;
  if (seen.has(value)) return value;
  seen.add(value);
  if (Array.isArray(value)) {
    value.forEach((item, idx) => {
      value[idx] = typeof item === 'string' ? repairKnownArabicMojibake(item) : sanitizePersistedArabicText(item, seen);
    });
    return value;
  }
  Object.keys(value).forEach(key => {
    value[key] = typeof value[key] === 'string' ? repairKnownArabicMojibake(value[key]) : sanitizePersistedArabicText(value[key], seen);
  });
  return value;
}

// ─── Initialize ───
window.addEventListener('DOMContentLoaded', async () => {
  console.log('🚀 SYSTEM INITIALIZING (AUTO-MODE)');

  try {

  // 1. Initial Setup
  initTheme();
  bindSidebarNavigation();
  rebuildSidebarNavigation();
  const switcher = document.getElementById('authUserSwitcher');
  if (switcher && window.PentagonAuth) {
    switcher.value = window.PentagonAuth._currentUserId;
  }
  await loadData();
  window.__dataLoadComplete = true; // unlock saveData() now that real data is loaded
  if (migrateEmployeePrevAdvanceSignConvention()) saveData();
  ensureFinance();
  if (!finance.customers || finance.customers.length === 0) {
    finance.customers = [{
      id: 'cust_demo',
      name: 'عميل تجريبي',
      phone: '07700000000',
      companyName: 'شركة التجربة والبرهان',
      shopName: 'معرض التجربة والبرهان',
      openingBalance: 0,
      notes: 'عميل افتراضي تجريبي لمحاكاة البوابة'
    }];
  }
  // Start remembering visited pages now; the boot landing page is resolved later
  // (just before we navigate) so PermissionService is fully initialised by then.
  startLastPageTracking();
  const urlParams = new URLSearchParams(window.location.search);
  const urlCustomerId = urlParams.get('customer');
  if (urlCustomerId) {
    currentPage = 'customer_portal';
    window.customerPortalInitialCustomerId = urlCustomerId;
  }
  ensureOmni();
  applyOrbStyle(getAdminSetting('ui.orbStyle', 'classic'));
  updateGlobalCurrencyUI();
  resetSurfaceViewStateForExamples();
  // Guard: do NOT save during init if employees is empty. A previous race wrote `employees:[]` over
  // the server on every reload, wiping the workforce. The server now also refuses to wipe, but skip
  // the unnecessary write here too.
  if (Array.isArray(employees) && employees.length > 0) {
    saveData(true);
  } else {
    console.warn('[init] skipping startup saveData — employees array is empty (would wipe server).');
  }
  refreshAuthUserSwitcher();
  checkLoginStatus();
  enforceUIPermissions();
  try { autoGenerateMaintenanceTasks(); } catch (_) {}

  // 3. UI Setup
  const cfg = getConfig();
  const fridays = getFridaysInMonth(cfg.year, cfg.month);
  const inpFridayDays = document.getElementById('inpFridayDays');
  const daysMonthDisplay = document.getElementById('daysMonthDisplay');

  if (inpFridayDays) inpFridayDays.value = `0/${fridays.length}`;
  if (daysMonthDisplay) daysMonthDisplay.textContent = getDaysInMonth(cfg.year, cfg.month);

  refreshCalcEmpDropdown();
  refreshEmpFilterDropdown();
  
  // 3.5 Land on the boot page. Resolve it here (PermissionService is ready by now)
  // so we can "resume where you left off". A ?customer= deep-link takes priority.
  // Use window.switchPage (the template-loading guard) so the landing view is
  // hydrated first, plus a short re-land retry for module-owned pages whose
  // switchPage wrapper may not be wired yet this early in boot.
  if (currentPage !== 'customer_portal') currentPage = getBootLandingPage();
  const __bootLanding = currentPage;
  (window.switchPage || switchPage)(__bootLanding);
  setTimeout(() => {
    if (currentPage !== __bootLanding) return; // user already navigated — leave them be
    const active = document.querySelector(`.nav-btn[data-page="${__bootLanding}"].active`);
    if (!active) (window.switchPage || switchPage)(__bootLanding);
  }, 900);

  // 4. Auto-Fetch Excel Data — only when on import/timesheet views to avoid startup noise
  if (currentPage === 'timesheet' || currentPage === 'import') {
    try {
      const response = await fetch('merged_attendance_biometric.xlsx');
      if (!response.ok) throw new Error('not found');
      const buffer = await response.arrayBuffer();
      await ensureOctagonLibrary('xlsx', 'XLSX', 'Excel import library unavailable');
      await processExcelBuffer(buffer);
      showToast('تم تحديث البيانات تلقائياً من ملف البصمة', 'success');
    } catch (e) {
      console.info('Biometric file not found — use Import page to load manually.');
    }
  }

  // 5. Final UI Refresh
  if (currentPage === 'timesheet') renderTimesheet();
  else if (currentPage === 'report') renderReport();
  else if (currentPage === 'employees') renderEmployeesTable();
  else if (currentPage === 'calendar') renderAttendanceCalendar();
  else if (document.getElementById('inpAttendance')) {
    // Only run the calculator recompute when its inputs are actually mounted.
    // On boot the default page's section loads lazily, so this ran against a
    // null form ("Octagon startup interrupted"). No behaviour change when present.
    validateDays();
    autoCalcEligibleFridays();
    recalculate();
  }
  financeRefreshAll();
  omniRefreshAll();

  // 6. Cleanup
  setTimeout(() => {
    hideLoadingOverlay('init-success');
    console.log('✨ System Ready');
  }, 500);

  // 7. Claude/Codex Project Status — persistent strip showing current focus + progress
  // (always visible, NOT dismissable; updated by the AI at the end of every section).
  checkClaudeProjectStatus();
  // 8. Claude/Codex Review Pointer — auto-navigate to the section the AI flagged for review
  // (dismissable via "تم الفحص" button; appears BELOW the status strip when active).
  checkClaudeReviewPointer();
  setTimeout(ensureAIChatLauncherFromApp, 650);
  } catch (error) {
    console.error('Octagon startup interrupted:', error);
    try {
      showToast('تعذر تحميل بعض أجزاء النظام، تم فتح الواجهة الأساسية.', 'warning');
    } catch (toastError) {}
  } finally {
    setTimeout(() => {
      hideLoadingOverlay('init-finally');
      console.log('System Ready');
    }, 500);
  }
});

// ═══════════ CLAUDE/CODEX PROJECT STATUS BANNER ═══════════
// Permanent strip at the top of every page showing the current project focus, recent
// completions, the next candidates, and overall progress. Not dismissable — always visible
// so the user can open the app any day and immediately see where the work stands. Maintained
// ===== OCTAGON AI PROJECT DETAILS =====
// The project status and review pointer files are published into the movable AI
// assistant. Fixed top banners were removed so the app keeps the full page height.
async function checkClaudeProjectStatus() {
  try {
    const res = await fetch('/claude-status.json', { cache: 'no-store' });
    if (!res.ok) return;
    const status = await res.json();
    if (!status || !status.currentFocus) return;
    publishProjectStatusToAi(status);
  } catch (e) {
    // Status file missing or invalid: no visible interruption.
  }
}

function publishProjectStatusToAi(status) {
  const oldBanner = document.getElementById('claudeStatusBanner');
  if (oldBanner) oldBanner.remove();
  document.body.classList.remove('has-status-banner');
  window.OctagonProjectStatus = status;
  window.PentagonProjectStatus = status; // compatibility for older integrations
  window.dispatchEvent(new CustomEvent('octagon:project-status', { detail: status }));
}

function renderClaudeProjectStatus(status) {
  publishProjectStatusToAi(status);
}

async function checkClaudeReviewPointer() {
  try {
    const res = await fetch('/claude-review-pointer.json', { cache: 'no-store' });
    if (!res.ok) return;
    const pointer = await res.json();
    if (!pointer || !pointer.target || !pointer.id) return;
    publishReviewPointerToAi(pointer);
  } catch (e) {
    // Pointer file missing, invalid, or unavailable: silently ignore.
  }
}

function publishReviewPointerToAi(pointer) {
  const oldBanner = document.getElementById('claudeReviewBanner');
  if (oldBanner) oldBanner.remove();
  document.body.classList.remove('has-review-banner');
  window.OctagonReviewPointer = pointer;
  window.PentagonReviewPointer = pointer; // compatibility for older integrations
  window.dispatchEvent(new CustomEvent('octagon:review-pointer', { detail: pointer }));
}

function renderClaudeReviewBanner(pointer) {
  publishReviewPointerToAi(pointer);
}

function dismissClaudeReviewBanner(id) {
  const list = JSON.parse(localStorage.getItem('octagon.reviewedSectionIds') || localStorage.getItem('pentagon.reviewedSectionIds') || '[]');
  if (!list.includes(id)) list.push(id);
  while (list.length > 50) list.shift();
  localStorage.setItem('octagon.reviewedSectionIds', JSON.stringify(list));
  const banner = document.getElementById('claudeReviewBanner');
  if (banner) banner.remove();
  document.body.classList.remove('has-review-banner');
  if (typeof showToast === 'function') showToast('?? ????? ????? ????????. ?????? ???????? ???? ???? ?????? ?????? ???????.', 'info');
}


// --- OMNISYSTEM Operating Layer ---
let omniDraggedCardId = null;
let omniDraggedNodeType = null;

const KANBAN_CARD_COLORS = ['default', 'blue', 'green', 'yellow', 'orange', 'red', 'purple', 'cyan', 'pink', 'slate', 'custom'];
const KANBAN_COLOR_PRESETS = {
  default: '#94a3b8',
  blue: '#38bdf8',
  green: '#34d399',
  yellow: '#fbbf24',
  orange: '#fb923c',
  red: '#f87171',
  purple: '#a78bfa',
  cyan: '#22d3ee',
  pink: '#f472b6',
  slate: '#64748b'
};
const KANBAN_COLUMN_STYLES = [
  { value: 'glass', label: 'زجاجي هادئ' },
  { value: 'solid', label: 'لون واضح' },
  { value: 'outline', label: 'إطار فقط' },
  { value: 'soft', label: 'خلفية ناعمة' }
];
const DEFAULT_OMNI_DEPARTMENTS = ['Octagon', 'قسم الليزر', 'قسم الراوتر', 'قسم الطباعة ثلاثية الأبعاد', 'قسم الجودة', 'فريق الورشة', 'الإدارة'];

function priorityClass(priority) {
  const p = String(priority || '').toLowerCase();
  if (p.includes('urgent')) return 'priority-urgent';
  if (p.includes('high')) return 'priority-high';
  if (p.includes('low')) return 'priority-low';
  return 'priority-normal';
}

function getKanbanCardColor(card) {
  const color = card?.color || card?.accentColor || 'default';
  return KANBAN_CARD_COLORS.includes(color) ? color : 'default';
}

function normalizeKanbanHexColor(value, fallback = '#38bdf8') {
  const v = String(value || '').trim();
  return /^#[0-9a-f]{6}$/i.test(v) ? v : fallback;
}

function getKanbanColorHex(keyOrHex, fallback = '#94a3b8') {
  const key = String(keyOrHex || '').trim();
  if (KANBAN_COLOR_PRESETS[key]) return KANBAN_COLOR_PRESETS[key];
  return normalizeKanbanHexColor(key, fallback);
}

function getKanbanCardAccentHex(card) {
  const color = getKanbanCardColor(card);
  if (color === 'custom') return normalizeKanbanHexColor(card?.customColor || card?.accentHex, '#38bdf8');
  return getKanbanColorHex(color, '#94a3b8');
}

function getKanbanColorOptions(selected = 'default') {
  const labels = {
    default: 'افتراضي',
    blue: 'أزرق',
    green: 'أخضر',
    yellow: 'أصفر',
    orange: 'برتقالي',
    red: 'أحمر',
    purple: 'بنفسجي',
    cyan: 'سماوي',
    pink: 'وردي',
    slate: 'رصاصي',
    custom: 'لون مخصص'
  };
  return KANBAN_CARD_COLORS.map(color => `<option value="${color}" ${selected === color ? 'selected' : ''}>${labels[color] || color}</option>`).join('');
}

function getKanbanDueProximity(card) {
  if (!card?.dueDate || kanbanCardIsDone(card)) return 0;
  const today = new Date(`${todayISO()}T00:00:00`);
  const due = new Date(`${card.dueDate}T00:00:00`);
  if (Number.isNaN(due.getTime())) return 0;
  const diffDays = Math.ceil((due.getTime() - today.getTime()) / 86400000);
  if (diffDays < 0) return 1;
  if (diffDays === 0) return 0.9;
  if (diffDays === 1) return 0.72;
  if (diffDays <= 3) return 0.5;
  if (diffDays <= 7) return 0.28;
  return 0.08;
}

function getKanbanCardStyleVars(card) {
  const accent = getKanbanCardAccentHex(card);
  const dueAlpha = Math.min(0.46, Math.max(0, getKanbanDueProximity(card) * 0.46));
  const colorAlpha = getKanbanCardColor(card) === 'default' ? 0.06 : 0.16;
  return `--card-accent:${accent};--card-color-alpha:${colorAlpha.toFixed(2)};--due-alpha:${dueAlpha.toFixed(2)};`;
}

function getKanbanColumnStyle(col) {
  const color = normalizeKanbanHexColor(col?.color || col?.accentColor, '#38bdf8');
  const tone = Math.min(0.28, Math.max(0, Number(col?.bodyTone ?? 0.08)));
  return `--column-color:${color};--column-tone:${tone.toFixed(2)};--column-tone-percent:${Math.round(tone * 100)}%;`;
}

function getKanbanColumnClass(col) {
  const style = KANBAN_COLUMN_STYLES.some(item => item.value === col?.headerStyle) ? col.headerStyle : 'glass';
  return `kanban-column-style-${style}`;
}

function getCardAssigneeName(card) {
  const emp = (employees || []).find(e => String(e.id || e.name) === String(card.assigneeId));
  return emp?.name || card.owner || card.assignedTo || '-';
}

function getKanbanAssigneeKey(card) {
  return String(card.assigneeId || card.assignedTo || card.owner || card.employeeId || '');
}

function getKanbanDepartmentName(card) {
  return card.department || card.section || card.branch || card.owner || card.assignedTo || 'غير مصنف';
}

function getKanbanEstimate(card) {
  return Number(card.estimatedMinutes || card.estimateMinutes || card.durationMinutes || card.minutes || 0) || 0;
}

function kanbanColumnLooksDone(column) {
  const title = String(column?.title || column?.name || '').toLowerCase();
  return ['done', 'complete', 'completed', 'review', 'مكتمل', 'منجز', 'مراجعة'].some(x => title.includes(x));
}

function kanbanColumnLooksActive(column) {
  const title = String(column?.title || column?.name || '').toLowerCase();
  return ['progress', 'doing', 'active', 'تنفيذ', 'قيد', 'عمل'].some(x => title.includes(x));
}

function kanbanCardIsDone(card) {
  const col = (omni.kanban?.columns || []).find(c => c.id === card.columnId);
  const status = String(card.status || '').toLowerCase();
  return kanbanColumnLooksDone(col) || ['done', 'complete', 'completed', 'مكتمل', 'منجز'].some(x => status.includes(x));
}

function kanbanCardIsBlocked(card) {
  const status = String(card.status || '').toLowerCase();
  return !!card.isBlocked || status.includes('block') || status.includes('تعليق') || status.includes('متوقف') || (card.tags || []).some(t => String(t).toLowerCase().includes('blocked') || String(t).includes('متوقف'));
}

function kanbanCardHasFailedQc(card) {
  return (card.qcRecordIds || []).map(id => getQcRecordById(id)).filter(Boolean).some(q => String(q.result || '').toLowerCase() === 'fail');
}

function kanbanCardQcStatus(card) {
  const qcs = (card.qcRecordIds || []).map(id => getQcRecordById(id)).filter(Boolean);
  if (!qcs.length) return 'none';
  if (qcs.some(q => String(q.result || '').toLowerCase() === 'fail')) return 'fail';
  if (qcs.some(q => String(q.result || '').toLowerCase() === 'pending')) return 'pending';
  return 'pass';
}

function calculateKanbanCardRisk(card) {
  const reasons = [];
  let score = 0;
  const dueRisk = calculateDueRisk(card);
  const priority = String(card.priority || '').toLowerCase();
  const matStatus = calculateMaterialAvailability(card);
  if (dueRisk === 'overdue' && !kanbanCardIsDone(card)) { score += 28; reasons.push('متأخرة'); }
  if (dueRisk === 'due_today' && kanbanChecklistProgress(card) < 100) { score += 14; reasons.push('استحقاق اليوم'); }
  if (priority.includes('urgent')) { score += 20; reasons.push('أولوية حرجة'); }
  else if (priority.includes('high')) { score += 12; reasons.push('أولوية عالية'); }
  if (!getKanbanAssigneeKey(card)) { score += 12; reasons.push('بدون مسؤول'); }
  if (!(card.sopIds || []).length) { score += 10; reasons.push('SOP غير مربوط'); }
  if ((card.requiresMachine || (card.tags || []).some(t => /machine|cnc|laser|router|ماكينة|ليزر|راوتر/i.test(String(t)))) && !(card.machineIds || []).length) { score += 12; reasons.push('ماكينة غير محددة'); }
  if (matStatus === 'missing') { score += 16; reasons.push('مواد ناقصة'); }
  if (kanbanCardHasFailedQc(card)) { score += 22; reasons.push('QC فاشل'); }
  if (kanbanCardIsBlocked(card)) { score += 20; reasons.push('معلقة'); }
  const deps = card.dependencies || card.blockedBy || [];
  if (deps.length) {
    const openDeps = deps.filter(id => {
      const depCard = (omni.kanban?.cards || []).find(c => c.id === id);
      return depCard && !kanbanCardIsDone(depCard);
    }).length;
    if (openDeps) { score += Math.min(18, openDeps * 9); reasons.push('اعتمادات غير مكتملة'); }
  }
  score = Math.min(100, score);
  const level = score >= 70 ? 'critical' : score >= 46 ? 'high' : score >= 22 ? 'medium' : 'low';
  const labels = { low: 'منخفض', medium: 'متوسط', high: 'عالي', critical: 'حرج' };
  return { level, score, reasons, badges: reasons.slice(0, 3), label: labels[level] };
}

function calculateKanbanBoardHealth() {
  ensureOmni();
  const cards = omni.kanban.cards || [];
  const openCards = cards.filter(c => !kanbanCardIsDone(c));
  const risks = cards.map(c => calculateKanbanCardRisk(c));
  const materialBlockedCards = openCards.filter(c => calculateMaterialAvailability(c) === 'missing').length;
  const machinePressure = calculateKanbanMachinePressure();
  const machineBlockedCards = openCards.filter(c => (c.machineIds || []).some(id => {
    const m = getMachineById(id);
    return m && /maintenance|offline|down|تعطل|صيانة/i.test(String(m.status || ''));
  })).length;
  const missingSop = openCards.filter(c => !(c.sopIds || []).length).length;
  const failedQc = openCards.filter(kanbanCardHasFailedQc).length;
  const overdueCards = openCards.filter(c => calculateDueRisk(c) === 'overdue').length;
  const urgentCards = openCards.filter(c => String(c.priority || '').toLowerCase().includes('urgent')).length;
  const noAssigneeCards = openCards.filter(c => !getKanbanAssigneeKey(c)).length;
  const urgentNotStarted = openCards.filter(c => String(c.priority || '').toLowerCase().includes('urgent') && !kanbanColumnLooksActive((omni.kanban.columns || []).find(col => col.id === c.columnId))).length;
  const penalty = overdueCards * 9 + materialBlockedCards * 10 + machineBlockedCards * 8 + missingSop * 3 + failedQc * 12 + noAssigneeCards * 5 + urgentNotStarted * 7 + risks.filter(r => r.level === 'critical').length * 8;
  const healthScore = Math.max(0, Math.min(100, 100 - penalty));
  const status = healthScore >= 85 ? 'ممتاز' : healthScore >= 68 ? 'جيد' : healthScore >= 45 ? 'يحتاج متابعة' : 'خطر';
  const warnings = [];
  if (overdueCards) warnings.push(`${overdueCards} بطاقات متأخرة`);
  if (materialBlockedCards) warnings.push(`${materialBlockedCards} مواد ناقصة`);
  if (machinePressure.some(m => m.score >= 75)) warnings.push('مكائن مزدحمة');
  return { totalCards: cards.length, activeCards: openCards.filter(c => kanbanColumnLooksActive((omni.kanban.columns || []).find(col => col.id === c.columnId))).length, overdueCards, urgentCards, noAssigneeCards, materialBlockedCards, machineBlockedCards, healthScore, status, warnings };
}

function getKanbanDepartmentStatus(score) {
  if (score >= 80) return { label: 'خطر', color: '#f87171' };
  if (score >= 60) return { label: 'مزدحم', color: '#fb923c' };
  if (score >= 35) return { label: 'مشغول', color: '#fbbf24' };
  return { label: 'طبيعي', color: '#34d399' };
}

function calculateKanbanDepartmentLoad() {
  ensureOmni();
  const groups = {};
  (omni.kanban.cards || []).filter(c => !kanbanCardIsDone(c)).forEach(card => {
    const name = getKanbanDepartmentName(card);
    if (!groups[name]) groups[name] = { name, openCards: 0, inProgressCards: 0, overdueCards: 0, urgentCards: 0, estimatedMinutes: 0, blockedCards: 0 };
    const g = groups[name];
    g.openCards++;
    if (kanbanColumnLooksActive((omni.kanban.columns || []).find(col => col.id === card.columnId))) g.inProgressCards++;
    if (calculateDueRisk(card) === 'overdue') g.overdueCards++;
    if (String(card.priority || '').toLowerCase().includes('urgent')) g.urgentCards++;
    if (kanbanCardIsBlocked(card) || calculateMaterialAvailability(card) === 'missing' || kanbanCardHasFailedQc(card)) g.blockedCards++;
    g.estimatedMinutes += getKanbanEstimate(card);
  });
  return Object.values(groups).map(g => {
    g.workloadScore = Math.min(100, g.openCards * 8 + g.inProgressCards * 8 + g.overdueCards * 16 + g.urgentCards * 12 + g.blockedCards * 14 + (g.estimatedMinutes / 60) * 3);
    g.status = getKanbanDepartmentStatus(g.workloadScore);
    return g;
  }).sort((a, b) => b.workloadScore - a.workloadScore);
}

function getKanbanEmployeeLoadStatus(score) {
  if (score >= 78) return { label: 'الموظف مضغوط', color: '#f87171' };
  if (score >= 46) return { label: 'مشغول', color: '#fbbf24' };
  if (score <= 18) return { label: 'يمكن تحويل مهمة إليه', color: '#34d399' };
  return { label: 'الموظف متاح', color: '#38bdf8' };
}

function calculateKanbanEmployeeLoad() {
  ensureOmni();
  const groups = {};
  (employees || []).forEach(emp => {
    const key = String(emp.id || emp.name);
    groups[key] = { id: key, name: emp.name || key, openCards: 0, overdueCards: 0, urgentCards: 0, inProgressCards: 0, checklistDone: 0, checklistTotal: 0 };
  });
  (omni.kanban.cards || []).filter(c => !kanbanCardIsDone(c)).forEach(card => {
    const key = getKanbanAssigneeKey(card) || 'unassigned';
    if (!groups[key]) groups[key] = { id: key, name: getCardAssigneeName(card) || 'بدون مسؤول', openCards: 0, overdueCards: 0, urgentCards: 0, inProgressCards: 0, checklistDone: 0, checklistTotal: 0 };
    const g = groups[key];
    g.openCards++;
    if (calculateDueRisk(card) === 'overdue') g.overdueCards++;
    if (String(card.priority || '').toLowerCase().includes('urgent')) g.urgentCards++;
    if (kanbanColumnLooksActive((omni.kanban.columns || []).find(col => col.id === card.columnId))) g.inProgressCards++;
    (card.checklist || []).forEach(item => { g.checklistTotal++; if (item.done) g.checklistDone++; });
  });
  return Object.values(groups).filter(g => g.openCards > 0 || g.id !== 'unassigned').map(g => {
    g.checklistAverage = g.checklistTotal ? Math.round((g.checklistDone / g.checklistTotal) * 100) : 0;
    g.loadScore = Math.min(100, g.openCards * 12 + g.inProgressCards * 10 + g.overdueCards * 18 + g.urgentCards * 14);
    g.status = getKanbanEmployeeLoadStatus(g.loadScore);
    return g;
  }).sort((a, b) => b.loadScore - a.loadScore);
}

function calculateKanbanMachinePressure() {
  ensureOmni();
  return (omni.machines || []).map(machine => {
    const linkedCards = (omni.kanban.cards || []).filter(c => !kanbanCardIsDone(c) && (c.machineIds || []).includes(machine.id));
    const queueLength = Array.isArray(machine.queue) ? machine.queue.length : 0;
    const estimatedMinutes = linkedCards.reduce((sum, card) => sum + getKanbanEstimate(card), 0);
    const unavailable = /maintenance|offline|down|تعطل|صيانة/i.test(String(machine.status || ''));
    const bottleneckScore = Math.min(100, queueLength * 14 + linkedCards.length * 13 + (estimatedMinutes / 60) * 4 + (unavailable ? 35 : 0));
    return { id: machine.id, name: machine.name || machine.id, status: machine.status || 'ready', queueLength, linkedCards: linkedCards.length, estimatedMinutes, bottleneckScore, score: bottleneckScore, unavailable };
  }).sort((a, b) => b.bottleneckScore - a.bottleneckScore);
}

function calculateKanbanColumnStats(column) {
  const cards = getFilteredKanbanCards(omni.kanban.cards || []).filter(card => card.columnId === column.id);
  const overdueCards = cards.filter(c => calculateDueRisk(c) === 'overdue').length;
  const estimatedMinutes = cards.reduce((sum, card) => sum + getKanbanEstimate(card), 0);
  const riskScore = cards.length ? Math.round(cards.reduce((sum, card) => sum + calculateKanbanCardRisk(card).score, 0) / cards.length) : 0;
  return { cards, count: cards.length, wipLimit: column.wip || column.wipLimit || 8, overdueCards, estimatedMinutes, healthScore: Math.max(0, 100 - riskScore), wipExceeded: cards.length > (column.wip || column.wipLimit || 8) };
}

function getKanbanBigScreenMode() {
  return localStorage.getItem('kanban_bigscreen_mode') === 'true';
}

function toggleKanbanBigScreenMode() {
  localStorage.setItem('kanban_bigscreen_mode', String(!getKanbanBigScreenMode()));
  renderKanbanBoard();
}

function getKanbanDensity() {
  return localStorage.getItem('kanban_density') || 'comfortable';
}

function toggleKanbanDensity() {
  localStorage.setItem('kanban_density', getKanbanDensity() === 'compact' ? 'comfortable' : 'compact');
  renderKanbanBoard();
}

function renderHelpMarker(text) {
  return `<span class="omni-help-marker" title="${String(text).replace(/"/g, '&quot;')}">?</span>`;
}

let kanbanViewMode = 'board';
function toggleKanbanView() { setKanbanViewMode(kanbanViewMode === 'board' ? 'list' : 'board'); }
function setKanbanViewMode(mode) { kanbanViewMode = mode || 'board'; renderKanbanBoard(); }

let kanbanGroupBy = 'none';
function setKanbanGroupBy(mode) { kanbanGroupBy = mode || 'none'; renderKanbanBoard(); }

let kanbanFilters = {
  search: "",
  owner: "all",
  assigneeId: "all",
  priority: "all",
  department: "all",
  machineId: "all",
  risk: "all",
  due: "all",
  qc: "all",
  sop: "all",
  status: "all"
};
let omniKanbanFilters = kanbanFilters;

function updateKanbanFilters(patch) {
  kanbanFilters = { ...kanbanFilters, ...patch };
  omniKanbanFilters = kanbanFilters;
  renderKanbanBoard();
}

function resetKanbanFilters() {
  kanbanFilters = { search: "", owner: "all", assigneeId: "all", priority: "all", department: "all", machineId: "all", risk: "all", due: "all", qc: "all", sop: "all", status: "all" };
  omniKanbanFilters = kanbanFilters;
  kanbanGroupBy = 'none';
  renderKanbanBoard();
}

function setKanbanFilter(key, val) {
  const map = { assignee: 'assigneeId' };
  updateKanbanFilters({ [map[key] || key]: val || 'all' });
}

function cardMatchesKanbanFilters(card, filters = kanbanFilters) {
  const f = filters || kanbanFilters;
  const search = String(f.search || '').trim().toLowerCase();
  if (search) {
    const haystack = [card.title, card.description, card.clientName, card.client, card.owner, card.assignedTo, ...(card.tags || [])].join(' ').toLowerCase();
    if (!haystack.includes(search)) return false;
  }
  const assigneeKey = getKanbanAssigneeKey(card);
  if (f.owner !== 'all' && String(card.owner || card.assignedTo || '') !== String(f.owner)) return false;
  if (f.assigneeId !== 'all' && String(assigneeKey) !== String(f.assigneeId)) return false;
  if (f.priority !== 'all' && String(card.priority || 'Normal') !== String(f.priority)) return false;
  if (f.department !== 'all' && getKanbanDepartmentName(card) !== f.department) return false;
  if (f.machineId !== 'all' && !(card.machineIds || []).includes(f.machineId)) return false;
  if (f.risk !== 'all' && calculateKanbanCardRisk(card).level !== f.risk) return false;
  if (f.status !== 'all' && String(card.columnId || card.status || '') !== String(f.status)) return false;
  if (f.sop === 'linked' && !(card.sopIds || []).length) return false;
  if (f.sop === 'missing' && (card.sopIds || []).length) return false;
  const matStatus = calculateMaterialAvailability(card);
  if (f.qc !== 'all' && kanbanCardQcStatus(card) !== f.qc) return false;
  if (f.risk === 'materials_missing' && matStatus !== 'missing') return false;
  if (f.due !== 'all') {
    const dueRisk = calculateDueRisk(card);
    const today = todayISO();
    const due = card.dueDate ? new Date(card.dueDate) : null;
    const weekEnd = new Date(); weekEnd.setDate(weekEnd.getDate() + 7);
    if (f.due === 'today' && dueRisk !== 'due_today') return false;
    if (f.due === 'overdue' && dueRisk !== 'overdue') return false;
    if (f.due === 'no_due' && card.dueDate) return false;
    if (f.due === 'this_week' && (!due || card.dueDate < today || due > weekEnd)) return false;
  }
  return true;
}

function getFilteredKanbanCards(cards) {
  return (cards || []).filter(card => cardMatchesKanbanFilters(card, kanbanFilters));
}

function renderKanbanBoard() {
  ensureOmni();
  const board = document.getElementById('omniKanbanBoard');
  if (!board) return;
  if (kanbanViewMode === 'list' || kanbanViewMode === 'table') return renderKanbanListView();
  if (kanbanViewMode === 'workload') return renderKanbanWorkloadView();
  renderKanbanBoardView();
}

function renderKanbanToolbar() {
  const cards = omni.kanban.cards || [];
  const assignees = [...new Map(cards.map(c => [getKanbanAssigneeKey(c), getCardAssigneeName(c)]).filter(([id]) => id)).entries()];
  const owners = [...new Set(cards.map(c => c.owner || c.assignedTo).filter(Boolean))];
  const departments = [...new Set(cards.map(getKanbanDepartmentName).filter(Boolean))];
  const machines = omni.machines || [];
  const columns = omni.kanban.columns || [];
  const option = (value, label, selected) => `<option value="${escapeHtml(value)}" ${String(selected) === String(value) ? 'selected' : ''}>${escapeHtml(label)}</option>`;
  return `
    <div class="kanban-board-toolbar">
      <div class="kanban-view-tabs">
        <button class="${kanbanViewMode === 'board' ? 'active' : ''}" onclick="setKanbanViewMode('board')"><i class="fa-solid fa-table-columns"></i> لوحة</button>
        <button class="${kanbanViewMode === 'list' ? 'active' : ''}" onclick="setKanbanViewMode('list')"><i class="fa-solid fa-list"></i> قائمة</button>
        <button class="${kanbanViewMode === 'workload' ? 'active' : ''}" onclick="setKanbanViewMode('workload')"><i class="fa-solid fa-chart-simple"></i> عبء العمل</button>
      </div>
      <div class="kanban-filter-grid">
        <input class="kanban-filter-control" value="${escapeHtml(kanbanFilters.search)}" placeholder="بحث" oninput="updateKanbanFilters({search:this.value})">
        <select class="kanban-filter-control" onchange="updateKanbanFilters({assigneeId:this.value})">${option('all', 'كل المسؤولين', kanbanFilters.assigneeId)}${assignees.map(([id, name]) => option(id, name, kanbanFilters.assigneeId)).join('')}</select>
        <select class="kanban-filter-control" onchange="updateKanbanFilters({priority:this.value})">${option('all', 'كل الأولويات', kanbanFilters.priority)}${[['Urgent','عاجل'],['High','عالي'],['Normal','عادي'],['Low','منخفض']].map(([v,l]) => option(v, l, kanbanFilters.priority)).join('')}</select>
        <select class="kanban-filter-control" onchange="updateKanbanFilters({department:this.value})">${option('all', 'كل الأقسام', kanbanFilters.department)}${departments.map(d => option(d, d, kanbanFilters.department)).join('')}</select>
        <select class="kanban-filter-control" onchange="updateKanbanFilters({machineId:this.value})">${option('all', 'كل المكائن', kanbanFilters.machineId)}${machines.map(m => option(m.id, m.name || m.id, kanbanFilters.machineId)).join('')}</select>
        <select class="kanban-filter-control" onchange="updateKanbanFilters({status:this.value})">${option('all', 'كل الحالات', kanbanFilters.status)}${columns.map(c => option(c.id, c.title || c.name || c.id, kanbanFilters.status)).join('')}</select>
        <select class="kanban-filter-control" onchange="updateKanbanFilters({risk:this.value})">
          ${option('all', 'كل المخاطر', kanbanFilters.risk)}
          ${option('critical', 'حرج', kanbanFilters.risk)}
          ${option('high', 'عالي', kanbanFilters.risk)}
          ${option('medium', 'متوسط', kanbanFilters.risk)}
          ${option('low', 'منخفض', kanbanFilters.risk)}
        </select>
        <select class="kanban-filter-control" onchange="updateKanbanFilters({due:this.value})">
          ${option('all', 'تاريخ الاستحقاق', kanbanFilters.due)}
          ${option('today', 'اليوم', kanbanFilters.due)}
          ${option('overdue', 'متأخر', kanbanFilters.due)}
          ${option('this_week', 'هذا الأسبوع', kanbanFilters.due)}
          ${option('no_due', 'بدون موعد', kanbanFilters.due)}
        </select>
        <select class="kanban-filter-control" onchange="updateKanbanFilters({qc:this.value})">${option('all', 'كل QC', kanbanFilters.qc)}${option('pass', 'QC ناجح', kanbanFilters.qc)}${option('fail', 'QC فاشل', kanbanFilters.qc)}${option('pending', 'QC معلق', kanbanFilters.qc)}${option('none', 'بدون QC', kanbanFilters.qc)}</select>
        <select class="kanban-filter-control" onchange="updateKanbanFilters({sop:this.value})">${option('all', 'كل SOP', kanbanFilters.sop)}${option('linked', 'SOP مربوط', kanbanFilters.sop)}${option('missing', 'SOP مفقود', kanbanFilters.sop)}</select>
        <select class="kanban-filter-control" style="border: 1px solid rgba(34, 211, 238, 0.3); background: rgba(34, 211, 238, 0.1); color: #22d3ee;" onchange="setKanbanGroupBy(this.value)">
          <option value="none" ${kanbanGroupBy === 'none' ? 'selected' : ''} style="background:#0f172a; color:#fff;">تجميع حسب: بدون تجميع</option>
          <option value="project" ${kanbanGroupBy === 'project' ? 'selected' : ''} style="background:#0f172a; color:#fff;">تجميع حسب: العميل / المشروع</option>
          <option value="assignee" ${kanbanGroupBy === 'assignee' ? 'selected' : ''} style="background:#0f172a; color:#fff;">تجميع حسب: الموظف المسند</option>
          <option value="machine" ${kanbanGroupBy === 'machine' ? 'selected' : ''} style="background:#0f172a; color:#fff;">تجميع حسب: الماكينة</option>
          <option value="department" ${kanbanGroupBy === 'department' ? 'selected' : ''} style="background:#0f172a; color:#fff;">تجميع حسب: القسم</option>
        </select>
      </div>
      <div class="kanban-toolbar-actions">
        <button class="btn-ghost" onclick="toggleKanbanBigScreenMode()"><i class="fa-solid fa-display"></i> وضع الشاشة الكبيرة</button>
        <button class="btn-ghost" onclick="toggleKanbanDensity()"><i class="fa-solid fa-grip"></i> ${getKanbanDensity() === 'compact' ? 'مريح' : 'مضغوط'}</button>
        <button class="btn-ghost" onclick="resetKanbanFilters()"><i class="fa-solid fa-rotate-left"></i> إعادة ضبط</button>
      </div>
    </div>`;
}

function renderKanbanExecutiveSummary() {
  const health = calculateKanbanBoardHealth();
  const metrics = [
    ['إجمالي البطاقات', health.totalCards, 'fa-layer-group'],
    ['قيد التنفيذ', health.activeCards, 'fa-person-running'],
    ['متأخرة', health.overdueCards, 'fa-clock'],
    ['حرجة', (omni.kanban.cards || []).filter(c => calculateKanbanCardRisk(c).level === 'critical').length, 'fa-triangle-exclamation'],
    ['بدون مسؤول', health.noAssigneeCards, 'fa-user-slash'],
    ['مواد ناقصة', health.materialBlockedCards, 'fa-box-open'],
    ['مكائن مزدحمة', calculateKanbanMachinePressure().filter(m => m.score >= 75).length, 'fa-gears'],
    ['صحة اللوحة', `${health.healthScore}%`, 'fa-heart-pulse']
  ];
  return `
    <div class="kanban-exec-summary">
      ${metrics.map(([label, value, icon]) => `<div class="kanban-kpi"><i class="fa-solid ${icon}"></i><span>${label}</span><b>${value}</b></div>`).join('')}
      <div class="kanban-health-banner kanban-health-${health.status === 'خطر' ? 'danger' : health.status === 'يحتاج متابعة' ? 'warn' : 'good'}">
        <b>${health.status}</b><span>${health.warnings.join(' · ') || 'اللوحة مستقرة تشغيلياً'}</span>
      </div>
    </div>`;
}

function renderLoadChip(item, type) {
  const score = item.workloadScore ?? item.loadScore ?? item.bottleneckScore ?? item.score ?? 0;
  const status = item.status || getKanbanDepartmentStatus(score);
  const count = item.openCards ?? item.linkedCards ?? 0;
  return `
    <button class="kanban-load-chip" onclick="updateKanbanFilters({${type === 'department' ? `department:'${String(item.name).replace(/'/g, "\\'")}'` : type === 'employee' ? `assigneeId:'${String(item.id).replace(/'/g, "\\'")}'` : `machineId:'${String(item.id).replace(/'/g, "\\'")}'`}})">
      <span class="kanban-load-title">${escapeHtml(item.name)}</span>
      <span class="kanban-load-meta">${count} مفتوحة · ${item.overdueCards || 0} متأخرة</span>
      <span class="kanban-load-bar"><i style="width:${Math.min(100, score)}%;background:${status.color || (item.unavailable ? '#f87171' : '#38bdf8')}"></i></span>
      <small style="color:${status.color || '#cbd5e1'}">${escapeHtml(status.label || translateMachineStatus(item.status) || '')}</small>
    </button>`;
}

function renderKanbanWorkloadPanel() {
  const departments = calculateKanbanDepartmentLoad().slice(0, 8);
  const employeesLoad = calculateKanbanEmployeeLoad().slice(0, 8);
  const machines = calculateKanbanMachinePressure().slice(0, 8);
  return `
    <div class="kanban-workload-panel">
      <section><h3>ضغط الأقسام</h3><div class="kanban-load-row">${departments.map(d => renderLoadChip(d, 'department')).join('') || '<div class="kanban-empty-inline">لا توجد بطاقات هنا حالياً</div>'}</div></section>
      <section><h3>ضغط الموظفين</h3><div class="kanban-load-row">${employeesLoad.map(e => renderLoadChip(e, 'employee')).join('') || '<div class="kanban-empty-inline">لا توجد مهام مسندة</div>'}</div></section>
      <section><h3>ضغط المكائن</h3><div class="kanban-load-row">${machines.map(m => renderLoadChip({ ...m, name: m.name, openCards: m.linkedCards, overdueCards: m.queueLength, status: { label: m.unavailable ? 'صيانة / متوقفة' : translateMachineStatus(m.status), color: m.unavailable ? '#f87171' : '#38bdf8' } }, 'machine')).join('') || '<div class="kanban-empty-inline">لم يتم تحديد ماكينة لهذه البطاقة</div>'}</div></section>
    </div>`;
}

function renderKanbanBoardView() {
  const board = document.getElementById('omniKanbanBoard');
  const shellClasses = ['kanban-executive-board', getKanbanBigScreenMode() ? 'kanban-bigscreen-mode' : '', `kanban-density-${getKanbanDensity()}`].join(' ');
  const totalFiltered = getFilteredKanbanCards(omni.kanban.cards || []).length;
  board.className = 'omni-kanban-board kanban-board-shell';
  
  let boardContentHtml = '';
  
  if (kanbanGroupBy === 'none') {
    boardContentHtml = `
      <div class="kanban-board-grid">
        ${(omni.kanban.columns || []).map(col => {
          const stats = calculateKanbanColumnStats(col);
          return `
            <div class="kanban-column-v2 omni-kanban-col ${getKanbanColumnClass(col)}" style="${getKanbanColumnStyle(col)}" ondragover="event.preventDefault(); this.classList.add('kanban-column-drop-active')" ondragleave="this.classList.remove('kanban-column-drop-active')" ondrop="omniDropCard(event, '${col.id}'); this.classList.remove('kanban-column-drop-active')">
              <div class="kanban-column-header-group" style="border-top-color:${normalizeKanbanHexColor(col.color, '#38bdf8')}">
                <div class="kanban-column-header-v2">
                  <div><b>${escapeHtml(col.title || col.name || 'Column')}</b><span style="margin-right: 8px; font-size: 0.8rem; color: var(--text-muted);">${stats.count} بطاقة · WIP ${stats.count}/${stats.wipLimit}</span></div>
                  <div class="col-head-actions">
                    <button class="icon-btn" onclick="editKanbanColumnStyle('${col.id}')" title="تنسيق العمود"><i class="fa-solid fa-palette"></i></button>
                    <button class="icon-btn" onclick="addKanbanCard('${col.id}')" title="إضافة بطاقة"><i class="fa-solid fa-plus"></i></button>
                    <button class="icon-btn icon-btn-danger" onclick="deleteKanbanColumn('${col.id}')" title="حذف العمود"><i class="fa-solid fa-trash"></i></button>
                  </div>
                </div>
                <div class="kanban-column-stats ${stats.wipExceeded ? 'wip-over' : ''}">
                  <span>${stats.wipExceeded ? 'تجاوز حد WIP' : 'WIP طبيعي'}</span>
                  <span>متأخرة: ${stats.overdueCards}</span>
                  <span>${stats.estimatedMinutes} دقيقة</span>
                </div>
              </div>
              <div class="kanban-column-body-v2 omni-card-list">
                ${stats.cards.map(renderKanbanCardV2).join('') || '<div class="kanban-column-empty">لا توجد بطاقات هنا حالياً</div>'}
              </div>
            </div>`;
        }).join('')}
      </div>
    `;
  } else {
    const filteredCards = getFilteredKanbanCards(omni.kanban.cards || []);
    const groupsMap = {};
    filteredCards.forEach(card => {
      let groupKey = 'none';
      if (kanbanGroupBy === 'project') {
        groupKey = card.clientName || card.client || "بدون عميل / مشروع";
      } else if (kanbanGroupBy === 'assignee') {
        groupKey = getCardAssigneeName(card) || "غير مسند";
        if (groupKey === '-') groupKey = "غير مسند";
      } else if (kanbanGroupBy === 'machine') {
        const mId = card.machineIds?.[0] || card.machineId;
        const machine = mId ? getMachineById(mId) : null;
        groupKey = machine ? (machine.name || machine.id) : "بدون ماكينة";
      } else if (kanbanGroupBy === 'department') {
        groupKey = getKanbanDepartmentName(card) || "غير مصنف";
      }
      if (!groupsMap[groupKey]) {
        groupsMap[groupKey] = [];
      }
      groupsMap[groupKey].push(card);
    });

    const groupNames = Object.keys(groupsMap).sort((a, b) => {
      const fallbacks = ["بدون عميل / مشروع", "غير مسند", "بدون ماكينة", "غير مصنف", "none"];
      const aIsFallback = fallbacks.includes(a);
      const bIsFallback = fallbacks.includes(b);
      if (aIsFallback && !bIsFallback) return 1;
      if (!aIsFallback && bIsFallback) return -1;
      return a.localeCompare(b, 'ar');
    });

    let groupIcon = '<i class="fa-solid fa-folder-open"></i>';
    if (kanbanGroupBy === 'project') groupIcon = '<i class="fa-solid fa-diagram-project"></i>';
    if (kanbanGroupBy === 'assignee') groupIcon = '<i class="fa-solid fa-user-gear"></i>';
    if (kanbanGroupBy === 'machine') groupIcon = '<i class="fa-solid fa-gears"></i>';
    if (kanbanGroupBy === 'department') groupIcon = '<i class="fa-solid fa-sitemap"></i>';

    boardContentHtml = groupNames.map(groupName => {
      const groupCards = groupsMap[groupName];
      return `
        <div class="kanban-swimlane-row" style="margin-bottom: 24px;">
          <div class="kanban-swimlane-header" style="background: rgba(15, 23, 42, 0.45); backdrop-filter: blur(8px); border-radius: 8px; padding: 10px 16px; margin: 15px 0 10px 0; font-weight: bold; border: 1px solid rgba(34, 211, 238, 0.15); display: flex; align-items: center; justify-content: space-between; gap: 10px; box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);">
            <div style="display: flex; align-items: center; gap: 10px; font-size: 1.05rem; color: #22d3ee;">
              ${groupIcon}
              <span>${escapeHtml(groupName)}</span>
            </div>
            <span style="font-size: 0.8rem; background: rgba(34, 211, 238, 0.1); color: #22d3ee; padding: 3px 10px; border-radius: 20px; border: 1px solid rgba(34, 211, 238, 0.15);">${groupCards.length} بطاقة</span>
          </div>
          
          <div class="kanban-board-grid" style="min-height: auto; padding-bottom: 10px;">
            ${(omni.kanban.columns || []).map(col => {
              const colCards = groupCards.filter(card => card.columnId === col.id);
              const overdueCards = colCards.filter(c => calculateDueRisk(c) === 'overdue').length;
              const estimatedMinutes = colCards.reduce((sum, card) => sum + getKanbanEstimate(card), 0);
              const riskScore = colCards.length ? Math.round(colCards.reduce((sum, card) => sum + calculateKanbanCardRisk(card).score, 0) / colCards.length) : 0;
              const wipLimit = col.wip || col.wipLimit || 8;
              const wipExceeded = colCards.length > wipLimit;
              const stats = { cards: colCards, count: colCards.length, wipLimit, overdueCards, estimatedMinutes, healthScore: Math.max(0, 100 - riskScore), wipExceeded };

              return `
                <div class="kanban-column-v2 omni-kanban-col ${getKanbanColumnClass(col)}" style="min-height: 150px; ${getKanbanColumnStyle(col)}" ondragover="event.preventDefault(); this.classList.add('kanban-column-drop-active')" ondragleave="this.classList.remove('kanban-column-drop-active')" ondrop="omniDropCard(event, '${col.id}'); this.classList.remove('kanban-column-drop-active')">
                  <div class="kanban-column-header-group" style="border-top-color:${normalizeKanbanHexColor(col.color, '#38bdf8')}; padding: 8px 10px 6px;">
                    <div class="kanban-column-header-v2">
                      <div><b style="font-size: 0.9rem; opacity: 0.8;">${escapeHtml(col.title || col.name || 'Column')}</b><span style="font-size: 0.75rem; margin-right: 8px; opacity: 0.7;">${stats.count}</span></div>
                      <div class="col-head-actions">
                        <button class="icon-btn" onclick="editKanbanColumnStyle('${col.id}')" title="تنسيق العمود"><i class="fa-solid fa-palette"></i></button>
                        <button class="icon-btn" onclick="addKanbanCard('${col.id}', '${escapeHtml(groupName).replace(/'/g, "\\'")}', '${kanbanGroupBy}')" title="إضافة بطاقة"><i class="fa-solid fa-plus"></i></button>
                      </div>
                    </div>
                    <div class="kanban-column-stats ${stats.wipExceeded ? 'wip-over' : ''}" style="font-size: 0.72rem;">
                      <span>متأخرة: ${stats.overdueCards}</span>
                      <span>${stats.estimatedMinutes} د</span>
                    </div>
                  </div>
                  <div class="kanban-column-body-v2 omni-card-list" style="min-height: 80px;">
                    ${stats.cards.map(renderKanbanCardV2).join('') || '<div class="kanban-column-empty" style="padding: 10px; font-size: 0.75rem; opacity: 0.4;">لا توجد بطاقات</div>'}
                  </div>
                </div>`;
            }).join('')}
          </div>
        </div>
      `;
    }).join('');
  }

  board.innerHTML = `
    <div class="${shellClasses}">
      ${renderKanbanToolbar()}
      ${renderKanbanExecutiveSummary()}
      ${renderKanbanWorkloadPanel()}
      ${totalFiltered ? '' : '<div class="kanban-empty-state">لا توجد نتائج حسب الفلاتر الحالية <button class="btn-ghost" onclick="resetKanbanFilters()">إعادة ضبط الفلاتر</button></div>'}
      ${boardContentHtml}
    </div>`;
}

function renderKanbanCardV2(card) {
  const dueRisk = calculateDueRisk(card);
  const readiness = calculateCardReadiness(card);
  const risk = calculateKanbanCardRisk(card);
  const indicators = getCardIndicators(card);
  const cardColor = getKanbanCardColor(card);
  const checklist = kanbanChecklistProgress(card);
  const qcStatus = kanbanCardQcStatus(card);
  const dueClass = dueRisk === 'overdue' ? 'card-due-overdue' : dueRisk === 'due_today' ? 'card-due-today' : dueRisk === 'due_tomorrow' ? 'card-due-tomorrow' : '';
  const age = card.createdAt ? Math.max(0, Math.floor((Date.now() - new Date(card.createdAt).getTime()) / 864e5)) : 0;
  return `
    <div class="kanban-card-v2 omni-kanban-card ${dueClass} kanban-risk-${risk.level} kanban-card-color-${cardColor}" style="${getKanbanCardStyleVars(card)}" draggable="true" ondragstart="omniDragCard(event, '${card.id}')" ondragend="this.classList.remove('kanban-card-dragging')" onclick="openKanbanCardInspector('${card.id}')">
      <span class="kanban-card-accent"></span>
      <div class="kanban-card-header-v2">
        <span class="card-priority ${priorityClass(card.priority)}">${escapeHtml(translatePriority(card.priority || 'Normal'))}</span>
        <span class="kanban-risk-badge kanban-risk-${risk.level}">${risk.label}</span>
      </div>
      ${card.clientName ? `<div class="card-client"><i class="fa-solid fa-building"></i> ${escapeHtml(card.clientName)}</div>` : ''}
      <h4 class="kanban-card-title-v2">${escapeHtml(card.title || 'بدون عنوان')}</h4>
      ${card.description ? `<p class="card-desc">${escapeHtml(String(card.description).slice(0, 96))}${String(card.description).length > 96 ? '...' : ''}</p>` : ''}
      <div class="kanban-card-meta-v2">
        <span><i class="fa-solid fa-user"></i> ${escapeHtml(getCardAssigneeName(card))}</span>
        <span><i class="fa-solid fa-sitemap"></i> ${escapeHtml(getKanbanDepartmentName(card))}</span>
        <span class="${dueClass}"><i class="fa-solid fa-calendar"></i> ${escapeHtml(card.dueDate || 'بدون موعد')}</span>
      </div>
      <div class="kanban-card-badges-v2">
        <span class="kanban-card-chip"><i class="fa-solid fa-list-check"></i> ${checklist}%</span>
        <span class="kanban-card-chip"><i class="fa-solid fa-book"></i> ${(card.sopIds || []).length ? 'SOP' : 'بدون SOP'}</span>
        <span class="kanban-card-chip"><i class="fa-solid fa-gear"></i> ${(card.machineIds || []).length || 'لا'}</span>
        <span class="kanban-card-chip"><i class="fa-solid fa-box"></i> ${calculateMaterialAvailability(card) === 'missing' ? 'ناقص' : (card.materialRequirements || []).length ? 'جاهز' : 'لا'}</span>
        <span class="kanban-card-chip"><i class="fa-solid fa-microscope"></i> ${qcStatus === 'none' ? 'لا QC' : qcStatus}</span>
      </div>
      ${risk.reasons.length ? `<div class="kanban-card-risk-row">${risk.reasons.slice(0, 3).map(r => `<span>${escapeHtml(r)}</span>`).join('')}</div>` : ''}
      <div class="kanban-card-progress-v2"><span style="width:${checklist}%"></span><i style="width:${readiness.percent}%"></i></div>
      <div class="kanban-card-footer-v2">
        <span><i class="fa-solid fa-comment"></i> ${(card.comments || []).length}</span>
        <span><i class="fa-solid fa-paperclip"></i> ${(card.attachments || []).length}</span>
        <span><i class="fa-solid fa-coins"></i> ${(card.costEntries || []).length}</span>
        <span>${age ? `${age} يوم` : 'جديد'}</span>
        <button class="icon-btn icon-btn-sm icon-btn-danger" onclick="event.stopPropagation(); deleteKanbanCard('${card.id}')" title="حذف"><i class="fa-solid fa-xmark"></i></button>
      </div>
    </div>`;
}

function renderKanbanListView() {
  const board = document.getElementById('omniKanbanBoard');
  const filteredCards = getFilteredKanbanCards(omni.kanban.cards || []);
  board.className = 'omni-kanban-board kanban-board-shell';
  board.innerHTML = `
    <div class="kanban-executive-board">
      ${renderKanbanToolbar()}
      ${renderKanbanExecutiveSummary()}
      <div class="table-container glass-card kanban-list-table">
        <table class="data-table">
          <thead><tr><th>العنوان</th><th>العمود</th><th>المسؤول</th><th>القسم</th><th>الأولوية</th><th>الخطر</th><th>التسليم</th><th>جاهزية</th></tr></thead>
          <tbody>
            ${filteredCards.map(card => {
              const col = (omni.kanban.columns || []).find(c => c.id === card.columnId);
              const risk = calculateKanbanCardRisk(card);
              return `<tr onclick="openKanbanCardInspector('${card.id}')" style="cursor:pointer">
                <td><b>${escapeHtml(card.title || '-')}</b><small>${escapeHtml(card.description || '')}</small></td>
                <td>${escapeHtml(col?.title || '-')}</td>
                <td>${escapeHtml(getCardAssigneeName(card))}</td>
                <td>${escapeHtml(getKanbanDepartmentName(card))}</td>
                <td><span class="${priorityClass(card.priority)}">${escapeHtml(translatePriority(card.priority || 'Normal'))}</span></td>
                <td><span class="kanban-risk-badge kanban-risk-${risk.level}">${risk.label}</span></td>
                <td>${escapeHtml(card.dueDate || '-')}</td>
                <td>${calculateCardReadiness(card).percent}%</td>
              </tr>`;
            }).join('') || '<tr><td colspan="8" class="text-center text-muted">لا توجد نتائج حسب الفلاتر الحالية</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>`;
}

function renderKanbanWorkloadView() {
  const board = document.getElementById('omniKanbanBoard');
  board.className = 'omni-kanban-board kanban-board-shell';
  board.innerHTML = `
    <div class="kanban-executive-board">
      ${renderKanbanToolbar()}
      ${renderKanbanExecutiveSummary()}
      ${renderKanbanWorkloadPanel()}
    </div>`;
}

function kanbanChecklistProgress(card) {
  const list = card.checklist || [];
  if (!list.length) return 0;
  return Math.round((list.filter(i => i.done).length / list.length) * 100);
}

function omniDragCard(ev, cardId) {
  omniDraggedCardId = cardId;
  ev.dataTransfer.setData('text/plain', cardId);
  ev.currentTarget?.classList?.add('kanban-card-dragging');
}

function omniDropCard(ev, columnId) {
  ev.preventDefault();
  ensureOmni();
  const cardId = omniDraggedCardId || ev.dataTransfer.getData('text/plain');
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const col = omni.kanban.columns.find(c => c.id === columnId);
  
  if (col && (col.title === 'مكتمل' || col.title === 'Done' || col.title.toLowerCase().includes('done'))) {
    if (card.blockedBy && card.blockedBy.length > 0) {
      const blockers = omni.kanban.cards.filter(c => card.blockedBy.includes(c.id));
      const unfinished = blockers.filter(b => {
        const bCol = omni.kanban.columns.find(c => c.id === b.columnId);
        return !(bCol && (bCol.title === 'مكتمل' || bCol.title === 'Done' || bCol.title.toLowerCase().includes('done')));
      });
      if (unfinished.length > 0) {
        showToast('لا يمكن نقل البطاقة! تعتمد على مهام غير مكتملة', 'error');
        return;
      }
    }
  }

  card.columnId = columnId;
  card.status = col ? (kanbanColumnLooksDone(col) ? 'done' : kanbanColumnLooksActive(col) ? 'in_progress' : card.status || '') : card.status;
  appendKanbanActivity(card, `تم نقل البطاقة إلى: ${col?.title || columnId}`);
  omniDraggedCardId = null;
  saveData();
  renderKanbanBoard();
  showToast('تم نقل البطاقة وتحديث اللوحة', 'success');
}

async function addKanbanCard(columnId = 'kb_backlog', prefilledGroup = null, prefilledGroupBy = null) {
  ensureOmni();
  let defaultOwner = '';
  let defaultClient = '';
  let defaultDept = '';
  if (prefilledGroup && prefilledGroupBy) {
    const fallbacks = ["بدون عميل / مشروع", "غير مسند", "بدون ماكينة", "غير مصنف", "none"];
    const isFallback = fallbacks.includes(prefilledGroup);
    if (!isFallback) {
      if (prefilledGroupBy === 'project') {
        defaultClient = prefilledGroup;
      } else if (prefilledGroupBy === 'assignee') {
        defaultOwner = prefilledGroup;
      } else if (prefilledGroupBy === 'department') {
        defaultDept = prefilledGroup;
      }
    }
  }
  const html = `
    <div style="display:flex; flex-direction:column; gap:10px;">
      <label>عنوان البطاقة</label>
      <input type="text" id="kbcTitle" class="form-input" placeholder="مثال: صيانة الماكينة">
      <label>المسؤول</label>
      <input type="text" id="kbcOwner" class="form-input" value="${escapeHtml(defaultOwner)}" placeholder="اسم الموظف">
      ${defaultClient ? `
        <label>العميل / المشروع</label>
        <input type="text" id="kbcClient" class="form-input" value="${escapeHtml(defaultClient)}">
      ` : ''}
      ${defaultDept ? `
        <label>القسم</label>
        <input type="text" id="kbcDept" class="form-input" value="${escapeHtml(defaultDept)}">
      ` : ''}
      <label>الأولوية</label>
      <select id="kbcPriority" class="form-input">
        <option value="Urgent">Urgent</option>
        <option value="High">High</option>
        <option value="Normal" selected>Normal</option>
        <option value="Low">Low</option>
      </select>
      <label>Tags (مفصولة بفارزة)</label>
      <input type="text" id="kbcTags" class="form-input" placeholder="صيانة, مستعجل, تصميم">
      <label>لون البطاقة</label>
      <select id="kbcColor" class="form-input">${getKanbanColorOptions('default')}</select>
      <label>لون مخصص</label>
      <input type="color" id="kbcCustomColor" class="form-input kanban-color-input" value="#38bdf8">
    </div>
  `;
  const result = await showOmniModal('إضافة بطاقة جديدة', html, (body) => {
    const title = body.querySelector('#kbcTitle').value.trim();
    if (!title) return false;
    return {
      title,
      owner: body.querySelector('#kbcOwner').value.trim(),
      clientName: body.querySelector('#kbcClient')?.value.trim() || defaultClient,
      department: body.querySelector('#kbcDept')?.value.trim() || defaultDept,
      priority: body.querySelector('#kbcPriority').value,
      tags: body.querySelector('#kbcTags').value.split(',').map(t=>t.trim()).filter(Boolean),
      color: body.querySelector('#kbcColor')?.value || 'default',
      customColor: normalizeKanbanHexColor(body.querySelector('#kbcCustomColor')?.value, '#38bdf8')
    };
  });
  if (!result) return;
  let mIds = [];
  if (prefilledGroup && prefilledGroupBy === 'machine') {
    const m = (omni.machines || []).find(x => (x.name || x.id) === prefilledGroup);
    if (m) mIds = [m.id];
  }
  const cardColor = KANBAN_CARD_COLORS.includes(result.color) ? result.color : 'default';
  const newCard = { id: makeId('card'), columnId, title: result.title, owner: result.owner, clientName: result.clientName || '', assigneeId: '', department: result.department || '', color: cardColor, accentColor: cardColor, customColor: result.customColor, priority: result.priority, dueDate: todayISO(), tags: result.tags, description: '', checklist: [], comments: [], activityLog: [], blockedBy: [], machineIds: mIds };
  omni.kanban.cards.push(newCard);
  saveData();
  renderKanbanBoard();
  triggerOmniEvent('QUOTE_CREATED', { card: newCard });
}

async function addKanbanColumn() {
  ensureOmni();
  const title = await showOmniPrompt('اسم العمود الجديد:');
  if (!title) return;
  omni.kanban.columns.push({ id: makeId('kb_col'), title: title.trim(), color: '#38bdf8', headerStyle: 'glass', bodyTone: 0.08, wip: 8 });
  saveData();
  renderKanbanBoard();
}

async function editKanbanColumnStyle(colId) {
  ensureOmni();
  const col = (omni.kanban.columns || []).find(c => c.id === colId);
  if (!col) return;
  const color = normalizeKanbanHexColor(col.color, '#38bdf8');
  const style = KANBAN_COLUMN_STYLES.some(item => item.value === col.headerStyle) ? col.headerStyle : 'glass';
  const bodyTone = Math.round(Math.min(0.28, Math.max(0, Number(col.bodyTone ?? 0.08))) * 100);
  const styleOptions = KANBAN_COLUMN_STYLES.map(item => `<option value="${item.value}" ${style === item.value ? 'selected' : ''}>${item.label}</option>`).join('');
  const html = `
    <div class="kanban-style-modal">
      <label>اسم العمود
        <input id="kanbanColumnTitle" class="form-input" value="${escapeHtml(col.title || col.name || '')}">
      </label>
      <label>لون العمود
        <input id="kanbanColumnColor" class="form-input kanban-color-input" type="color" value="${color}">
      </label>
      <label>نمط الهيدر
        <select id="kanbanColumnStyle" class="form-input">${styleOptions}</select>
      </label>
      <label>قوة لون خلفية العمود
        <input id="kanbanColumnTone" class="form-input" type="range" min="0" max="28" value="${bodyTone}">
      </label>
      <div class="kanban-style-preview" style="--column-color:${color};--column-tone:${(bodyTone / 100).toFixed(2)};--column-tone-percent:${bodyTone}%;">
        <b>${escapeHtml(col.title || 'عمود')}</b>
        <span>معاينة اللون والتنسيق</span>
      </div>
    </div>
  `;
  const result = await showOmniModal('تنسيق العمود', html, body => ({
    title: body.querySelector('#kanbanColumnTitle')?.value.trim() || col.title || col.name || 'Column',
    color: normalizeKanbanHexColor(body.querySelector('#kanbanColumnColor')?.value, color),
    headerStyle: body.querySelector('#kanbanColumnStyle')?.value || 'glass',
    bodyTone: (Number(body.querySelector('#kanbanColumnTone')?.value || 0) || 0) / 100
  }));
  if (!result) return;
  col.title = result.title;
  col.name = result.title;
  col.color = result.color;
  col.headerStyle = KANBAN_COLUMN_STYLES.some(item => item.value === result.headerStyle) ? result.headerStyle : 'glass';
  col.bodyTone = Math.min(0.28, Math.max(0, result.bodyTone));
  saveData();
  renderKanbanBoard();
  showToast('تم تحديث تنسيق العمود', 'success');
}

async function editKanbanCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const html = `
    <div style="display:flex; flex-direction:column; gap:10px;">
      <label>عنوان البطاقة</label>
      <input type="text" id="ekbcTitle" class="form-input" value="${card.title}">
      <label>المسؤول</label>
      <input type="text" id="ekbcOwner" class="form-input" value="${card.owner || ''}">
      <label>الأولوية</label>
      <select id="ekbcPriority" class="form-input">
        <option value="Urgent" ${card.priority === 'Urgent' ? 'selected' : ''}>Urgent</option>
        <option value="High" ${card.priority === 'High' ? 'selected' : ''}>High</option>
        <option value="Normal" ${card.priority === 'Normal' ? 'selected' : ''}>Normal</option>
        <option value="Low" ${card.priority === 'Low' ? 'selected' : ''}>Low</option>
      </select>
      <label>Tags (مفصولة بفارزة)</label>
      <input type="text" id="ekbcTags" class="form-input" value="${(card.tags || []).join(', ')}">
      <label>لون البطاقة</label>
      <select id="ekbcColor" class="form-input">${getKanbanColorOptions(getKanbanCardColor(card))}</select>
      <label>لون مخصص</label>
      <input type="color" id="ekbcCustomColor" class="form-input kanban-color-input" value="${getKanbanCardAccentHex(card)}">
    </div>
  `;
  const result = await showOmniModal('تعديل بطاقة', html, (body) => {
    const title = body.querySelector('#ekbcTitle').value.trim();
    if (!title) return false;
    return {
      title,
      owner: body.querySelector('#ekbcOwner').value.trim(),
      priority: body.querySelector('#ekbcPriority').value,
      tags: body.querySelector('#ekbcTags').value.split(',').map(t=>t.trim()).filter(Boolean),
      color: body.querySelector('#ekbcColor')?.value || 'default',
      customColor: normalizeKanbanHexColor(body.querySelector('#ekbcCustomColor')?.value, getKanbanCardAccentHex(card))
    };
  });
  if (!result) return;
  card.title = result.title;
  card.owner = result.owner;
  card.priority = result.priority;
  card.tags = result.tags;
  card.color = KANBAN_CARD_COLORS.includes(result.color) ? result.color : 'default';
  card.accentColor = card.color;
  card.customColor = result.customColor;
  saveData();
  renderKanbanBoard();
}

async function deleteKanbanCard(cardId) {
  ensureOmni();
  const ok = await showOmniConfirm('حذف بطاقة', 'هل أنت متأكد من حذف هذه البطاقة؟', 'حذف', 'إلغاء');
  if (!ok) return;
  omni.kanban.cards = omni.kanban.cards.filter(c => c.id !== cardId);
  saveData(); renderKanbanBoard();
  showToast('تم حذف البطاقة', 'success');
}

async function deleteKanbanColumn(colId) {
  ensureOmni();
  const col = omni.kanban.columns.find(c => c.id === colId);
  if (!col) return;
  const cardsInCol = omni.kanban.cards.filter(c => c.columnId === colId);
  if (cardsInCol.length > 0) {
    const ok = await showOmniConfirm('حذف عمود', `العمود "${col.title}" يحتوي على ${cardsInCol.length} بطاقة. هل تريد حذف العمود وجميع بطاقاته؟`, 'حذف', 'إلغاء');
    if (!ok) return;
    omni.kanban.cards = omni.kanban.cards.filter(c => c.columnId !== colId);
  } else {
    const ok = await showOmniConfirm('حذف عمود', `هل تريد حذف العمود "${col.title}"؟`, 'حذف', 'إلغاء');
    if (!ok) return;
  }
  omni.kanban.columns = omni.kanban.columns.filter(c => c.id !== colId);
  saveData(); renderKanbanBoard();
  showToast('تم حذف العمود', 'success');
}

function openKanbanCardInspector(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const panel = document.getElementById('inspectorPanel');
  const overlay = document.getElementById('inspectorOverlay');
  const title = document.getElementById('inspectorTitle');
  const tabs = document.getElementById('inspectorTabs');
  const body = document.getElementById('inspectorBody');
  if (!panel || !overlay) return;
  panel.classList.add('kanban-inspector-panel');
  panel.classList.add('kanban-inspector-v2');
  tabs.className = 'inspector-tabs kanban-inspector-tabs-side';
  body.className = 'inspector-body kanban-inspector-content';

  title.textContent = card.title;
  const tabList = ['نظرة عامة', 'Checklist', 'SOP', 'ماكينة', 'مواد', 'كلفة', 'نشاط', 'QC', 'روابط'];
  const tabHelp = [
    'معلومات البطاقة الأساسية: العنوان، المسؤول، الأولوية، القسم، الموعد، والحالة.',
    'قائمة خطوات صغيرة داخل البطاقة لمتابعة إنجاز العمل خطوة بخطوة.',
    'ربط البطاقة بإجراء تشغيلي قياسي حتى يعرف الفريق طريقة التنفيذ الصحيحة.',
    'ربط البطاقة بماكينة محددة مثل ليزر، راوتر، طابعة، أو غيرها.',
    'المواد المطلوبة لتنفيذ هذه البطاقة مع الكمية وحالة التوفر.',
    'تسجيل الكلف المرتبطة بهذه البطاقة مثل مواد، تشغيل، أجور، أو خدمات.',
    'سجل تلقائي يوضح ما حدث على البطاقة: ربط، تعديل، كلفة، تعليق، أو تغيير حالة.',
    'فحوصات الجودة المرتبطة بالبطاقة ونتائج القبول أو الرفض وإعادة العمل.',
    'الروابط والعلاقات الخاصة بالبطاقة مع كيانات أخرى في النظام.'
  ];
  let activeTab = 0;

  function renderInspectorTab(tabIdx) {
    activeTab = tabIdx;
    tabs.innerHTML = tabList.map((t, i) => `<button class="insp-tab kanban-inspector-tab-btn ${i === tabIdx ? 'active' : ''}" onclick="renderKanbanInspectorTab('${cardId}', ${i})"><span>${t}</span>${renderHelpMarker(tabHelp[i])}</button>`).join('');

    if (tabIdx === 0) {
      const dueRisk = calculateDueRisk(card);
      const readiness = calculateCardReadiness(card);
      const risk = calculateKanbanCardRisk(card);
      const indicators = getCardIndicators(card);
      const departments = Array.isArray(omni.departments) ? omni.departments : [];
      const employeeOptions = (employees || []).map(emp => `<option value="${escapeHtml(emp.id || emp.name)}" ${String(card.assigneeId || card.owner || '') === String(emp.id || emp.name) ? 'selected' : ''}>${escapeHtml(emp.name)}</option>`).join('');
      const departmentOptions = departments.map(dep => `<option value="${escapeHtml(dep.name || dep)}" ${card.department === (dep.name || dep) ? 'selected' : ''}>${escapeHtml(dep.name || dep)}</option>`).join('');
      const colorOptions = getKanbanColorOptions(getKanbanCardColor(card));
      body.innerHTML = `
        <div class="kanban-inspector-header-v2">
          <div>
            <span class="cc-source-label">اللوحة التنفيذية</span>
            <h3>${escapeHtml(card.title || '-')}</h3>
            <p>${escapeHtml(card.description || 'لا يوجد وصف مختصر بعد')}</p>
          </div>
          <div class="kanban-quick-actions">
            <button class="btn-primary" onclick="startKanbanCard('${card.id}')"><i class="fa-solid fa-play"></i> بدء</button>
            <button class="btn-primary" onclick="completeKanbanCard('${card.id}')"><i class="fa-solid fa-check"></i> إنهاء</button>
            <button class="btn-ghost" onclick="blockKanbanCard('${card.id}')"><i class="fa-solid fa-ban"></i> تعليق</button>
            <button class="btn-ghost" onclick="unblockKanbanCard('${card.id}')"><i class="fa-solid fa-unlock"></i> إلغاء التعليق</button>
            <button class="btn-ghost" onclick="assignKanbanCardQuick('${card.id}')"><i class="fa-solid fa-user-plus"></i> إسناد</button>
            <button class="btn-ghost" onclick="requestMaterialForKanbanCard('${card.id}')"><i class="fa-solid fa-box"></i> طلب مادة</button>
          </div>
        </div>
        <div class="kanban-inspector-summary">
          <span><b>الأولوية</b>${escapeHtml(card.priority || 'Normal')}</span>
          <span><b>المسؤول</b>${escapeHtml(getCardAssigneeName(card))}</span>
          <span><b>القسم</b>${escapeHtml(getKanbanDepartmentName(card))}</span>
          <span><b>التسليم</b>${escapeHtml(card.dueDate || '-')}</span>
          <span><b>الخطر</b><em class="kanban-risk-badge kanban-risk-${risk.level}">${risk.label}</em></span>
          <span><b>الجاهزية</b>${readiness.percent}%</span>
        </div>
        ${risk.reasons.length ? `<div class="kanban-inspector-section-card"><h4>ملخص الخطر</h4><div class="kanban-card-risk-row">${risk.reasons.map(r => `<span>${escapeHtml(r)}</span>`).join('')}</div></div>` : ''}
        <div class="kanban-inspector-field-grid">
        <div class="insp-section"><h4>العنوان</h4><p>${card.title}</p></div>
        ${card.clientName ? `<div class="insp-section"><h4>العميل</h4><p>${card.clientName}</p></div>` : ''}
        <div class="insp-section"><h4>المسؤول</h4><p>${card.owner || '-'}</p></div>
        <div class="insp-section"><h4>الأولوية</h4><p class="${priorityClass(card.priority)}">${card.priority || 'Normal'}</p></div>
        <div class="insp-section"><h4>التسليم</h4><p class="${dueRisk === 'overdue' ? 'text-danger' : ''}">${card.dueDate || '-'} ${dueRisk === 'overdue' ? '(متأخر!)' : dueRisk === 'due_today' ? '(اليوم)' : ''}</p></div>
        <div class="insp-section"><h4>الوصف</h4><p>${card.description || '-'}</p></div>
        <div class="insp-section"><h4>Tags</h4><div class="card-tags">${(card.tags||[]).map(t => `<span>${t}</span>`).join('') || '-'}</div></div>
        <div class="insp-section"><h4>الجاهزية</h4><p>${readiness.percent}% (${readiness.score}/${readiness.total})</p></div>
        <div class="insp-section"><h4>المؤشرات</h4><div class="card-indicators">${indicators.map(ind => `<span class="card-indicator" style="color:${ind.color}"><i class="fa-solid ${ind.icon}"></i> ${ind.label}</span>`).join('') || '-'}</div></div>
        ${card.operationPackId ? `<div class="insp-section"><h4>باقة العمليات</h4><p>${(getOperationPackById(card.operationPackId)||{}).name || card.operationPackId}</p></div>` : ''}
        ${card.workflowId ? `<div class="insp-section"><h4>Workflow</h4><p>${card.workflowId}</p></div>` : ''}
        </div>
        <div class="insp-section kanban-overview-controls">
          <h4>إدارة البطاقة ${renderHelpMarker('اختر المسؤول، القسم، ولون البطاقة بدون تغيير مسارها في اللوحة.')}</h4>
          <label>المسؤول
            ${employeeOptions ? `<select class="kanban-inline-control" onchange="setKanbanAssignee('${card.id}', this.value)"><option value="">بدون مسؤول</option>${employeeOptions}</select>` : `<input class="kanban-inline-control" value="${escapeHtml(card.owner || '')}" onchange="setKanbanOwner('${card.id}', this.value)" placeholder="اسم المسؤول">`}
          </label>
          <label>القسم / الفرع
            <select class="kanban-inline-control" onchange="setKanbanDepartment('${card.id}', this.value)"><option value="">بدون قسم</option>${departmentOptions}</select>
          </label>
          <label>لون البطاقة
            <select class="kanban-inline-control" onchange="setKanbanCardColor('${card.id}', this.value)">${colorOptions}</select>
          </label>
          <label>لون مخصص
            <input type="color" class="kanban-inline-control kanban-color-input" value="${getKanbanCardAccentHex(card)}" onchange="setKanbanCardCustomColor('${card.id}', this.value)">
          </label>
        </div>
        <div class="insp-actions">
          <button class="btn-primary" onclick="editKanbanCard('${card.id}'); closeInspector(); renderKanbanBoard();"><i class="fa-solid fa-pen"></i> تعديل</button>
          <button class="btn-primary" onclick="editKanbanCardLinks('${card.id}')"><i class="fa-solid fa-link"></i> ربط</button>
          <button class="btn-danger" onclick="deleteKanbanCard('${card.id}'); closeInspector();"><i class="fa-solid fa-trash"></i> حذف</button>
        </div>
      `;
    } else if (tabIdx === 1) {
      const cl = card.checklist || [];
      body.innerHTML = `
        <div class="insp-section"><h4>Checklist (${cl.filter(i=>i.done).length}/${cl.length})</h4>
          <div class="insp-checklist">${cl.map((item, i) => `<label class="insp-check-item"><input type="checkbox" ${item.done ? 'checked' : ''} onchange="toggleKanbanChecklist('${card.id}', ${i})"> ${item.text}</label>`).join('') || '<p>لا يوجد checklist</p>'}</div>
          <div style="margin-top:10px"><button class="btn-primary" onclick="addKanbanChecklistItem('${card.id}')"><i class="fa-solid fa-plus"></i> إضافة بند</button></div>
        </div>
      `;
    } else if (tabIdx === 2) {
      const sops = (card.sopIds || []).map(id => getSopById(id)).filter(Boolean);
      const sopOptions = (omni.sops || []).map(s => `<option value="${s.id}">${escapeHtml(s.code || '')} ${escapeHtml(s.title)} (${escapeHtml(s.approvalStatus || s.status || '-')})</option>`).join('');
      body.innerHTML = `
        <div class="insp-section"><h4>SOPs المرتبطة (${sops.length})</h4>
          ${sops.map(s => `<div class="insp-linked-item" onclick="openSopInspector('${s.id}')" style="cursor:pointer">
            <b>${s.code || ''} — ${s.title}</b>
            <small>${s.type} · ${s.owner} · v${s.version||1} · ${(s.steps||[]).length} خطوة</small>
            ${s.approvalStatus === 'approved' ? '<span style="color:#10b981;font-size:11px">✓ معتمد</span>' : '<span style="color:#f59e0b;font-size:11px">● ' + ({'draft':'مسودة','review':'مراجعة'}[s.approvalStatus]||s.approvalStatus) + '</span>'}
          </div>`).join('') || '<p>لا يوجد SOP مرتبط</p>'}
          ${sopOptions ? `<div class="kanban-inline-linker"><select class="kanban-inline-control" id="kanbanSopSelect_${card.id}"><option value="">اختر SOP</option>${sopOptions}</select><button class="btn-primary" onclick="linkSopToCardDirect('${card.id}', document.getElementById('kanbanSopSelect_${card.id}').value)"><i class="fa-solid fa-link"></i> ربط SOP</button></div>` : '<div class="cc-empty">لا توجد SOPs محفوظة بعد. افتح مكتبة SOP لإضافة إجراء جديد.</div>'}
          <div style="margin-top:10px"><button class="btn-ghost" onclick="linkSopToCard('${card.id}')"><i class="fa-solid fa-keyboard"></i> إدخال يدوي احتياطي</button></div>
        </div>
      `;
    } else if (tabIdx === 3) {
      const machines = (card.machineIds || []).map(id => getMachineById(id)).filter(Boolean);
      const machineOptions = (omni.machines || []).map(m => `<option value="${m.id}">${escapeHtml(m.name)} (${escapeHtml(m.status || '-')})</option>`).join('');
      body.innerHTML = `
        <div class="insp-section"><h4>المكائن المطلوبة (${machines.length})</h4>
        ${machines.map(m => `<div class="insp-linked-item"><b>${m.name}</b><small>${translateMachineStatus(m.status)} · طابور: ${getMachineQueueCount(m)} · ${m.operator}</small></div>`).join('') || '<p>لا ماكينة مرتبطة</p>'}
          ${machineOptions ? `<div class="kanban-inline-linker"><select class="kanban-inline-control" id="kanbanMachineSelect_${card.id}"><option value="">اختر ماكينة</option>${machineOptions}</select><button class="btn-primary" onclick="linkMachineToCardDirect('${card.id}', document.getElementById('kanbanMachineSelect_${card.id}').value)"><i class="fa-solid fa-link"></i> ربط ماكينة</button></div>` : '<div class="cc-empty">لا توجد مكائن محفوظة بعد. افتح صفحة المكائن لإضافتها.</div>'}
          <div style="margin-top:10px"><button class="btn-ghost" onclick="linkMachineToCard('${card.id}')"><i class="fa-solid fa-keyboard"></i> إدخال يدوي احتياطي</button></div>
        </div>
      `;
    } else if (tabIdx === 4) {
      const mats = (card.materialRequirements || []).map(req => ({ ...req, mat: getMaterialById(req.materialId) }));
      const materialOptions = (omni.materials || []).map(m => `<option value="${m.id}">${escapeHtml(m.name)} (${getMaterialAvailableQty(m)} ${escapeHtml(m.unit || '')})</option>`).join('');
      body.innerHTML = `
        <div class="insp-section"><h4>المواد المطلوبة (${mats.length})</h4>
          ${mats.map(r => {
            const m = r.mat;
            const avail = m ? getMaterialAvailableQty(m) : 0;
            return `<div class="insp-linked-item"><b>${m ? m.name : r.materialId}</b><small>مطلوب: ${r.quantity || 1} · متاح: ${avail} ${m ? m.unit : ''}</small>${avail < (r.quantity||1) ? '<span class="inv-badge inv-badge-danger">ناقص</span>' : '<span class="inv-badge inv-badge-ok">كافي</span>'}</div>`;
          }).join('') || '<p>لا مواد مطلوبة</p>'}
          ${materialOptions ? `<div class="kanban-inline-linker kanban-material-linker"><select class="kanban-inline-control" id="kanbanMaterialSelect_${card.id}"><option value="">اختر مادة</option>${materialOptions}</select><input class="kanban-inline-control" id="kanbanMaterialQty_${card.id}" type="number" min="0" step="0.01" value="1" placeholder="الكمية"><input class="kanban-inline-control" id="kanbanMaterialUnit_${card.id}" placeholder="الوحدة"><button class="btn-primary" onclick="linkMaterialToCardInline('${card.id}')"><i class="fa-solid fa-plus"></i> إضافة</button></div>` : '<div class="cc-empty">لا توجد مواد محفوظة بعد. افتح المخزون لإضافة مادة.</div>'}
          <div style="margin-top:10px"><button class="btn-ghost" onclick="linkMaterialToCard('${card.id}')"><i class="fa-solid fa-keyboard"></i> إدخال يدوي احتياطي</button></div>
        </div>
      `;
    } else if (tabIdx === 5) {
      body.innerHTML = `
        <div class="insp-section"><h4>سجل الكلف (${(card.costEntries||[]).length})</h4>
          ${(card.costEntries||[]).map(c => `<div class="insp-linked-item"><b>${c.description || 'كلفة'}</b><small>${(c.amount||0).toLocaleString()} IQD · ${c.date || '-'}</small></div>`).join('') || '<p>لا كلف مسجلة</p>'}
          <div style="margin-top:10px"><button class="btn-primary" onclick="addCostToCard('${card.id}')"><i class="fa-solid fa-plus"></i> إضافة كلفة</button></div>
        </div>
      `;
    } else if (tabIdx === 6) {
      body.innerHTML = `
        <div class="insp-section"><h4>سجل النشاط (${(card.activityLog||[]).length})</h4>
          ${(card.activityLog||[]).map(a => `<div class="insp-activity-item"><small>${a.date}</small><p>${a.text}</p></div>`).join('') || '<p>لا نشاط مسجل</p>'}
        </div>
        <div class="insp-section"><h4>التعليقات (${(card.comments||[]).length})</h4>
          ${(card.comments||[]).map(c => `<div class="insp-activity-item"><small>${c.date} · ${c.author || '-'}</small><p>${c.text}</p></div>`).join('') || '<p>لا تعليقات</p>'}
          <div class="kanban-inline-linker kanban-comment-box"><textarea class="kanban-inline-control" id="kanbanCommentText_${card.id}" placeholder="اكتب تعليقاً جديداً"></textarea><button class="btn-primary" onclick="addCommentToCardInline('${card.id}')"><i class="fa-solid fa-plus"></i> إضافة تعليق</button></div>
          <div style="margin-top:10px"><button class="btn-ghost" onclick="addCommentToCard('${card.id}')"><i class="fa-solid fa-keyboard"></i> إدخال يدوي احتياطي</button></div>
        </div>
      `;
    } else if (tabIdx === 7) {
      const qcs = (card.qcRecordIds || []).map(id => getQcRecordById(id)).filter(Boolean);
      body.innerHTML = `
        <div class="insp-section"><h4>فحوصات الجودة (${qcs.length})</h4>
          ${qcs.map(q => `<div class="insp-linked-item"><b>${q.type}</b><small>${q.result === 'pass' ? 'ناجح' : 'فاشل'} · ${q.date}</small>${q.result === 'fail' ? `<small class="text-danger">السبب: ${q.reason}</small>` : ''}</div>`).join('') || '<p>لا فحوصات مرتبطة</p>'}
          <div class="kanban-inline-linker kanban-qc-form">
            <input class="kanban-inline-control" id="kanbanQcType_${card.id}" placeholder="نوع الفحص / العنوان">
            <select class="kanban-inline-control" id="kanbanQcResult_${card.id}"><option value="pending">قيد الفحص</option><option value="pass">ناجح</option><option value="fail">فاشل</option></select>
            <input class="kanban-inline-control" id="kanbanQcReason_${card.id}" placeholder="ملاحظات أو سبب الفشل">
            <button class="btn-primary" onclick="createQcForCardInline('${card.id}')"><i class="fa-solid fa-plus"></i> إضافة فحص جودة</button>
          </div>
          <div style="margin-top:10px"><button class="btn-ghost" onclick="linkQcToCard('${card.id}')"><i class="fa-solid fa-keyboard"></i> إدخال يدوي احتياطي</button></div>
        </div>
      `;
    } else if (tabIdx === 8) {
      body.innerHTML = `
        <div class="insp-section">
          <h4>روابط وعلاقات</h4>
          ${renderEntityRelationsPanel('kanban_card', cardId)}
        </div>
      `;
    }
  }

  renderInspectorTab(0);
  window.renderKanbanInspectorTab = function(cid, idx) { renderInspectorTab(idx); };
  panel.classList.remove('hidden');
  overlay.classList.remove('hidden');
}

function renderKanbanInspectorV2(cardId, activeTab = 0) {
  openKanbanCardInspector(cardId);
  if (activeTab && typeof window.renderKanbanInspectorTab === 'function') {
    window.renderKanbanInspectorTab(cardId, activeTab);
  }
}

function moveKanbanCardToBestColumn(cardId, targetType) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return false;
  const columns = omni.kanban.columns || [];
  const matcher = targetType === 'done' ? kanbanColumnLooksDone : targetType === 'in_progress' ? kanbanColumnLooksActive : () => false;
  const target = columns.find(matcher);
  if (target) card.columnId = target.id;
  card.status = targetType === 'done' ? 'done' : targetType === 'in_progress' ? 'in_progress' : card.status || targetType;
  appendKanbanActivity(card, target ? `إجراء سريع: نقل إلى ${target.title}` : `إجراء سريع: تحديث الحالة إلى ${card.status}`);
  saveData();
  renderKanbanBoard();
  return true;
}

function startKanbanCard(cardId) {
  if (moveKanbanCardToBestColumn(cardId, 'in_progress')) showToast('تم بدء البطاقة', 'success');
}

async function completeKanbanCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const qcStatus = getCardQcStatus(card);
  if (!canCardMoveToDone(card)) {
    const reason = getQcRequirementReason('kanban_card', card);
    const result = await showOmniModal('QC مطلوب قبل الإنهاء', `
      <div class="qc-inspector">
        <p>لا يمكن إنهاء البطاقة قبل إكمال بوابة الجودة.</p>
        <div class="qc-record-card">
          <b>${escapeHtml(card.title || 'بطاقة')}</b>
          <small>${escapeHtml(reason)} · الحالة الحالية: ${escapeHtml(qcStatus.label)}</small>
        </div>
        <p class="muted">اضغط تأكيد لإنشاء فحص جودة مرتبط بهذه البطاقة. سيتم إبقاء البطاقة في مكانها.</p>
      </div>
    `, () => true);
    if (result) createQcRecordForCard(cardId, card.qcTemplateId || '');
    showToast('لا يمكن إكمال البطاقة قبل اجتياز QC', 'warning');
    return;
  }
  if (moveKanbanCardToBestColumn(cardId, 'done')) showToast('تم إنهاء البطاقة', 'success');
}

async function blockKanbanCard(cardId, reason) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  let finalReason = reason;
  if (!finalReason) {
    finalReason = await showOmniPrompt('سبب تعليق البطاقة:', '');
  }
  card.isBlocked = true;
  card.status = 'blocked';
  if (!Array.isArray(card.tags)) card.tags = [];
  if (!card.tags.some(t => String(t).toLowerCase().includes('blocked'))) card.tags.push('blocked');
  appendKanbanActivity(card, `تم تعليق البطاقة${finalReason ? ': ' + finalReason : ''}`);
  saveData();
  renderKanbanBoard();
  openKanbanCardInspector(cardId);
}

function unblockKanbanCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  card.isBlocked = false;
  if (card.status === 'blocked') card.status = '';
  card.tags = (card.tags || []).filter(t => !String(t).toLowerCase().includes('blocked') && !String(t).includes('متوقف'));
  appendKanbanActivity(card, 'تم إلغاء تعليق البطاقة');
  saveData();
  renderKanbanBoard();
  openKanbanCardInspector(cardId);
}

async function assignKanbanCardQuick(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const options = (employees || []).map(emp => `<option value="${escapeHtml(emp.id || emp.name)}">${escapeHtml(emp.name)}</option>`).join('');
  const html = `<label>المسؤول</label><select id="quickAssignee" class="form-input"><option value="">بدون مسؤول</option>${options}</select>`;
  const assigneeId = await showOmniModal('إسناد البطاقة', html, body => body.querySelector('#quickAssignee')?.value || '');
  if (assigneeId === false || assigneeId === null) return;
  setKanbanAssignee(cardId, assigneeId);
}

async function requestMaterialForKanbanCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const note = await showOmniPrompt('ملاحظة طلب المادة:', 'طلب مادة لهذه البطاقة');
  if (!note) return;
  if (!Array.isArray(card.comments)) card.comments = [];
  card.comments.push({ id: makeId('cmt'), text: note, author: 'Saif', createdAt: new Date().toISOString(), date: todayISO() });
  appendKanbanActivity(card, `طلب مادة: ${note}`);
  saveData();
  openKanbanCardInspector(cardId);
}

// ─── Kanban Linking Actions ───
function refreshKanbanInspector(cardId) {
  saveData();
  renderKanbanBoard();
  openKanbanCardInspector(cardId);
}

function appendKanbanActivity(card, text) {
  if (!Array.isArray(card.activityLog)) card.activityLog = [];
  card.activityLog.push({ date: todayISO(), text });
}

function setKanbanCardColor(cardId, color) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  card.color = KANBAN_CARD_COLORS.includes(color) ? color : 'default';
  card.accentColor = card.color;
  appendKanbanActivity(card, `تم تغيير لون البطاقة إلى ${card.color}`);
  refreshKanbanInspector(cardId);
}

function setKanbanCardCustomColor(cardId, color) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  card.customColor = normalizeKanbanHexColor(color, getKanbanCardAccentHex(card));
  card.color = 'custom';
  card.accentColor = 'custom';
  appendKanbanActivity(card, `تم تغيير اللون المخصص للبطاقة إلى ${card.customColor}`);
  refreshKanbanInspector(cardId);
}

function setKanbanDepartment(cardId, department) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  card.department = department || '';
  appendKanbanActivity(card, `تم تحديث القسم: ${card.department || 'بدون قسم'}`);
  refreshKanbanInspector(cardId);
}

function setKanbanOwner(cardId, owner) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  card.owner = owner || '';
  card.assigneeId = '';
  appendKanbanActivity(card, `تم تحديث المسؤول: ${card.owner || 'بدون مسؤول'}`);
  refreshKanbanInspector(cardId);
}

function setKanbanAssignee(cardId, assigneeId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const emp = (employees || []).find(e => String(e.id || e.name) === String(assigneeId));
  card.assigneeId = assigneeId || '';
  card.owner = emp?.name || '';
  appendKanbanActivity(card, `تم تعيين المسؤول: ${card.owner || 'بدون مسؤول'}`);
  refreshKanbanInspector(cardId);
}

function linkSopToCardDirect(cardId, sopId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  const sop = (omni.sops || []).find(s => s.id === sopId);
  if (!card || !sop) return showToast('اختر SOP صالحاً', 'warning');
  if (!Array.isArray(card.sopIds)) card.sopIds = [];
  if (card.sopIds.includes(sop.id)) return showToast('هذا SOP مرتبط مسبقاً', 'warning');
  card.sopIds.push(sop.id);
  appendKanbanActivity(card, `تم ربط SOP: ${sop.title}`);
  refreshKanbanInspector(cardId);
}

function linkMachineToCardDirect(cardId, machineId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  const machine = (omni.machines || []).find(m => m.id === machineId);
  if (!card || !machine) return showToast('اختر ماكينة صالحة', 'warning');
  if (!Array.isArray(card.machineIds)) card.machineIds = [];
  if (card.machineIds.includes(machine.id)) return showToast('هذه الماكينة مرتبطة مسبقاً', 'warning');
  card.machineIds.push(machine.id);
  appendKanbanActivity(card, `تم ربط ماكينة: ${machine.name}`);
  refreshKanbanInspector(cardId);
}

function linkMaterialToCardInline(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  const materialId = document.getElementById(`kanbanMaterialSelect_${cardId}`)?.value;
  const mat = (omni.materials || []).find(m => m.id === materialId);
  if (!card || !mat) return showToast('اختر مادة صالحة', 'warning');
  const quantity = parseFloat(document.getElementById(`kanbanMaterialQty_${cardId}`)?.value) || 1;
  const unit = document.getElementById(`kanbanMaterialUnit_${cardId}`)?.value || mat.unit || '';
  if (!Array.isArray(card.materialRequirements)) card.materialRequirements = [];
  const existing = card.materialRequirements.find(req => req.materialId === materialId);
  if (existing) {
    existing.quantity = quantity;
    existing.qty = quantity;
    existing.unit = unit;
    appendKanbanActivity(card, `تم تحديث مادة: ${mat.name} × ${quantity} ${unit}`);
  } else {
    card.materialRequirements.push({ materialId, quantity, qty: quantity, unit });
    appendKanbanActivity(card, `تم ربط مادة: ${mat.name} × ${quantity} ${unit}`);
  }
  refreshKanbanInspector(cardId);
}

function createQcForCardInline(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const type = document.getElementById(`kanbanQcType_${cardId}`)?.value?.trim();
  const result = document.getElementById(`kanbanQcResult_${cardId}`)?.value || 'pending';
  const reason = document.getElementById(`kanbanQcReason_${cardId}`)?.value?.trim() || '';
  if (!type) return showToast('اكتب عنوان فحص الجودة أولاً', 'warning');
  const qc = createQcRecordForCard(cardId, card.qcTemplateId || '', { title: type, result, failureReason: reason, reason });
  appendKanbanActivity(card, `فحص جودة: ${type} → ${result}`);
  if (result === 'pass') markQcPass(qc.id);
  if (result === 'fail') markQcFail(qc.id, reason || 'غير محدد', qc.severity || 'high');
  refreshKanbanInspector(cardId);
}

function addCommentToCardInline(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  const text = document.getElementById(`kanbanCommentText_${cardId}`)?.value?.trim();
  if (!card || !text) return showToast('اكتب التعليق أولاً', 'warning');
  if (!Array.isArray(card.comments)) card.comments = [];
  card.comments.push({ id: makeId('cmt'), text, author: 'Saif', createdAt: new Date().toISOString(), date: todayISO() });
  appendKanbanActivity(card, 'تمت إضافة تعليق جديد');
  refreshKanbanInspector(cardId);
}

async function editKanbanCardLinks(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const html = `
    <label>اسم العميل</label><input id="kanbanLinkClient" class="form-input" value="${escapeHtml(card.clientName || '')}">
    <label>رقم الطلب (Order ID)</label><input id="kanbanLinkOrder" class="form-input" value="${escapeHtml(card.orderId || '')}">
  `;
  const result = await showOmniModal('ربط البطاقة بالطلب', html, body => ({
    clientName: body.querySelector('#kanbanLinkClient')?.value?.trim() || '',
    orderId: body.querySelector('#kanbanLinkOrder')?.value?.trim() || ''
  }));
  if (!result) return;
  card.clientName = result.clientName;
  card.orderId = result.orderId;
  appendKanbanActivity(card, 'تم تحديث روابط العميل والطلب');
  saveData(); openKanbanCardInspector(cardId);
}

async function linkSopToCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const options = (omni.sops || []).map(s => `<option value="${escapeHtml(s.id)}">${escapeHtml(s.code || '')} ${escapeHtml(s.title || '')}</option>`).join('');
  const sopId = await showOmniModal('ربط SOP', `<select id="manualSopId" class="form-input"><option value="">اختر SOP</option>${options}</select>`, body => body.querySelector('#manualSopId')?.value || '');
  if (sopId) linkSopToCardDirect(cardId, sopId);
}

async function linkMachineToCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const options = (omni.machines || []).map(m => `<option value="${escapeHtml(m.id)}">${escapeHtml(m.name || m.id)} (${escapeHtml(m.status || '-')})</option>`).join('');
  const machineId = await showOmniModal('ربط ماكينة', `<select id="manualMachineId" class="form-input"><option value="">اختر ماكينة</option>${options}</select>`, body => body.querySelector('#manualMachineId')?.value || '');
  if (machineId) linkMachineToCardDirect(cardId, machineId);
}

async function linkMaterialToCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const options = (omni.materials || []).map(m => `<option value="${escapeHtml(m.id)}">${escapeHtml(m.name || m.id)} (${getMaterialAvailableQty(m)} ${escapeHtml(m.unit || '')})</option>`).join('');
  const html = `<select id="manualMaterialId" class="form-input"><option value="">اختر مادة</option>${options}</select><input id="manualMaterialQty" class="form-input" type="number" min="0" step="0.01" value="1" placeholder="الكمية">`;
  const result = await showOmniModal('ربط مادة', html, body => ({ materialId: body.querySelector('#manualMaterialId')?.value || '', quantity: parseFloat(body.querySelector('#manualMaterialQty')?.value) || 1 }));
  const mat = (omni.materials || []).find(m => m.id === result?.materialId);
  if (!mat) return showToast('اختر مادة صالحة', 'warning');
  if (!Array.isArray(card.materialRequirements)) card.materialRequirements = [];
  card.materialRequirements.push({ materialId: mat.id, quantity: result.quantity, qty: result.quantity, unit: mat.unit || '' });
  appendKanbanActivity(card, `تم ربط مادة: ${mat.name} × ${result.quantity}`);
  saveData(); openKanbanCardInspector(cardId);
}

async function linkQcToCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const html = `
    <input id="manualQcType" class="form-input" placeholder="نوع فحص الجودة">
    <select id="manualQcResult" class="form-input"><option value="pass">pass</option><option value="pending">pending</option><option value="fail">fail</option></select>
    <input id="manualQcReason" class="form-input" placeholder="سبب الفشل / ملاحظات">
    <input id="manualQcCost" class="form-input" type="number" min="0" value="0" placeholder="تكلفة إعادة العمل">
  `;
  const form = await showOmniModal('إضافة QC', html, body => ({
    type: body.querySelector('#manualQcType')?.value?.trim() || '',
    result: body.querySelector('#manualQcResult')?.value || 'pass',
    reason: body.querySelector('#manualQcReason')?.value?.trim() || '',
    cost: parseInt(body.querySelector('#manualQcCost')?.value || '0', 10) || 0
  }));
  if (!form?.type) return;
  const { type, result, reason, cost } = form;
  const qc = { id: makeId('qc'), taskRef: cardId, type, result, reason, assignee: 'الجودة', date: todayISO(), reworkCost: cost, sopViolation: '' };
  if (!Array.isArray(omni.qcRecords)) omni.qcRecords = [];
  if (!Array.isArray(card.qcRecordIds)) card.qcRecordIds = [];
  omni.qcRecords.push(qc);
  card.qcRecordIds.push(qc.id);
  appendKanbanActivity(card, `فحص جودة: ${type} → ${result}`);
  saveData(); openKanbanCardInspector(cardId);
}

async function addCostToCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const html = `<input id="costDesc" class="form-input" placeholder="وصف الكلفة"><input id="costAmount" class="form-input" type="number" min="0" value="0" placeholder="المبلغ IQD">`;
  const result = await showOmniModal('إضافة كلفة', html, body => ({ desc: body.querySelector('#costDesc')?.value?.trim() || '', amount: parseInt(body.querySelector('#costAmount')?.value || '0', 10) || 0 }));
  if (!result?.desc) return;
  if (!Array.isArray(card.costEntries)) card.costEntries = [];
  const { desc, amount } = result;
  card.costEntries.push({ id: makeId('cost'), description: desc, amount, date: todayISO() });
  appendKanbanActivity(card, `كلفة مضافة: ${desc} — ${amount.toLocaleString()} IQD`);
  saveData(); openKanbanCardInspector(cardId);
}

async function addCommentToCard(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const text = await showOmniPrompt('التعليق:', '');
  if (!text) return;
  if (!Array.isArray(card.comments)) card.comments = [];
  card.comments.push({ id: makeId('cmt'), text, author: 'Saif', date: todayISO() });
  saveData(); openKanbanCardInspector(cardId);
}

function toggleKanbanChecklist(cardId, idx) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card || !card.checklist || !card.checklist[idx]) return;
  card.checklist[idx].done = !card.checklist[idx].done;
  saveData();
}

async function addKanbanChecklistItem(cardId) {
  ensureOmni();
  const card = omni.kanban.cards.find(c => c.id === cardId);
  if (!card) return;
  const text = await showOmniPrompt('بند جديد:', '');
  if (!text) return;
  if (!card.checklist) card.checklist = [];
  card.checklist.push({ text, done: false });
  saveData(); openKanbanCardInspector(cardId);
}

function renderWorkflowStudio() {
  ensureOmni();
  localizeWorkflowPage();
  normalizeWorkflowRelations();
  getWorkflowViewport();
  getWorkflowCanvasSettings();
  bindWorkflowKeyboardShortcuts();
  const canvas = document.getElementById('workflowCanvas');
  const palette = document.getElementById('workflowPalette');
  const summary = document.getElementById('workflowSummary');
  if (!canvas || !palette) return;
  const readiness = validateWorkflowDeep(omni.workflow);
  const simulation = simulateWorkflowRun();
  if (summary) {
    summary.innerHTML = `
      <div class="workflow-header-stat"><b>${readiness.score}%</b><span>جاهزية</span></div>
      <div class="workflow-header-stat"><b>${simulation.totalEstimatedMinutes}</b><span>دقائق</span></div>
      <div class="workflow-header-stat"><b>${simulation.nodesCount}</b><span>خطوات</span></div>
      <div class="workflow-header-stat"><b>${readiness.errors.length + readiness.warnings.length}</b><span>تحذيرات</span></div>
    `;
  }
  palette.innerHTML = [
    ['trigger', 'نقطة بداية', 'fa-play'],
    ['human_task', 'مهمة بشرية', 'fa-user'],
    ['action', 'إجراء', 'fa-bolt'],
    ['approval', 'اعتماد', 'fa-check-double'],
    ['operation', 'تشغيل ورشة', 'fa-gears'],
    ['sop', 'SOP', 'fa-book'],
    ['machine', 'ماكينة', 'fa-cog'],
    ['inventory', 'مخزون', 'fa-boxes-stacked'],
    ['qc', 'فحص جودة', 'fa-microscope'],
    ['finance', 'مالية', 'fa-coins'],
    ['condition', 'شرط', 'fa-code-branch'],
    ['delay', 'تأخير', 'fa-clock'],
    ['notification', 'إشعار', 'fa-bell'],
    ['rework', 'إعادة عمل', 'fa-rotate-left'],
    ['archive', 'أرشفة', 'fa-box-archive']
  ].map(item => `<div class="workflow-tool" draggable="true" ondragstart="omniDragNodeType(event, '${item[0]}')"><i class="fa-solid ${item[2]}"></i><span>${item[1]}</span></div>`).join('');

  const edges = renderWorkflowEdgesSvg(omni.workflow.nodes || [], omni.workflow.edges || []);
  let emptyState = '';
  if (omni.workflow.nodes.length === 0) {
    emptyState = `
      <div class="workflow-empty-state">
        <i class="fa-solid fa-wand-magic-sparkles" style="font-size:32px;color:var(--primary);margin-bottom:16px;"></i>
        <h3>مرحباً بك في مصمم العمليات</h3>
        <p>ابدأ بتصميم عملية جديدة أو حمّل مثال فحص شامل لتجربة كل الإمكانيات.</p>
        <div style="display:flex;flex-direction:column;gap:10px;">
          <button class="btn-primary" onclick="addWorkflowNode('trigger')" style="width:100%;"><i class="fa-solid fa-play"></i> إضافة نقطة بداية</button>
          <button class="btn-primary" onclick="openComprehensiveWorkflowDemoModal()" style="width:100%;"><i class="fa-solid fa-flask-vial"></i> تحميل مثال فحص شامل</button>
          <button class="btn-secondary" onclick="openWorkflowTemplates()" style="width:100%;"><i class="fa-solid fa-gears"></i> قوالب جاهزة</button>
        </div>
      </div>
    `;
  }

  canvas.classList.toggle('workflow-grid-hidden', !workflowCanvasSettings.showGrid);
  const readOnlyBanner = isWorkflowReadOnly() ? `
    <div class="workflow-readonly-banner" style="background: rgba(239, 68, 68, 0.15); border: 1px solid rgba(239, 68, 68, 0.3); color: #ef4444; padding: 10px 16px; border-radius: 8px; display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 12px; font-size: 13px; backdrop-filter: blur(8px); direction: rtl;">
      <span style="display:flex; align-items:center; gap:8px;"><i class="fa-solid fa-lock"></i> <b>سير العمل منشور حالياً (إصدار ${omni.workflow?.version || 1}) وهو للقراءة فقط.</b></span>
      <button class="btn-secondary" style="padding: 4px 12px; background: rgba(239, 68, 68, 0.2); border-color: rgba(239, 68, 68, 0.3); color: #ef4444; font-size:11px;" onclick="unpublishWorkflow()"><i class="fa-solid fa-pencil"></i> إلغاء النشر للتعديل</button>
    </div>
  ` : '';
  canvas.innerHTML = `
    ${readOnlyBanner}
    <div class="workflow-canvas-toolbar workflow-toolbar-v2">
      <button class="btn-ghost" onclick="zoomWorkflow(0.1)" title="تكبير"><i class="fa-solid fa-plus"></i> تكبير</button>
      <button class="btn-ghost" onclick="zoomWorkflow(-0.1)" title="تصغير"><i class="fa-solid fa-minus"></i> تصغير</button>
      <span id="workflowZoomLabel" class="workflow-zoom-label">${Math.round(workflowViewport.zoom * 100)}%</span>
      <button class="btn-ghost" onclick="fitWorkflowToScreen()"><i class="fa-solid fa-expand"></i> ملاءمة الشاشة</button>
      <button class="btn-ghost" onclick="resetWorkflowViewport()"><i class="fa-solid fa-rotate-left"></i> إعادة ضبط العرض</button>
      <button class="btn-ghost" onclick="applyWorkflowAutoLayout()"><i class="fa-solid fa-diagram-project"></i> ترتيب تلقائي</button>
      <button class="btn-ghost" onclick="openComprehensiveWorkflowDemoModal()"><i class="fa-solid fa-flask-vial"></i> مثال فحص شامل</button>
      <button class="btn-ghost" onclick="undoWorkflowChange()"><i class="fa-solid fa-rotate-left"></i> تراجع</button>
      <button class="btn-ghost" onclick="redoWorkflowChange()"><i class="fa-solid fa-rotate-right"></i> إعادة</button>
      <label class="workflow-toggle"><input type="checkbox" ${workflowCanvasSettings.snapToGrid ? 'checked' : ''} onchange="updateWorkflowCanvasSettings({snapToGrid:this.checked})"> محاذاة للشبكة</label>
      <label class="workflow-toggle"><input type="checkbox" ${workflowCanvasSettings.showGrid ? 'checked' : ''} onchange="updateWorkflowCanvasSettings({showGrid:this.checked})"> إظهار الشبكة</label>
    </div>
    <div class="workflow-canvas-inner">
      <svg class="workflow-lines" viewBox="0 0 6000 4000" preserveAspectRatio="xMinYMin meet">${edges}</svg>
      ${emptyState}
      ${omni.workflow.nodes.map(node => {
    const badges = [
      node.linkedSopId ? '<span title="SOP مرتبط"><i class="fa-solid fa-book"></i></span>' : workflowNodeNeedsSop(node) ? '<span class="workflow-node-warn" title="SOP مفقود"><i class="fa-solid fa-book"></i></span>' : '',
      node.linkedMachineId ? '<span title="ماكينة مرتبطة"><i class="fa-solid fa-gear"></i></span>' : workflowNodeNeedsMachine(node) ? '<span class="workflow-node-warn" title="ماكينة مفقودة"><i class="fa-solid fa-gear"></i></span>' : '',
      (node.materialRequirements || []).length ? `<span title="مواد"><i class="fa-solid fa-cube"></i> ${(node.materialRequirements || []).length}</span>` : '',
      node.estimatedMinutes ? `<span title="دقائق تقديرية"><i class="fa-solid fa-clock"></i> ${node.estimatedMinutes}</span>` : ''
    ].filter(Boolean).join('');
    const nodeValidation = validateWorkflowDeep({ nodes: omni.workflow.nodes || [], edges: omni.workflow.edges || [] });
    const nodeWarning = [...nodeValidation.errors, ...nodeValidation.warnings].some(item => item.nodeId === node.id);
    const nodeReadiness = calculateWorkflowNodeReadiness(node);
    const ports = getWorkflowNodePorts(node).map(port => {
      const semantic = getWorkflowPortSemantic(node, port.name);
      const style = getWorkflowConnectionStyle(semantic);
      const connected = isWorkflowPortConnected(node.id, port.name);
      const active = workflowPortLink?.nodeId === node.id && workflowPortLink?.portName === port.name;
      const title = `${port.label} · ${style.label}${connected ? ' · متصل' : ' · غير متصل'}`;
      return `<button class="workflow-node-port workflow-node-port-${port.name} workflow-node-port-${port.type} workflow-port-${semantic} ${connected ? 'is-connected' : 'is-empty'} ${active ? 'workflow-node-port-active' : ''}" style="--workflow-port-color:${style.color};--workflow-port-glow:${style.glow}" title="${escapeHtml(title)}" aria-label="${escapeHtml(title)}" onclick="event.stopPropagation(); ${port.type === 'input' ? `completeWorkflowPortLink('${node.id}', '${port.name}')` : `startWorkflowPortLink('${node.id}', '${port.name}')`}"></button>`;
    }).join('');
    return `
    <div class="workflow-node workflow-node-v2 node-${escapeHtml(node.type)} ${omni.workflow.selectedNodeId === node.id ? 'workflow-node-selected workflow-node-selected-v2' : ''} ${nodeWarning ? 'workflow-node-warning' : ''}" data-workflow-node-id="${escapeHtml(node.id)}" style="left:${node.x}px;top:${node.y}px" onpointerdown="startWorkflowNodePointer(event, '${node.id}')" onclick="selectWorkflowNode('${node.id}', event)">
      ${ports}
      <span class="workflow-node-readiness">${nodeReadiness}%</span>
      <div class="node-type">${escapeHtml(getWorkflowNodeLabel(node.type))}</div><h4 ondblclick="event.stopPropagation(); openWorkflowNodeQuickMenu('${node.id}', event.clientX, event.clientY, true)">${escapeHtml(node.title)}</h4><p>${escapeHtml(node.description || '')}</p><div class="workflow-node-badges">${badges}</div>
    </div>`;
  }).join('')}
    </div>
    <div id="workflowMinimap" class="workflow-minimap"></div>`;
  canvas.onpointerdown = startWorkflowPan;
  canvas.onpointermove = function(event) { moveWorkflowPan(event); updateWorkflowTemporaryEdge(event); };
  canvas.onpointerup = endWorkflowPan;
  canvas.onpointercancel = endWorkflowPan;
  canvas.onclick = function(event) {
    if (event.target.closest?.('.workflow-node, .workflow-node-quick-menu, .workflow-edge, .workflow-canvas-toolbar, .workflow-minimap')) return;
    closeWorkflowNodeQuickMenu();
    closeWorkflowEdgeToolbar();
    clearWorkflowTemporaryInteraction();
    setWorkflowSelection({});
    renderWorkflowStudio();
  };
  canvas.onwheel = function(event) {
    event.preventDefault();
    if (event.ctrlKey || event.metaKey || event.altKey) {
      const step = event.ctrlKey || event.metaKey ? 0.16 : 0.1;
      setWorkflowZoom(workflowViewport.zoom + (event.deltaY < 0 ? step : -step), event.clientX, event.clientY);
      return;
    }
    if (event.shiftKey) {
      workflowViewport.panX -= event.deltaY;
    } else {
      workflowViewport.panX -= event.deltaX;
      workflowViewport.panY -= event.deltaY;
    }
    applyWorkflowViewport({ skipSave: true, skipMinimap: true });
    clearTimeout(workflowViewportCommitTimer);
    workflowViewportCommitTimer = setTimeout(() => applyWorkflowViewport(), 120);
  };
  applyWorkflowViewport();
}

function omniDragNodeType(ev, type) {
  omniDraggedNodeType = type;
  ev.dataTransfer.setData('nodeType', type);
}

function omniDragExistingNode(ev, nodeId) {
  ev.dataTransfer.setData('nodeId', nodeId);
}

function workflowCanvasDrop(ev) {
  ev.preventDefault();
  ensureOmni();
  const point = screenToWorkflowPoint(ev.clientX, ev.clientY);
  const nodeId = ev.dataTransfer.getData('nodeId');
  if (nodeId) {
    const node = omni.workflow.nodes.find(n => n.id === nodeId);
    if (node) {
      pushWorkflowUndoSnapshot('node_move');
      node.x = Math.max(10, snapWorkflowPoint(point.x - 100));
      node.y = Math.max(10, snapWorkflowPoint(point.y - 56));
      addWorkflowNodeActivity(node.id, 'تم نقل الخطوة على لوحة العملية');
    }
  } else {
    const type = omniDraggedNodeType || ev.dataTransfer.getData('nodeType') || 'action';
    pushWorkflowUndoSnapshot('node_create');
    omni.workflow.nodes.push({ id: makeId('wf'), type, title: getWorkflowNodeLabel(type), x: Math.max(10, snapWorkflowPoint(point.x - 100)), y: Math.max(10, snapWorkflowPoint(point.y - 56)), sop: '', description: 'اضغط لتعديل التفاصيل', linkedSopId: '', linkedMachineId: '', linkedOperationPackId: '', linkedCardId: '', linkedTaskId: '', linkedQcRecordId: '', orderId: '', department: '', branch: '', materialRequirements: [], assignedRole: '', estimatedMinutes: 0, costImpact: 0, successPath: '', failurePath: '', activityLog: [{ date: new Date().toISOString(), text: 'تم إنشاء الخطوة' }] });
  }
  omniDraggedNodeType = null;
  saveData();
  renderWorkflowStudio();
}

function selectWorkflowNode(nodeId, event) {
  ensureOmni();
  event?.stopPropagation?.();
  if (workflowInteractionState.didDrag) {
    workflowInteractionState.didDrag = false;
    return;
  }
  
  if (workflowPortLink && workflowInteractionState.mode === 'connect') {
    if (workflowPortLink.nodeId !== nodeId) {
      completeWorkflowPortLink(nodeId, 'input');
      return;
    }
  }

  const node = omni.workflow.nodes.find(n => n.id === nodeId);
  if (!node) return;
  setWorkflowSelection({ nodeId: node.id, edgeId: null });
  closeWorkflowEdgeToolbar();
  const screen = event ? { x: event.clientX, y: event.clientY } : workflowToScreenPoint(Number(node.x) || 0, Number(node.y) || 0);
  renderWorkflowStudio();
  openWorkflowNodeQuickMenu(node.id, screen.x, screen.y);
  return;
}

function addWorkflowNode(type = 'action') {
  ensureOmni();
  if (isWorkflowReadOnly()) {
    showToast('العملية منشورة وحالياً للقراءة فقط. يرجى إلغاء النشر للتعديل عليها.', 'warning');
    return;
  }
  pushWorkflowUndoSnapshot('node_create');
  omni.workflow.nodes.push({ id: makeId('wf'), type, title: getWorkflowNodeLabel(type), x: 120, y: 140, sop: '', description: 'اضغط لتعديل التفاصيل', linkedSopId: '', linkedMachineId: '', linkedOperationPackId: '', linkedCardId: '', linkedTaskId: '', linkedQcRecordId: '', orderId: '', department: '', branch: '', materialRequirements: [], assignedRole: '', estimatedMinutes: 0, costImpact: 0, successPath: '', failurePath: '', activityLog: [{ date: new Date().toISOString(), text: 'تم إنشاء الخطوة' }] });
  saveData();
  renderWorkflowStudio();
}

function clearWorkflowSelection() {
  ensureOmni();
  omni.workflow.selectedFrom = null;
  omni.workflow.selectedEdgeId = null;
  workflowPortLink = null;
  showToast('تم إلغاء التحديد والربط', 'info');
  renderWorkflowStudio();
}

function renderWorkflowEdgeToolbar(edge) {
  const from = getWorkflowNodeById(edge.from || edge.source || edge.sourceNodeId);
  const to = getWorkflowNodeById(edge.to || edge.target || edge.targetNodeId);
  return `
    <div class="workflow-edge-toolbar-head">
      <b>رابط العملية</b>
      <button class="icon-btn" onclick="closeWorkflowEdgeToolbar()" title="إغلاق"><i class="fa-solid fa-xmark"></i></button>
    </div>
    <small>${escapeHtml(from?.title || edge.from || '')} ← ${escapeHtml(to?.title || edge.to || '')}</small>
    <label>التسمية<input id="wfEdgeQuickLabel" class="workflow-insp-input" value="${escapeHtml(edge.label || '')}"></label>
    <div class="workflow-edge-toolbar-actions">
      <button class="btn-primary" onclick="saveWorkflowEdgeQuickEdit('${edge.id}')"><i class="fa-solid fa-check"></i> حفظ</button>
      <button class="btn-secondary" onclick="openWorkflowEdgeInspector('${edge.id}'); closeWorkflowEdgeToolbar();"><i class="fa-solid fa-sliders"></i> تحرير متقدم</button>
      <button class="btn-danger" onclick="deleteWorkflowEdgeExplicit('${edge.id}')"><i class="fa-solid fa-trash"></i> حذف الرابط</button>
    </div>
  `;
}

function openWorkflowEdgeToolbar(edgeId, screenX, screenY) {
  const edge = (omni.workflow.edges || []).find(e => e.id === edgeId);
  if (!edge) return;
  closeWorkflowNodeQuickMenu();
  closeWorkflowEdgeToolbar();
  const point = clampWorkflowFloatingPoint(screenX + 10, screenY - 12, 320, 230);
  const toolbar = document.createElement('div');
  toolbar.id = 'workflowEdgeToolbar';
  toolbar.className = 'workflow-edge-toolbar';
  toolbar.style.left = `${point.x}px`;
  toolbar.style.top = `${point.y}px`;
  toolbar.dir = 'rtl';
  toolbar.innerHTML = renderWorkflowEdgeToolbar(edge);
  toolbar.addEventListener('pointerdown', event => event.stopPropagation());
  toolbar.addEventListener('click', event => event.stopPropagation());
  document.body.appendChild(toolbar);
  workflowInteractionState.edgeToolbarId = edgeId;
  workflowInteractionState.edgeToolbarX = point.x;
  workflowInteractionState.edgeToolbarY = point.y;
}

function saveWorkflowEdgeQuickEdit(edgeId) {
  if (isWorkflowReadOnly()) {
    showToast('العملية منشورة وحالياً للقراءة فقط. يرجى إلغاء النشر للتعديل عليها.', 'warning');
    return;
  }
  const edge = (omni.workflow.edges || []).find(e => e.id === edgeId);
  if (!edge) return;
  edge.label = document.getElementById('wfEdgeQuickLabel')?.value?.trim() || edge.label || '';
  saveData();
  renderWorkflowStudio();
  openWorkflowEdgeToolbar(edgeId, workflowInteractionState.edgeToolbarX, workflowInteractionState.edgeToolbarY);
  showToast('تم تحديث الرابط', 'success');
}

async function deleteWorkflowEdgeExplicit(edgeId) {
  closeWorkflowEdgeToolbar();
  await deleteWorkflowEdge(edgeId, { skipConfirm: true });
}

function openWorkflowEdgeInspector(edgeId) {
  ensureOmni();
  omni.workflow.selectedEdgeId = edgeId;
  const edge = (omni.workflow.edges || []).find(e => e.id === edgeId);
  const from = edge ? getWorkflowNodeById(edge.from || edge.source || edge.sourceNodeId) : null;
  const to = edge ? getWorkflowNodeById(edge.to || edge.target || edge.targetNodeId) : null;
  renderWorkflowStudio();
  const panel = document.getElementById('inspectorPanel');
  const overlay = document.getElementById('inspectorOverlay');
  const title = document.getElementById('inspectorTitle');
  const tabs = document.getElementById('inspectorTabs');
  const body = document.getElementById('inspectorBody');
  if (!panel || !edge) return;
  title.textContent = 'رابط العملية';
  tabs.innerHTML = '<button class="insp-tab active">الرابط</button>';
  body.innerHTML = `
    <div class="insp-section"><h4>من</h4><p>${escapeHtml(from?.title || edge.from)}</p></div>
    <div class="insp-section"><h4>إلى</h4><p>${escapeHtml(to?.title || edge.to)}</p></div>
    <div class="insp-section"><h4>التسمية</h4><input class="workflow-insp-input" value="${escapeHtml(edge.label || '')}" onchange="updateWorkflowEdgeLabel('${edge.id}', this.value)"></div>
    <div class="workflow-insp-grid">
      <label>منفذ المصدر<select class="workflow-insp-input" onchange="updateWorkflowEdgePort('${edge.id}', 'sourcePort', this.value)">
        ${['output','success','failure','rework'].map(p => `<option value="${p}" ${edge.sourcePort === p ? 'selected' : ''}>${p === 'output' ? 'مخرج' : p === 'success' ? 'نجاح' : p === 'failure' ? 'فشل' : 'إعادة عمل'}</option>`).join('')}
      </select></label>
      <label>نوع الرابط<select class="workflow-insp-input" onchange="updateWorkflowEdgePort('${edge.id}', 'type', this.value)">
        ${['normal','success','failure','rework'].map(p => `<option value="${p}" ${edge.type === p ? 'selected' : ''}>${p === 'normal' ? 'عادي' : p === 'success' ? 'نجاح' : p === 'failure' ? 'فشل' : 'إعادة عمل'}</option>`).join('')}
      </select></label>
    </div>
    <div class="insp-actions"><button class="btn-danger" onclick="deleteWorkflowEdge('${edge.id}')"><i class="fa-solid fa-trash"></i> حذف الرابط</button></div>
  `;
  panel.classList.remove('hidden');
  overlay.classList.remove('hidden');
}

function selectWorkflowEdge(edgeId, event) {
  ensureOmni();
  event?.stopPropagation?.();
  const edge = (omni.workflow.edges || []).find(e => e.id === edgeId);
  if (!edge) return;
  setWorkflowSelection({ nodeId: null, edgeId });
  renderWorkflowStudio();
  if (event) {
    openWorkflowEdgeToolbar(edgeId, event.clientX, event.clientY);
  } else {
    const from = getWorkflowNodeById(edge.from || edge.source || edge.sourceNodeId);
    const to = getWorkflowNodeById(edge.to || edge.target || edge.targetNodeId);
    const mid = from && to ? getWorkflowEdgeMidpoint(from, to, edge) : { x: 160, y: 160 };
    const screen = workflowToScreenPoint(mid.x, mid.y);
    openWorkflowEdgeToolbar(edgeId, screen.x, screen.y);
  }
}

function updateWorkflowEdgeLabel(edgeId, label) {
  const edge = (omni.workflow.edges || []).find(e => e.id === edgeId);
  if (!edge) return;
  edge.label = label;
  saveData();
  renderWorkflowStudio();
  openWorkflowEdgeInspector(edgeId);
}

function updateWorkflowEdgePort(edgeId, field, value) {
  const edge = (omni.workflow.edges || []).find(e => e.id === edgeId);
  if (!edge) return;
  edge[field] = value;
  if (field === 'type' && ['success', 'failure', 'rework'].includes(value)) edge.sourcePort = value;
  if (field === 'sourcePort') edge.type = normalizeWorkflowPortName(value) === 'output' ? 'normal' : normalizeWorkflowPortName(value);
  if (field === 'sourcePort' || field === 'targetPort') edge[field] = normalizeWorkflowPortName(edge[field]);
  saveData();
  renderWorkflowStudio();
  openWorkflowEdgeInspector(edgeId);
}

function setWorkflowLinkSource(nodeId) {
  ensureOmni();
  startWorkflowPortLink(nodeId, 'output');
}

function openWorkflowNodeInspector(nodeId, activeTab = 0) {
  ensureOmni();
  const node = getWorkflowNodeById(nodeId);
  const panel = document.getElementById('inspectorPanel');
  const overlay = document.getElementById('inspectorOverlay');
  const title = document.getElementById('inspectorTitle');
  const tabs = document.getElementById('inspectorTabs');
  const body = document.getElementById('inspectorBody');
  if (!node || !panel || !overlay || !title || !tabs || !body) return;
  omni.workflow.selectedNodeId = node.id;
  title.textContent = node.title || 'خطوة في العملية';
  const tabList = ['نظرة عامة', 'روابط', 'مواد', 'مسارات', 'محاكاة', 'نشاط', 'روابط خلفية'];

  function renderTab(tabIdx) {
    const current = getWorkflowNodeById(nodeId);
    if (!current) return;
    tabs.innerHTML = tabList.map((t, i) => `<button class="insp-tab ${i === tabIdx ? 'active' : ''}" onclick="renderWorkflowInspectorTab('${nodeId}', ${i})">${t}</button>`).join('');
    if (tabIdx === 0) {
      body.innerHTML = renderWorkflowOverviewTab(current);
    } else if (tabIdx === 1) {
      body.innerHTML = renderWorkflowLinksTab(current);
    } else if (tabIdx === 2) {
      body.innerHTML = renderWorkflowMaterialsTab(current);
    } else if (tabIdx === 3) {
      body.innerHTML = renderWorkflowRoutingTab(current);
    } else if (tabIdx === 4) {
      body.innerHTML = renderWorkflowSimulationTab();
    } else if (tabIdx === 5) {
      body.innerHTML = `
        <div class="insp-section"><h4>النشاط</h4>
          ${(current.activityLog || []).map(item => `<div class="insp-linked-item"><b>${escapeHtml(item.text)}</b><small>${escapeHtml(item.date)}</small></div>`).join('') || '<p>لا يوجد نشاط بعد</p>'}
        </div>
      `;
    } else {
      body.innerHTML = renderWorkflowNodeRelations(nodeId);
    }
  }

  renderTab(activeTab);
  window.renderWorkflowInspectorTab = function(nid, idx) { openWorkflowNodeInspector(nid, idx); };
  panel.classList.remove('hidden');
  overlay.classList.remove('hidden');
}

function renderWorkflowOverviewTab(node) {
  const validation = validateWorkflowDeep(omni.workflow);
  const warnings = [...validation.errors, ...validation.warnings].filter(item => item.nodeId === node.id);
  return `
    <div class="workflow-node-inspector-summary">
      <span><b>النوع</b>${escapeHtml(getWorkflowNodeLabel(node.type))}</span>
      <span><b>الجاهزية</b>${calculateWorkflowNodeReadiness(node)}%</span>
      <span><b>SOP</b>${escapeHtml(getSopById(node.linkedSopId)?.title || '-')}</span>
      <span><b>الماكينة</b>${escapeHtml(getMachineById(node.linkedMachineId)?.name || '-')}</span>
      <span><b>المواد</b>${(node.materialRequirements || []).length}</span>
      <span><b>التحذيرات</b>${warnings.length}</span>
    </div>
    <div class="workflow-insp-grid">
      <label>العنوان<input class="workflow-insp-input" value="${escapeHtml(node.title || '')}" onchange="workflowNodeFieldChanged('${node.id}', 'title', this.value, 'تم تحديث العنوان')"></label>
      <label>النوع<select class="workflow-insp-input" onchange="workflowNodeFieldChanged('${node.id}', 'type', this.value, 'تم تحديث النوع')">${WORKFLOW_NODE_TYPES.map(t => `<option value="${t}" ${node.type === t ? 'selected' : ''}>${getWorkflowNodeLabel(t)}</option>`).join('')}</select></label>
      <label>الوصف<textarea class="workflow-insp-input" onchange="workflowNodeFieldChanged('${node.id}', 'description', this.value, 'تم تحديث الوصف')">${escapeHtml(node.description || '')}</textarea></label>
      <label>الدور المسؤول<input class="workflow-insp-input" value="${escapeHtml(node.assignedRole || '')}" onchange="workflowNodeFieldChanged('${node.id}', 'assignedRole', this.value, 'تم تحديث الدور المسؤول')"></label>
      <label>القسم<input class="workflow-insp-input" value="${escapeHtml(node.department || '')}" onchange="workflowNodeFieldChanged('${node.id}', 'department', this.value, 'تم تحديث القسم')"></label>
      <label>الفرع<input class="workflow-insp-input" value="${escapeHtml(node.branch || '')}" onchange="workflowNodeFieldChanged('${node.id}', 'branch', this.value, 'تم تحديث الفرع')"></label>
      <label>الدقائق التقديرية<input type="number" min="0" class="workflow-insp-input" value="${Number(node.estimatedMinutes) || 0}" onchange="workflowNodeFieldChanged('${node.id}', 'estimatedMinutes', this.value, 'تم تحديث الوقت التقديري')"></label>
      <label>أثر الكلفة<input type="number" min="0" class="workflow-insp-input" value="${Number(node.costImpact) || 0}" onchange="workflowNodeFieldChanged('${node.id}', 'costImpact', this.value, 'تم تحديث أثر الكلفة')"></label>
    </div>
    <div class="insp-actions">
      <button class="btn-primary" onclick="setWorkflowLinkSource('${node.id}')"><i class="fa-solid fa-link"></i> بدء الربط</button>
      <button class="btn-danger" onclick="deleteWorkflowNode('${node.id}')"><i class="fa-solid fa-trash"></i> حذف الخطوة</button>
    </div>
  `;
}

function renderWorkflowLinksTab(node) {
  return `
    <div class="workflow-insp-grid">
      <label>SOP<select class="workflow-insp-input" onchange="workflowNodeSelectChanged('${node.id}', 'linkedSopId', this.value, 'تم ربط SOP')">
        <option value="">بدون SOP</option>${(omni.sops || []).map(s => `<option value="${s.id}" ${node.linkedSopId === s.id ? 'selected' : ''}>${escapeHtml(s.code || s.title)} - ${escapeHtml(s.title)}</option>`).join('')}
      </select></label>
      <label>ماكينة<select class="workflow-insp-input" onchange="workflowNodeSelectChanged('${node.id}', 'linkedMachineId', this.value, 'تم ربط ماكينة')">
        <option value="">بدون ماكينة</option>${(omni.machines || []).map(m => `<option value="${m.id}" ${node.linkedMachineId === m.id ? 'selected' : ''}>${escapeHtml(m.name)}</option>`).join('')}
      </select></label>
      <label>باقة عمليات<select class="workflow-insp-input" onchange="workflowNodeSelectChanged('${node.id}', 'linkedOperationPackId', this.value, 'تم ربط باقة عمليات')">
        <option value="">بدون باقة عمليات</option>${(omni.opPacks || []).map(p => `<option value="${p.id}" ${node.linkedOperationPackId === p.id ? 'selected' : ''}>${escapeHtml(p.name)}</option>`).join('')}
      </select></label>
      <label>بطاقة اللوحة<select class="workflow-insp-input" onchange="workflowNodeSelectChanged('${node.id}', 'linkedCardId', this.value, 'تم ربط بطاقة اللوحة')">
        <option value="">بدون بطاقة</option>${(omni.kanban?.cards || []).map(c => `<option value="${c.id}" ${node.linkedCardId === c.id ? 'selected' : ''}>${escapeHtml(c.title)}</option>`).join('')}
      </select></label>
      <label>سجل QC<select class="workflow-insp-input" onchange="workflowNodeSelectChanged('${node.id}', 'linkedQcRecordId', this.value, 'تم ربط سجل QC')">
        <option value="">بدون QC</option>${(omni.qcRecords || []).map(q => `<option value="${q.id}" ${node.linkedQcRecordId === q.id ? 'selected' : ''}>${escapeHtml(q.type || q.id)} - ${escapeHtml(q.result || '')}</option>`).join('')}
      </select></label>
      <label>رقم الطلب<input class="workflow-insp-input" value="${escapeHtml(node.orderId || '')}" onchange="workflowNodeSelectChanged('${node.id}', 'orderId', this.value, 'تم تحديث رقم الطلب')"></label>
    </div>
    <div class="insp-section"><h4>الروابط الحالية</h4>
      <p>SOP: ${escapeHtml(getSopById(node.linkedSopId)?.title || '-')}</p>
      <p>الماكينة: ${escapeHtml(getMachineById(node.linkedMachineId)?.name || '-')}</p>
      <p>باقة العمليات: ${escapeHtml(getOperationPackById(node.linkedOperationPackId)?.name || '-')}</p>
      <p>بطاقة اللوحة: ${escapeHtml((omni.kanban?.cards || []).find(c => c.id === node.linkedCardId)?.title || '-')}</p>
    </div>
  `;
}

function getWorkflowNodeRelations(node) {
  return [
    node.linkedSopId && { type: 'sop', id: node.linkedSopId, title: getSopById(node.linkedSopId)?.title || node.linkedSopId, label: 'SOP' },
    node.linkedMachineId && { type: 'machine', id: node.linkedMachineId, title: getMachineById(node.linkedMachineId)?.name || node.linkedMachineId, label: 'ماكينة' },
    node.linkedOperationPackId && { type: 'op_pack', id: node.linkedOperationPackId, title: getOperationPackById(node.linkedOperationPackId)?.name || node.linkedOperationPackId, label: 'باقة عمليات' },
    node.linkedCardId && { type: 'kanban_card', id: node.linkedCardId, title: (omni.kanban?.cards || []).find(c => c.id === node.linkedCardId)?.title || node.linkedCardId, label: 'بطاقة اللوحة' },
    node.linkedQcRecordId && { type: 'qc_record', id: node.linkedQcRecordId, title: getQcRecordById(node.linkedQcRecordId)?.type || node.linkedQcRecordId, label: 'QC' },
    node.orderId && { type: 'order', id: node.orderId, title: getOrderById(node.orderId)?.title || node.orderId, label: 'طلب' },
    ...(node.materialRequirements || []).map(req => ({ type: 'material', id: req.materialId, title: getMaterialById(req.materialId)?.name || req.materialId, label: 'مادة' }))
  ].filter(Boolean);
}

function renderWorkflowNodeRelations(nodeId) {
  const node = getWorkflowNodeById(nodeId);
  if (!node) return '';
  const relations = getWorkflowNodeRelations(node);
  return `
    <div class="insp-section"><h4>روابط هذه الخطوة</h4>
      ${relations.map(r => `<div class="insp-linked-item workflow-inspector-linked-card" onclick="openOmniEntity('${r.type}', '${r.id}')" style="cursor:pointer"><b>${escapeHtml(r.label)}: ${escapeHtml(r.title)}</b><small>${escapeHtml(r.id)}</small></div>`).join('') || '<p>لا توجد روابط بعد</p>'}
    </div>
    <div class="insp-section"><h4>الروابط الخلفية</h4>
      ${typeof renderEntityRelationsPanel === 'function' ? renderEntityRelationsPanel('workflow_node', nodeId) : '<p>لوحة الروابط الخلفية غير متاحة</p>'}
    </div>
  `;
}

function linkWorkflowNodeToEntity(nodeId, entityType, entityId) {
  const node = getWorkflowNodeById(nodeId);
  if (!node) return;
  const fieldMap = { sop: 'linkedSopId', machine: 'linkedMachineId', op_pack: 'linkedOperationPackId', kanban_card: 'linkedCardId', task: 'linkedTaskId', qc_record: 'linkedQcRecordId', order: 'orderId' };
  const field = fieldMap[entityType];
  if (!field) return;
  node[field] = entityId || '';
  addWorkflowNodeActivity(nodeId, `تم تحديث رابط ${entityType}`);
  saveData();
  openWorkflowNodeInspector(nodeId, 6);
}

function unlinkWorkflowNodeEntity(nodeId, entityType) {
  linkWorkflowNodeToEntity(nodeId, entityType, '');
}

function renderWorkflowMaterialsTab(node) {
  return `
    <div class="insp-section"><h4>المواد المطلوبة</h4>
      ${(node.materialRequirements || []).map((req, idx) => {
        const mat = getMaterialById(req.materialId);
        const qty = getMaterialRequirementQty(req);
        const status = materialAvailabilityStatus(req);
        const label = status === 'available' ? 'متوفر' : status === 'short' ? 'ناقص' : 'مفقود';
        return `<div class="workflow-material-row">
          <div><b>${escapeHtml(mat?.name || req.materialId || 'مادة مفقودة')}</b><small>مطلوب ${qty} ${escapeHtml(req.unit || mat?.unit || '')} / متاح ${mat ? getMaterialAvailableQty(mat) : 0}</small></div>
          <span class="workflow-status-pill workflow-status-${status}">${label}</span>
          <button class="btn-xs btn-danger" onclick="removeWorkflowNodeMaterial('${node.id}', ${idx})"><i class="fa-solid fa-times"></i></button>
        </div>`;
      }).join('') || '<p>لا توجد مواد مرتبطة</p>'}
    </div>
    <div class="workflow-insp-grid">
      <label>المادة<select class="workflow-insp-input" id="workflowMaterialSelect">${(omni.materials || []).map(m => `<option value="${m.id}">${escapeHtml(m.name)} (${getMaterialAvailableQty(m)} ${escapeHtml(m.unit || '')})</option>`).join('')}</select></label>
      <label>الكمية<input class="workflow-insp-input" id="workflowMaterialQty" type="number" min="0" step="0.01" value="1"></label>
      <label>الوحدة<input class="workflow-insp-input" id="workflowMaterialUnit" value=""></label>
    </div>
    <div class="insp-actions"><button class="btn-primary" onclick="addWorkflowNodeMaterial('${node.id}')"><i class="fa-solid fa-plus"></i> إضافة مادة</button></div>
  `;
}

function renderWorkflowRoutingTab(node) {
  const options = (omni.workflow.nodes || []).filter(n => n.id !== node.id).map(n => `<option value="${n.id}">${escapeHtml(n.title)}</option>`).join('');
  const outEdges = (omni.workflow.edges || []).filter(e => (e.from || e.source || e.sourceNodeId) === node.id);
  const inEdges = (omni.workflow.edges || []).filter(e => (e.to || e.target || e.targetNodeId) === node.id);
  return `
    <div class="workflow-insp-grid">
      <label>مسار نجاح<select class="workflow-insp-input" onchange="workflowNodeSelectChanged('${node.id}', 'successPath', this.value, 'تم تحديث مسار النجاح')"><option value="">بدون مسار نجاح</option>${(omni.workflow.nodes || []).filter(n => n.id !== node.id).map(n => `<option value="${n.id}" ${node.successPath === n.id ? 'selected' : ''}>${escapeHtml(n.title)}</option>`).join('')}</select></label>
      <label>مسار فشل<select class="workflow-insp-input" onchange="workflowNodeSelectChanged('${node.id}', 'failurePath', this.value, 'تم تحديث مسار الفشل')"><option value="">بدون مسار فشل</option>${(omni.workflow.nodes || []).filter(n => n.id !== node.id).map(n => `<option value="${n.id}" ${node.failurePath === n.id ? 'selected' : ''}>${escapeHtml(n.title)}</option>`).join('')}</select></label>
    </div>
    <div class="insp-section"><h4>الروابط</h4>
      ${outEdges.map(e => `<div class="insp-linked-item"><b>خارج إلى ${escapeHtml(getWorkflowNodeById(e.to || e.target || e.targetNodeId)?.title || e.to || e.target || e.targetNodeId)}</b><small>${escapeHtml(e.label || '')}</small><button class="btn-xs btn-danger" onclick="deleteWorkflowEdge('${e.id}')">حذف الرابط</button></div>`).join('') || '<p>لا توجد روابط خارجة</p>'}
      ${inEdges.map(e => `<div class="insp-linked-item"><b>داخل من ${escapeHtml(getWorkflowNodeById(e.from || e.source || e.sourceNodeId)?.title || e.from || e.source || e.sourceNodeId)}</b><small>${escapeHtml(e.label || '')}</small></div>`).join('')}
    </div>
    <div class="insp-actions"><button class="btn-primary" onclick="setWorkflowLinkSource('${node.id}')"><i class="fa-solid fa-link"></i> بدء الربط من هذه الخطوة</button></div>
  `;
}

function renderWorkflowSimulationTab() {
  const result = simulateWorkflowRun();
  return `
    <div class="workflow-sim-score"><b>${result.readiness.score}%</b><span>جاهزية العملية</span></div>
    <div class="workflow-sim-grid">
      <div><b>${result.nodesCount}</b><span>خطوات</span></div>
      <div><b>${result.edgesCount}</b><span>روابط</span></div>
      <div><b>${result.totalEstimatedMinutes}</b><span>دقائق</span></div>
      <div><b>${result.totalCostImpact.toLocaleString()}</b><span>كلفة</span></div>
    </div>
    <div class="insp-section"><h4>المواد</h4>${result.materials.map(m => `<div class="insp-linked-item"><b>${escapeHtml(m.name)}</b><small>مطلوب ${m.qty} ${escapeHtml(m.unit)} / متاح ${m.available}</small></div>`).join('') || '<p>لا توجد مواد مطلوبة</p>'}</div>
    <div class="insp-section"><h4>مواد ناقصة</h4>${result.missingMaterials.map(m => `<div class="insp-linked-item"><b>${escapeHtml(m.name)}</b><small>مطلوب ${m.qty} / متاح ${m.available}</small></div>`).join('') || '<p>لا يوجد نقص مواد</p>'}</div>
    <div class="insp-section"><h4>المكائن</h4>${result.machines.map(m => `<div class="insp-linked-item"><b>${escapeHtml(m.name)}</b><small>${escapeHtml(translateMachineStatus(m.status))} / طابور ${getMachineQueueCount(m)}</small></div>`).join('') || '<p>لا توجد مكائن مطلوبة</p>'}</div>
    <div class="insp-section"><h4>SOPs</h4>${result.sops.map(s => `<div class="insp-linked-item"><b>${escapeHtml(s.title)}</b><small>${escapeHtml(s.code || '')}</small></div>`).join('') || '<p>No SOPs linked</p>'}</div>
    <div class="insp-section"><h4>تحذيرات</h4>${result.routingWarnings.map(w => `<div class="insp-linked-item"><b>${escapeHtml(w.text || w.type)}</b></div>`).join('') || '<p>لا توجد تحذيرات مسار</p>'}</div>
    <div class="insp-actions"><button class="btn-primary" onclick="runWorkflowSimulation()"><i class="fa-solid fa-play"></i> اختبار وفحص العملية</button></div>
  `;
}

function workflowNodeFieldChanged(nodeId, field, value, logText) {
  const patch = {};
  patch[field] = field === 'estimatedMinutes' || field === 'costImpact' ? Number(value) || 0 : value;
  updateWorkflowNode(nodeId, patch);
  addWorkflowNodeActivity(nodeId, logText);
  saveData();
  openWorkflowNodeInspector(nodeId, 0);
}

function workflowNodeSelectChanged(nodeId, field, value, logText) {
  if (isWorkflowReadOnly()) {
    showToast('العملية منشورة وحالياً للقراءة فقط. يرجى إلغاء النشر للتعديل عليها.', 'warning');
    return;
  }
  const node = getWorkflowNodeById(nodeId);
  if (!node) return;
  if ((field === 'successPath' || field === 'failurePath') && value === nodeId) return showToast('A node cannot route to itself', 'warning');
  node[field] = value;
  addWorkflowNodeActivity(nodeId, logText);
  saveData();
  renderWorkflowStudio();
  openWorkflowNodeInspector(nodeId, field === 'successPath' || field === 'failurePath' ? 3 : 1);
}

function addWorkflowNodeMaterial(nodeId) {
  if (isWorkflowReadOnly()) {
    showToast('العملية منشورة وحالياً للقراءة فقط. يرجى إلغاء النشر للتعديل عليها.', 'warning');
    return;
  }
  const node = getWorkflowNodeById(nodeId);
  const materialId = document.getElementById('workflowMaterialSelect')?.value;
  if (!node || !materialId) return;
  const material = getMaterialById(materialId);
  const qty = Number(document.getElementById('workflowMaterialQty')?.value) || 1;
  const unit = document.getElementById('workflowMaterialUnit')?.value || material?.unit || '';
  node.materialRequirements.push({ materialId, qty, unit });
  addWorkflowNodeActivity(nodeId, `Material added: ${material?.name || materialId}`);
  saveData();
  renderWorkflowStudio();
  openWorkflowNodeInspector(nodeId, 2);
}

function removeWorkflowNodeMaterial(nodeId, idx) {
  if (isWorkflowReadOnly()) {
    showToast('العملية منشورة وحالياً للقراءة فقط. يرجى إلغاء النشر للتعديل عليها.', 'warning');
    return;
  }
  const node = getWorkflowNodeById(nodeId);
  if (!node || !node.materialRequirements?.[idx]) return;
  const req = node.materialRequirements[idx];
  const material = getMaterialById(req.materialId);
  node.materialRequirements.splice(idx, 1);
  addWorkflowNodeActivity(nodeId, `Material removed: ${material?.name || req.materialId}`);
  saveData();
  renderWorkflowStudio();
  openWorkflowNodeInspector(nodeId, 2);
}

function buildWorkflowExecutionPreview(workflow = omni.workflow) {
  const nodes = [...(workflow.nodes || [])].sort((a, b) => (Number(a.x) || 0) - (Number(b.x) || 0) || (Number(a.y) || 0) - (Number(b.y) || 0));
  const sops = nodes.map(n => getSopById(n.linkedSopId)).filter(Boolean);
  const machines = nodes.map(n => getMachineById(n.linkedMachineId)).filter(Boolean);
  const materialsMap = {};
  nodes.forEach(node => (node.materialRequirements || []).forEach(req => {
    const mat = getMaterialById(req.materialId);
    const key = req.materialId || 'missing';
    if (!materialsMap[key]) materialsMap[key] = { materialId: key, name: mat?.name || key, qty: 0, unit: req.unit || mat?.unit || '', available: mat ? getMaterialAvailableQty(mat) : 0 };
    materialsMap[key].qty += getMaterialRequirementQty(req);
  }));
  const materials = Object.values(materialsMap);
  return {
    steps: nodes,
    sops,
    machines,
    materials,
    estimatedMinutes: nodes.reduce((sum, n) => sum + (Number(n.estimatedMinutes) || 0), 0),
    estimatedCost: nodes.reduce((sum, n) => sum + (Number(n.costImpact) || 0), 0),
    bottlenecks: machines.filter(m => getMachineQueueCount(m) > 3 || /maintenance|offline|down|صيانة|متوقفة/i.test(String(m.status || ''))),
    missingLinks: validateWorkflowDeep(workflow).warnings.concat(validateWorkflowDeep(workflow).errors),
    expectedCards: nodes.map(n => ({ title: n.title, sopIds: n.linkedSopId ? [n.linkedSopId] : [], machineIds: n.linkedMachineId ? [n.linkedMachineId] : [] }))
  };
}

